function applyBackground(index)
  customBgSelected = nil
  currentBackground = (tonumber(index) and tonumber(index) >= 1) and tonumber(index) or 1
  -- K2 grey redesign: never show purple wallpaper images
  BgImage.Visible = false
  BgImage.ImageTransparency = 1
  MiniBg.ImageTransparency = 1
  Main.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
  MiniFrame.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
  local id = BackgroundIDs[currentBackground]
  if id then
    -- keep ids for settings preview only; do not display on Main
    BgImage.Image = "rbxassetid://" .. id
    BgImage.Visible = false
    MiniBg.Image = "rbxassetid://" .. id
    saveAmbitiousConfig()
    -- Aggiorna preview custom bg row se esiste
    if _G.AmbitiousCustomBgPreviewUpdate then pcall(_G.AmbitiousCustomBgPreviewUpdate) end
    _G._AmbitiousBgIndex = currentBackground
    _G._AmbitiousBgCustom = false
    if _G._AmbitiousApplyAccent then pcall(_G._AmbitiousApplyAccent) end
    return "Image " .. tostring(currentBackground)
  end
  currentBackground = 1
  local fallback = BackgroundIDs[1]
  if fallback then
    BgImage.Image = "rbxassetid://" .. fallback
    BgImage.Visible = true
    MiniBg.Image = "rbxassetid://" .. fallback
  end
  saveAmbitiousConfig()
  if _G.AmbitiousCustomBgPreviewUpdate then pcall(_G.AmbitiousCustomBgPreviewUpdate) end
  _G._AmbitiousBgIndex = currentBackground
  _G._AmbitiousBgCustom = false
  if _G._AmbitiousApplyAccent then pcall(_G._AmbitiousApplyAccent) end
  return "Image 1"
end

function applyCustomBackground(assetId)
  customBgSelected = assetId
  currentBackground = 0
  BgImage.Image = "rbxassetid://" .. assetId
  BgImage.Visible = false
  BgImage.ImageTransparency = 1
  MiniBg.Image = "rbxassetid://" .. assetId
  MiniBg.ImageTransparency = 1
  Main.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
  saveAmbitiousConfig()
  if _G.AmbitiousCustomBgPreviewUpdate then pcall(_G.AmbitiousCustomBgPreviewUpdate) end
  _G._AmbitiousBgIndex = 0
  _G._AmbitiousBgCustom = true
  if _G._AmbitiousApplyAccent then pcall(_G._AmbitiousApplyAccent) end
  -- Deseleziona i 4 built-in buttons
  if updateBackgroundButtons then pcall(updateBackgroundButtons) end
end

if customBgSelected and customBgSelected ~= "" then
  applyCustomBackground(customBgSelected)
else
  applyBackground(currentBackground)
end
_G._AmbitiousBgIndex = currentBackground
_G._AmbitiousBgCustom = (customBgSelected ~= nil and customBgSelected ~= "")
if _G._AmbitiousApplyAccent then pcall(_G._AmbitiousApplyAccent) end

