corner(Close, 8)
stroke(Close, COLORS.stroke, 1, 0.35)

AmbitiousLockTopButton = Instance.new("TextButton")
AmbitiousLockTopButton.Name = "LockGUI"
AmbitiousLockTopButton.BackgroundColor3 = Color3.fromRGB(20, 17, 34)
AmbitiousLockTopButton.BackgroundTransparency = 0.1
AmbitiousLockTopButton.TextColor3 = COLORS.white
AmbitiousLockTopButton.TextSize = 8
AmbitiousLockTopButton.Font = Enum.Font.GothamBlack
AmbitiousLockTopButton.Size = UDim2.new(0, 32, 0, 28)
AmbitiousLockTopButton.Position = UDim2.new(0, 12, 0, 10)   -- spostato a sinistra
AmbitiousLockTopButton.AutoButtonColor = false
AmbitiousLockTopButton.ZIndex = 5
AmbitiousLockTopButton.Parent = Main
corner(AmbitiousLockTopButton, 8)
stroke(AmbitiousLockTopButton, COLORS.stroke, 1, 0.35)

function AmbitiousUpdateGuiLockVisual()
  if AmbitiousLockTopButton then
    AmbitiousLockTopButton.Text = (_G.AmbitiousGuiLocked == true) and "UNLOCK" or "LOCK"
    AmbitiousLockTopButton.BackgroundTransparency = (_G.AmbitiousGuiLocked == true) and 0.08 or 0.28
    local st = AmbitiousLockTopButton:FindFirstChildOfClass("UIStroke")
    if st then
      st.Transparency = (_G.AmbitiousGuiLocked == true) and 0.08 or 0.35
      st.Color = (_G.AmbitiousGuiLocked == true) and Color3.fromRGB(255,255,255) or COLORS.stroke
    end
  end
  if setLockGuiVisual then pcall(setLockGuiVisual, _G.AmbitiousGuiLocked == true) end
end

AmbitiousLockTopButton.Activated:Connect(function()
  _G.AmbitiousGuiLocked = not (_G.AmbitiousGuiLocked == true)
  AmbitiousUpdateGuiLockVisual()
  saveAmbitiousConfig()
end)
AmbitiousUpdateGuiLockVisual()

local Content = Instance.new("Frame")
Content.Name = "Content"
Content.BackgroundTransparency = 1
Content.Position = UDim2.new(0, 13, 0, 104)
Content.Size = UDim2.new(1, -26, 1, -137)
Content.ZIndex = 3
Content.Parent = Main

local Tabs = Instance.new("Frame")
Tabs.Name = "Tabs"
Tabs.BackgroundTransparency = 1
Tabs.Position = UDim2.new(0, 12, 0, 64)
Tabs.Size = UDim2.new(1, -24, 0, 34)
Tabs.ZIndex = 3
Tabs.Parent = Main

local TabLayout = Instance.new("UIListLayout")
TabLayout.FillDirection = Enum.FillDirection.Horizontal
TabLayout.Padding = UDim.new(0, 5)
TabLayout.SortOrder = Enum.SortOrder.LayoutOrder
TabLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
TabLayout.Parent = Tabs

local pages = {}
local tabButtons = {}
local tabNames = {"MOVEMENT", "COMBAT", "KEYBINDS", "VISUALS", "SETTINGS"}
local activeTab = "MOVEMENT"

function addPage(name)
  local page = Instance.new("ScrollingFrame")
  page.Name = name
  page.BackgroundTransparency = 1
  page.BorderSizePixel = 0
  page.ScrollBarThickness = 0
  page.ScrollBarImageTransparency = 1
  page.CanvasSize = UDim2.new(0, 0, 0, 0)
  page.AutomaticCanvasSize = Enum.AutomaticSize.Y
  page.Size = UDim2.new(1, 0, 1, 0)
  page.ZIndex = 3
  page.Visible = false
  page.Parent = Content
  local layout = Instance.new("UIListLayout")
  layout.Padding = UDim.new(0, 7)
  layout.SortOrder = Enum.SortOrder.LayoutOrder
  layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
  layout.Parent = page
  local pagePadding = Instance.new("UIPadding")
  pagePadding.Name = "PagePad"
  pagePadding.PaddingBottom = UDim.new(0, 12)
  pagePadding.Parent = page
  pages[name] = page
  if _G._AmbitiousApplyPagePadding then _G._AmbitiousApplyPagePadding() end
  return page
end

-- >>> PAGE PADDING PER POSIZIONE TAB BEGIN
-- Il respiro sopra e sotto le righe dipende da dove stanno le tab:
--   Up     -> sopra ci sono le tab, sotto serve il margine
--   Bottom -> sotto ci sono le tab, sopra serve il margine
--   Left/Right -> le tab sono di lato, quindi serve sia sopra che sotto
-- Prima era fisso (solo 12 sotto per tutti) e su Left/Right l'ultima riga
-- finiva incollata al bordo inferiore.
_G._AmbitiousApplyPagePadding = function()
  local mode = _G._AmbitiousTabPosition or "Up"
  local top, bottom
  if mode == "Up" then
    top, bottom = 0, 12
  elseif mode == "Bottom" then
    top, bottom = 10, 0
  else
    -- Left/Right: stesso margine di Up sotto, piu' il pizzico d'aria sopra
    top, bottom = 10, 12
  end
  for _, page in pairs(pages) do
    local pad = page:FindFirstChild("PagePad")
    if pad then
      pad.PaddingTop    = UDim.new(0, top)
      pad.PaddingBottom = UDim.new(0, bottom)
    end
  end
end
-- <<< PAGE PADDING PER POSIZIONE TAB END

function setTab(name)
  activeTab = name
  for pageName, page in pairs(pages) do
    page.Visible = pageName == name
  end
  for tabName, btn in pairs(tabButtons) do
    local on = tabName == name
    btn.TextColor3 = on and COLORS.white or COLORS.muted
    btn.BackgroundColor3 = on and Color3.fromRGB(30, 26, 50) or Color3.fromRGB(11, 10, 20)
    btn.BackgroundTransparency = on and 0.05 or 0.35
    local st = btn:FindFirstChildOfClass("UIStroke")
    if st then
      st.Transparency = on and 0.25 or 0.55
      st.Color = on and Color3.fromRGB(200, 200, 210) or COLORS.line
    end
  end
end

for _, name in ipairs(tabNames) do
  addPage(name)
  local btn = Instance.new("TextButton")
  btn.Name = name
  btn.Size = UDim2.new(0, 54, 0, 34)   -- ridotto per entrare
  btn.BackgroundColor3 = Color3.fromRGB(11, 10, 20)
  btn.BackgroundTransparency = 0.35
  btn.BorderSizePixel = 0
  btn.Text = name
  btn.TextColor3 = COLORS.muted
  btn.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
  btn.TextStrokeTransparency = 0.35
  btn.TextSize = 8
  btn.Font = Enum.Font.GothamBlack
  btn.AutoButtonColor = false
  btn.ZIndex = 4
  btn.Parent = Tabs
  corner(btn, 7)
  stroke(btn, COLORS.stroke, 1, 0.52)
  tabButtons[name] = btn
  btn.MouseButton1Click:Connect(function()
    setTab(name)
  end)
end

-- >>> TAB POSITION BEGIN
-- ============================================================
-- POSIZIONE DELLE TAB
-- Riposiziona la barra delle tab e ridimensiona il Content di conseguenza.
-- Main e' 324 x 576; l'header arriva a y=88, quindi tutte e quattro le
-- disposizioni partono da y=97 in giu'.
-- IIFE e non do-end: un do-end NON apre un nuovo budget di registri e qui
-- il main chunk e' gia' vicino al limite di 200.
-- ============================================================
;(function()
  local H = Enum.FillDirection.Horizontal
  local V = Enum.FillDirection.Vertical

  -- Larghezze della finestra. In Left/Right la colonna delle tab si prende
  -- spazio a lato, e se Main restasse a 324 il Content si stringerebbe di
  -- una sessantina di pixel: le row hanno i bottoni posizionati con offset
  -- assoluti dal bordo destro, quindi si sovrappongono alle label e finiscono
  -- tagliati. Per questo la finestra si allarga: il Content resta a 298 di
  -- larghezza in tutte e quattro le disposizioni, e dentro le pagine non
  -- cambia assolutamente niente.
  local W_NARROW = 324   -- Up / Bottom
  local W_WIDE   = 359   -- Left / Right (324 + 35 di colonna)
  -- Col testo ruotato la colonna deve contenere solo l'ALTEZZA di una riga
  -- di testo, non la larghezza di una lettera: 30 bastano e avanzano.
  local BAR_W    = 30    -- larghezza della colonna verticale

  local LAYOUTS = {
    Up = {
      wide       = false,
      tabsPos    = UDim2.new(0, 12, 0, 64),
      tabsSize   = UDim2.new(1, -24, 0, 34),
      dir        = H,
      pad        = UDim.new(0, 5),
      hAlign     = Enum.HorizontalAlignment.Center,
      vAlign     = Enum.VerticalAlignment.Center,
      contentPos = UDim2.new(0, 13, 0, 104),
      contentSize= UDim2.new(1, -26, 1, -112),
    },
    Bottom = {
      wide       = false,
      tabsPos    = UDim2.new(0, 12, 1, -46),
      tabsSize   = UDim2.new(1, -24, 0, 34),
      dir        = H,
      pad        = UDim.new(0, 5),
      hAlign     = Enum.HorizontalAlignment.Center,
      vAlign     = Enum.VerticalAlignment.Center,
      contentPos = UDim2.new(0, 13, 0, 97),
      contentSize= UDim2.new(1, -26, 1, -153),
    },
    Left = {
      wide       = true,
      tabsPos    = UDim2.new(0, 10, 0, 97),
      tabsSize   = UDim2.new(0, BAR_W, 1, -109),
      dir        = V,
      pad        = UDim.new(0, 3),
      hAlign     = Enum.HorizontalAlignment.Center,
      -- Centrata, non incollata in alto: le cinque tab occupano circa 430
      -- dei 467 pixel della colonna, e da Top lasciavano tutto il vuoto in
      -- fondo. Da Center il margine si divide sopra e sotto.
      vAlign     = Enum.VerticalAlignment.Center,
      rot        = -90,   -- a sinistra si legge dal basso verso l'alto
      -- L'area contenuti arriva in fondo come con le tab in alto: con -109
      -- si fermava 12px prima e l'ultima riga restava sospesa a mezz'aria.
      contentPos = UDim2.new(0, 48, 0, 97),
      contentSize= UDim2.new(1, -61, 1, -96),
    },
    Right = {
      wide       = true,
      tabsPos    = UDim2.new(1, -40, 0, 97),
      tabsSize   = UDim2.new(0, BAR_W, 1, -109),
      dir        = V,
      pad        = UDim.new(0, 3),
      hAlign     = Enum.HorizontalAlignment.Center,
      vAlign     = Enum.VerticalAlignment.Center,
      rot        = 90,    -- a destra si legge dall'alto verso il basso
      contentPos = UDim2.new(0, 13, 0, 97),
      contentSize= UDim2.new(1, -61, 1, -96),
    },
  }

  -- ============================================================
  -- TESTO RUOTATO
  -- ============================================================
  -- Una sola TextLabel per tab, con la parola scritta NORMALE e poi
  -- ruotata di 90 gradi. Le lettere stanno su un'unica linea di base con
  -- la crenatura decisa dal font, quindi non c'e' niente da allineare:
  -- e' dritto per costruzione, non per correzione. Tutti i tentativi
  -- precedenti impilavano una label per lettera, e li' ogni glifo veniva
  -- centrato per conto suo con il suo arrotondamento.
  --
  -- Il verso segue la convenzione delle sidebar:
  --   Left  -> -90, si legge dal basso verso l'alto
  --   Right -> +90, si legge dall'alto verso il basso
  local LETTER_FONT = Enum.Font.GothamBlack
  local WORD_SIZE   = 15   -- TextSize della parola
  local WORD_PAD    = 14   -- aria sopra e sotto, nel senso della colonna

  -- La rotazione NON cambia lo spazio che l'oggetto occupa nel layout:
  -- il bottone va quindi alto quanto la parola e' LARGA da orizzontale.
  local TextServiceRef = game:GetService("TextService")
  local wordLenCache = {}
  local function wordLength(word)
    local n = wordLenCache[word]
    if not n then
      local ok, sz = pcall(function()
        return TextServiceRef:GetTextSize(word, WORD_SIZE, LETTER_FONT, Vector2.new(4000, 100))
      end)
      n = (ok and sz and math.ceil(sz.X)) or (#word * WORD_SIZE * 0.62)
      wordLenCache[word] = n
    end
    return n
  end

  local function buildWord(btn, name, rot)
    local lbl = btn:FindFirstChild("VWord")
    if lbl and lbl:GetAttribute("Word") == name and lbl.Rotation == rot then
      return lbl
    end
    if lbl then lbl:Destroy() end

    local len = wordLength(name)

    lbl = Instance.new("TextLabel")
    lbl.Name = "VWord"
    lbl.BackgroundTransparency = 1
    lbl.Text = name
    lbl.Font = LETTER_FONT
    lbl.TextSize = WORD_SIZE
    lbl.TextXAlignment = Enum.TextXAlignment.Center
    lbl.TextYAlignment = Enum.TextYAlignment.Center
    lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    lbl.TextStrokeTransparency = 0.35
    lbl.TextWrapped = false
    -- Dimensioni da orizzontale; ruotando, la larghezza diventa l'altezza.
    lbl.Size = UDim2.new(0, len, 0, WORD_SIZE + 6)
    lbl.AnchorPoint = Vector2.new(0.5, 0.5)
    lbl.Position = UDim2.new(0.5, 0, 0.5, 0)
    lbl.Rotation = rot
    lbl.ZIndex = 5
    lbl:SetAttribute("Word", name)
    lbl.Parent = btn
    return lbl
  end

  -- Le lettere non ereditano il colore dal bottone: va propagato a mano
  -- ogni volta che setTab cambia lo stato attivo.
  local function syncLetters()
    for _, btn in pairs(tabButtons) do
      local lbl = btn:FindFirstChild("VWord")
      if lbl and lbl.Visible then lbl.TextColor3 = btn.TextColor3 end
    end
  end
  _G._AmbitiousSyncTabLetters = syncLetters

  function _G.AmbitiousApplyTabPosition(pos)
    pos = _G.AmbitiousValidTabPosition(pos)
    local L = LAYOUTS[pos]
    if not L then return end
    _G._AmbitiousTabPosition = pos

    -- La finestra si allarga/restringe. FULL_MAIN_SIZE e' la misura che tutti
    -- i ripristini della hub usano (minimize, intro, duels), quindi va
    -- aggiornata anche lei: altrimenti al primo ripristino tornerebbe stretta
    -- con le tab ancora di lato.
    FULL_MAIN_SIZE = UDim2.new(0, L.wide and W_WIDE or W_NARROW, 0, 576)
    Main.Size = FULL_MAIN_SIZE

    Tabs.Position = L.tabsPos
    Tabs.Size     = L.tabsSize

    TabLayout.FillDirection       = L.dir
    TabLayout.Padding             = L.pad
    TabLayout.HorizontalAlignment = L.hAlign
    TabLayout.VerticalAlignment   = L.vAlign

    for name, btn in pairs(tabButtons) do
      -- Padding interno riusato tra un cambio di modalita' e l'altro.
      local pad = btn:FindFirstChild("TabPad")
      if not pad then
        pad = Instance.new("UIPadding")
        pad.Name = "TabPad"
        pad.Parent = btn
      end

      if L.dir == V then
        -- Il bottone non scrive niente: il testo e' la label ruotata.
        -- Alto quanto la parola e' larga da orizzontale, piu' l'aria.
        btn.Text = ""
        btn.AutomaticSize = Enum.AutomaticSize.None
        pad.PaddingTop    = UDim.new(0, 0)
        pad.PaddingBottom = UDim.new(0, 0)
        btn.Size = UDim2.new(1, 0, 0, wordLength(name) + WORD_PAD)
        local lbl = buildWord(btn, name, L.rot or 90)
        lbl.Visible = true
      else
        btn.AutomaticSize = Enum.AutomaticSize.None
        local lbl = btn:FindFirstChild("VWord")
        if lbl then lbl.Visible = false end
        btn.Text = name
        btn.TextSize = 8
        btn.TextWrapped = false
        btn.TextXAlignment = Enum.TextXAlignment.Center
        btn.TextYAlignment = Enum.TextYAlignment.Center
        pad.PaddingTop    = UDim.new(0, 0)
        pad.PaddingBottom = UDim.new(0, 0)
        btn.Size = UDim2.new(0, 54, 0, 34)
      end
    end

    Content.Position = L.contentPos
    Content.Size     = L.contentSize

    -- >>> PAGE PADDING <<< il respiro sopra/sotto cambia col lato delle tab
    if _G._AmbitiousApplyPagePadding then _G._AmbitiousApplyPagePadding() end

    syncLetters()
  end
end)()

-- setTab colora i bottoni ma non sa delle lettere: si aggancia qui.
do
  local _oldSetTab = setTab
  function setTab(name)
    _oldSetTab(name)
    if _G._AmbitiousSyncTabLetters then _G._AmbitiousSyncTabLetters() end
  end
end

-- Applica quello caricato dal config (o il default "Up").
_G.AmbitiousApplyTabPosition(_G._AmbitiousTabPosition)
-- <<< TAB POSITION END

function section(parent, text, order)
  local label = Instance.new("TextLabel")
  label.Name = text
  label.BackgroundTransparency = 1
  label.Text = text
  label.TextColor3 = COLORS.accent
  label.TextStrokeTransparency = 1
  label.TextSize = 10
  label.Font = Enum.Font.GothamBold
  label.TextXAlignment = Enum.TextXAlignment.Left
  label.Size = UDim2.new(1, -6, 0, 15)
  label.LayoutOrder = order
  label.ZIndex = 8
  label.Parent = parent
  return label
end

function baseRow(parent, labelText, order)
  -- K2 LTM-style card row
  local row = Instance.new("Frame")
  row.Name = labelText
  row.BackgroundColor3 = COLORS.row
  row.BackgroundTransparency = 0.12
  row.Size = UDim2.new(1, -4, 0, 40)
  row.BorderSizePixel = 0
  row.LayoutOrder = order
  row.ZIndex = 4
  row.Parent = parent
  corner(row, 10)
  local edge = stroke(row, COLORS.line, 1, 0.55)
  local label = Instance.new("TextLabel")
  label.Name = "Label"
  label.BackgroundTransparency = 1
  label.Text = labelText
  label.TextColor3 = COLORS.white
  label.TextStrokeTransparency = 1
  label.TextSize = 12
  label.Font = Enum.Font.GothamBold
  label.TextXAlignment = Enum.TextXAlignment.Left
  label.Position = UDim2.new(0, 12, 0, 0)
  label.Size = UDim2.new(1, -132, 1, 0)
  label.ZIndex = 5
  label.Parent = row
  row.MouseEnter:Connect(function()
    if edge then tween(edge, {Color = COLORS.accent, Transparency = 0.25}) end
    tween(row, {BackgroundTransparency = 0.05})
  end)
  row.MouseLeave:Connect(function()
    if edge then tween(edge, {Color = COLORS.line, Transparency = 0.55}) end
    tween(row, {BackgroundTransparency = 0.12})
  end)
  return row
end

function textboxRow(parent, labelText, value, order)
  local row = baseRow(parent, labelText, order)
  local box = Instance.new("TextBox")
  box.Name = "ValueBox"
  box.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
  box.BackgroundTransparency = 0.18
  box.Text = tostring(value or "")
  box.TextColor3 = COLORS.white
  box.TextSize = 12
  box.Font = Enum.Font.GothamSemibold
  box.ClearTextOnFocus = false
  box.Size = UDim2.new(0, 58, 0, 24)
  box.Position = UDim2.new(1, -68, 0.5, -12)
  box.BorderSizePixel = 0
  box.ZIndex = 6
  box.Parent = row
  corner(box, 7)
  stroke(box, COLORS.strokeSoft, 1, 0.45)
  return row, box
end

function toggleRow(parent, labelText, default, order)
  local row = baseRow(parent, labelText, order)
  local button = Instance.new("TextButton")
  button.Name = "ToggleButton"
  button.BackgroundTransparency = 1
  button.Text = ""
  button.Size = UDim2.new(1, 0, 1, 0)
  button.Position = UDim2.new(0, 0, 0, 0)
  button.AutoButtonColor = false
  button.ZIndex = 7
  button.Parent = row
  local track = Instance.new("Frame")
  track.Name = "Track"
  track.BackgroundColor3 = COLORS.toggleBg
  track.BackgroundTransparency = 0.12
  track.Size = UDim2.new(0, 44, 0, 22)
  track.Position = UDim2.new(1, -54, 0.5, -11)
  track.BorderSizePixel = 0
  track.ClipsDescendants = false
  track.ZIndex = 5
  track.Parent = button
  corner(track, 11)
  stroke(track, COLORS.strokeSoft, 1.3, 0.4)

  -- LTM grey fill when toggle on
  local fill = Instance.new("Frame")
  fill.Name = "Fill"
  fill.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
  fill.BackgroundTransparency = default and 0 or 1
  fill.Size = UDim2.new(1, 0, 1, 0)
  fill.BorderSizePixel = 0
  fill.ZIndex = 5
  fill.Parent = track
  corner(fill, 11)
  local fillGrad = Instance.new("UIGradient")
  fillGrad.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
  })
  fillGrad.Rotation = 18
  fillGrad.Parent = fill

  local knob = Instance.new("Frame")
  knob.Name = "Knob"
  knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
  knob.Size = UDim2.new(0, 16, 0, 16)
  knob.Position = default and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)
  knob.BorderSizePixel = 0
  knob.ZIndex = 7
  knob.Parent = track
  corner(knob, 999)
  local knobStroke = Instance.new("UIStroke")
  knobStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  knobStroke.Color = default and Color3.fromRGB(200, 200, 210) or Color3.fromRGB(120, 120, 135)
  knobStroke.Thickness = 1.4
  knobStroke.Transparency = 0.15
  knobStroke.Parent = knob
  local shine = Instance.new("Frame")
  shine.Name = "Shine"
  shine.BackgroundColor3 = COLORS.white
  shine.BackgroundTransparency = 0.55
  shine.Size = UDim2.new(1, -5, 0, 5)
  shine.Position = UDim2.new(0, 2.5, 0, 2.5)
  shine.BorderSizePixel = 0
  shine.ZIndex = 8
  shine.Parent = knob
  corner(shine, 5)
  _G._AmbitiousRegAccent(fill, fillGrad, "toggle", track, knob, row)
  local state = default and true or false
  local trackStroke = track:FindFirstChildOfClass("UIStroke")
  local rowStroke = row:FindFirstChildOfClass("UIStroke")
  local function setVisual(on)
    state = on and true or false
    tween(knob, {Position = state and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)})
    local _onBg, _onEdge = _G._AmbitiousToggleOnColor()
    tween(track, {
      BackgroundTransparency = state and 0 or 0.12,
      BackgroundColor3 = state and _onBg or COLORS.toggleBg
    })
    tween(fill, { BackgroundTransparency = state and 0 or 1 })
    tween(knobStroke, {
      Color = state and _onEdge or Color3.fromRGB(120, 120, 135)
    })
    if trackStroke then
      tween(trackStroke, {
        Color = state and _onEdge or COLORS.strokeSoft,
        Transparency = state and 0 or 0.4,
        Thickness = 1.4
      })
    end
    if rowStroke then
      tween(rowStroke, {
        Color = state and _onBg or COLORS.strokeSoft,
        Transparency = state and 0.08 or 0.38,
        Thickness = 1.25
      })
    end
  end
  setVisual(state)
  button.Activated:Connect(function() end)
  return row, setVisual
end

_G.AmbitiousSyncToggleVisuals = function()
  pcall(function() if setAutoStealVisual then setAutoStealVisual(autoStealEnabled == true) end end)
  pcall(function() if _G._AmbitiousSyncAfterHit.setVisual then _G._AmbitiousSyncAfterHit.setVisual(_G._AmbitiousSyncAfterHit.enabled == true) end end)
  pcall(function() if setInfJumpVisual then setInfJumpVisual(infJumpEnabled == true) end end)
  pcall(function() if _SV.setLookAtVisual then _SV.setLookAtVisual(_G.AmbitiousLookAtEnabled == true) end end)
  pcall(function() if setAntiRagdollVisual then setAntiRagdollVisual(antiRagdollEnabled == true) end end)
  pcall(function() if setAutoCarrySpeedVisual then setAutoCarrySpeedVisual(autoCarrySpeedEnabled == true) end end)
  pcall(function() if _G.AmbitiousRefreshAutoCarryModeSelector then _G.AmbitiousRefreshAutoCarryModeSelector() end end)
  pcall(function() if _SV.setAutoTPVisual then _SV.setAutoTPVisual(autoTPEnabled == true) end end)
end

_G.AmbitiousActionToggleRow = function(parent, labelText, default, order)
  local row = baseRow(parent, labelText, order)
  local button = Instance.new("TextButton")
  button.Name = "ToggleButton"
  button.BackgroundTransparency = 1
  button.Text = ""
  button.Size = UDim2.new(1, 0, 1, 0)
  button.Position = UDim2.new(0, 0, 0, 0)
  button.AutoButtonColor = false
  button.ZIndex = 7
  button.Parent = row
  local track = Instance.new("Frame")
  track.Name = "Track"
  track.BackgroundColor3 = COLORS.toggleBg
  track.BackgroundTransparency = 0.12
  track.Size = UDim2.new(0, 44, 0, 22)
  track.Position = UDim2.new(1, -54, 0.5, -11)
  track.BorderSizePixel = 0
  track.ClipsDescendants = false
  track.ZIndex = 5
  track.Parent = button
  corner(track, 11)
  stroke(track, COLORS.strokeSoft, 1.3, 0.4)

  -- LTM grey fill when toggle on
  local fill = Instance.new("Frame")
  fill.Name = "Fill"
  fill.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
  fill.BackgroundTransparency = default and 0 or 1
  fill.Size = UDim2.new(1, 0, 1, 0)
  fill.BorderSizePixel = 0
  fill.ZIndex = 5
  fill.Parent = track
  corner(fill, 11)
  local fillGrad = Instance.new("UIGradient")
  fillGrad.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
  })
  fillGrad.Rotation = 18
  fillGrad.Parent = fill

  local knob = Instance.new("Frame")
  knob.Name = "Knob"
  knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
  knob.Size = UDim2.new(0, 16, 0, 16)
  knob.Position = default and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)
  knob.BorderSizePixel = 0
  knob.ZIndex = 7
  knob.Parent = track
  corner(knob, 999)
  local knobStroke = Instance.new("UIStroke")
  knobStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  knobStroke.Color = default and Color3.fromRGB(200, 200, 210) or Color3.fromRGB(120, 120, 135)
  knobStroke.Thickness = 1.4
  knobStroke.Transparency = 0.15
  knobStroke.Parent = knob
  local shine = Instance.new("Frame")
  shine.Name = "Shine"
  shine.BackgroundColor3 = COLORS.white
  shine.BackgroundTransparency = 0.55
  shine.Size = UDim2.new(1, -5, 0, 5)
  shine.Position = UDim2.new(0, 2.5, 0, 2.5)
  shine.BorderSizePixel = 0
  shine.ZIndex = 8
  shine.Parent = knob
  corner(shine, 5)
  _G._AmbitiousRegAccent(fill, fillGrad, "toggle", track, knob, row)
  local trackStroke = track:FindFirstChildOfClass("UIStroke")
  local rowStroke = row:FindFirstChildOfClass("UIStroke")
  local function setVisual(on)
    local state = on and true or false
    tween(knob, {Position = state and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)})
    local _onBg, _onEdge = _G._AmbitiousToggleOnColor()
    tween(track, {
      BackgroundTransparency = state and 0 or 0.12,
      BackgroundColor3 = state and _onBg or COLORS.toggleBg
    })
    tween(fill, { BackgroundTransparency = state and 0 or 1 })
    tween(knobStroke, {
      Color = state and _onEdge or Color3.fromRGB(120, 120, 135)
    })
    if trackStroke then
      tween(trackStroke, {
        Color = state and _onEdge or COLORS.strokeSoft,
        Transparency = state and 0 or 0.4,
        Thickness = 1.4
      })
    end
    if rowStroke then
      tween(rowStroke, {
        Color = state and _onBg or COLORS.strokeSoft,
        Transparency = state and 0.08 or 0.38,
        Thickness = 1.25
      })
    end
  end
  setVisual(default)
  return row, setVisual, button
end

function dropdownRow(parent, labelText, value, order)
  local row = baseRow(parent, labelText, order)
  local select = Instance.new("TextButton")
  select.Name = "Dropdown"
