    t.ZIndex = 8
    t.Parent = adHolder
    adTexts[i] = t
  end

  -- L'etichetta di sinistra porta la versione dell'aimbot selezionata,
  -- come fa il bottone mobile: la fonte e' la stessa variabile, quindi
  -- non possono divergere.
  local function adApplyVisual()
    local idx = (_G.AmbitiousAfterDrop.action == "TPBAT") and 2 or 1
    adTexts[1].Text = "BAT AIMBOT " .. ((selectedAimbotMode == "V2") and "V2" or "V1")
    adTexts[2].Text = "TP BAT"
    tween(adSlide, {Position = UDim2.new(0.5 * (idx - 1), 4, 0, 4)}, 0.18)
    for i, t in ipairs(adTexts) do
      local sel = (i == idx)
      tween(t, {
        TextTransparency = sel and 0 or 0.5,
        TextStrokeTransparency = sel and 0.2 or 0.38,
      }, 0.14)
    end
    if setADVisual then pcall(setADVisual, _G.AmbitiousAfterDrop.enabled == true) end
  end
  _G.AmbitiousRefreshAfterDropSelector = adApplyVisual

  for i, mode in ipairs(AD_MODES) do
    local b = Instance.new("TextButton")
    b.BackgroundTransparency = 1
    b.Text = ""
    b.AutoButtonColor = false
    b.Size = UDim2.new(0.5, 0, 1, 0)
    b.Position = UDim2.new(0.5 * (i - 1), 0, 0, 0)
    b.ZIndex = 10
    b.Parent = adHolder
    b.MouseButton1Click:Connect(function()
      _G.AmbitiousAfterDrop.action = mode
      adApplyVisual()
      saveAmbitiousConfig()
    end)
  end

  local adArrow = Instance.new("TextButton")
  adArrow.Name = "AutoAfterDropArrow"
  adArrow.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
  adArrow.BackgroundTransparency = 0.18
  adArrow.BorderSizePixel = 0
  adArrow.Size = UDim2.new(0, 28, 0, 24)
  adArrow.Position = UDim2.new(1, -90, 0.5, -12)
  adArrow.Text = "\u{25B2}"
  adArrow.TextColor3 = COLORS.white
  adArrow.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
  adArrow.TextStrokeTransparency = 0.3
  adArrow.TextSize = 15
  adArrow.Font = Enum.Font.GothamBold
  adArrow.AutoButtonColor = false
  adArrow.ZIndex = 8
  adArrow.Parent = adRow
  corner(adArrow, 7)
  stroke(adArrow, COLORS.strokeSoft, 1, 0.45)

  local adExpanded = false
  adArrow.Activated:Connect(function()
    adExpanded = not adExpanded
    _G._AmbitiousExpand(adHolder, adExpanded, 42, adArrow)
  end)

  local adBtn = adRow and adRow:FindFirstChild("ToggleButton")
  if adBtn then
    adBtn.Activated:Connect(function()
      _G.AmbitiousAfterDrop.enabled = not (_G.AmbitiousAfterDrop.enabled == true)
      if setADVisual then setADVisual(_G.AmbitiousAfterDrop.enabled) end
      saveAmbitiousConfig()
    end)
  end

  adApplyVisual()
end

