-- Palette unica e ORDINATA, usata da tutti i color picker dell'hub.
-- Ordine: neutri (marrone compreso, cosi' non finisce vicino al rosso),
-- poi rossi/arancioni/gialli, verdi, ciano/blu, viola/rosa.
_G.AmbitiousColorPresets = {
  -- neutri
  Color3.fromRGB(255, 255, 255),
  Color3.fromRGB(230, 230, 230),
  Color3.fromRGB(50, 50, 50),
  Color3.fromRGB(0, 0, 0),
  Color3.fromRGB(139, 69, 19),
  -- rossi / arancioni / gialli
  Color3.fromRGB(220, 20, 60),
  Color3.fromRGB(255, 0, 0),
  Color3.fromRGB(255, 80, 80),
  Color3.fromRGB(255, 128, 0),
  Color3.fromRGB(255, 140, 0),
  Color3.fromRGB(255, 200, 0),
  Color3.fromRGB(255, 215, 0),
  -- verdi
  Color3.fromRGB(0, 255, 0),
  Color3.fromRGB(80, 255, 120),
  Color3.fromRGB(0, 128, 128),
  Color3.fromRGB(64, 224, 208),
  -- ciano / blu
  Color3.fromRGB(0, 255, 255),
  Color3.fromRGB(0, 180, 255),
  Color3.fromRGB(0, 100, 255),
  Color3.fromRGB(123, 104, 238),
  -- viola / rosa
  Color3.fromRGB(128, 0, 255),
  Color3.fromRGB(255, 0, 255),
  Color3.fromRGB(255, 105, 180),
  Color3.fromRGB(255, 180, 200),
}

-- Costruisce una riga "<nome> Color" a tendina, identica a quella del
-- Tracker Color: freccetta sulla riga indicata, pallino di anteprima e
-- bottone PICK che apre il popup con la palette + i campi RGB.
--
-- cfg = {
--   parent    = frame della tab
--   anchorRow = riga su cui mettere la freccetta
--   rowName   = testo della riga (es. "Tracker Color")
--   rowOrder  = LayoutOrder della riga
--   title     = titolo del popup (es. "TRACKER COLOR")
--   getColor  = function() -> Color3      (colore corrente)
--   onColor   = function(Color3)          (applica il nuovo colore)
-- }
-- Ritorna: row, setPreview(Color3)
_G._AmbitiousBuildColorPickerRow = function(cfg)
  local row = baseRow(cfg.parent, cfg.rowName, cfg.rowOrder)
  row.Size = UDim2.new(1, -4, 0, 42)
  row.ClipsDescendants = true
  row.Visible = false

  -- ---- FRECCETTA SULLA RIGA PADRE ----
  if cfg.anchorRow then
    local expanded = false
    local arrow = Instance.new("TextButton")
    arrow.Name = "ColorArrow"
    arrow.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    arrow.BackgroundTransparency = 0.18
    arrow.BorderSizePixel = 0
    arrow.Size = UDim2.new(0, 28, 0, 24)
    arrow.Position = UDim2.new(1, -90, 0.5, -12)
    arrow.Text = "\u{25B2}"
    arrow.TextColor3 = COLORS.white
    arrow.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    arrow.TextStrokeTransparency = 0.3
    arrow.TextSize = 15
    arrow.Font = Enum.Font.GothamBold
    arrow.AutoButtonColor = false
    arrow.ZIndex = 8
    arrow.Parent = cfg.anchorRow
    corner(arrow, 7)
    stroke(arrow, COLORS.strokeSoft, 1, 0.45)
    arrow.Activated:Connect(function()
      expanded = not expanded
      _G._AmbitiousExpand(row, expanded, 42, arrow)
    end)
  end

  -- ---- PALLINO DI ANTEPRIMA ----
  local preview = Instance.new("Frame")
  preview.Name = "ColorPreview"
  preview.Size = UDim2.new(0, 28, 0, 28)
  preview.Position = UDim2.new(1, -114, 0.5, -14)
  preview.BackgroundColor3 = cfg.getColor() or Color3.fromRGB(230, 230, 230)
  preview.BorderSizePixel = 0
  preview.ZIndex = 6
  preview.Parent = row
  Instance.new("UICorner", preview).CornerRadius = UDim.new(1, 0)
  local previewStroke = Instance.new("UIStroke")
  previewStroke.Color = Color3.fromRGB(255, 255, 255)
  previewStroke.Thickness = 1.5
  previewStroke.Transparency = 0.3
  previewStroke.Parent = preview

  -- ---- BOTTONE PICK ----
  local btnHolder = Instance.new("Frame")
  btnHolder.Name = "ColorButtonHolder"
  btnHolder.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
  btnHolder.BackgroundTransparency = 0.28
  btnHolder.BorderSizePixel = 0
  btnHolder.Size = UDim2.new(0, 66, 0, 30)
  btnHolder.Position = UDim2.new(1, -73, 0.5, -15)
  btnHolder.ClipsDescendants = true
  btnHolder.ZIndex = 6
  btnHolder.Parent = row
  corner(btnHolder, 15)
  stroke(btnHolder, Color3.fromRGB(200, 200, 210), 1.5, 0.15)

  local pickGrad = Instance.new("UIGradient")
  pickGrad.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
  })
  pickGrad.Rotation = 18
  pickGrad.Parent = btnHolder
  _G._AmbitiousRegAccent(btnHolder, pickGrad, "pick")

  local pickBtn = Instance.new("TextButton")
  pickBtn.Name = "ColorButton"
  pickBtn.BackgroundTransparency = 1
  pickBtn.Text = "PICK"
  pickBtn.TextColor3 = COLORS.white
  pickBtn.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
  pickBtn.TextStrokeTransparency = 0.3
  pickBtn.TextSize = 12
  pickBtn.Font = Enum.Font.GothamBlack
  pickBtn.TextXAlignment = Enum.TextXAlignment.Center
  pickBtn.Size = UDim2.new(1, 0, 1, 0)
  pickBtn.Position = UDim2.new(0, 0, 0, 0)
  pickBtn.BorderSizePixel = 0
  pickBtn.ZIndex = 8
  pickBtn.AutoButtonColor = false
  pickBtn.Parent = btnHolder

  pickBtn.MouseEnter:Connect(function()
    tween(btnHolder, {Size = UDim2.new(0, 72, 0, 32), Position = UDim2.new(1, -76, 0.5, -16)}, 0.12)
  end)
  pickBtn.MouseLeave:Connect(function()
    tween(btnHolder, {Size = UDim2.new(0, 66, 0, 30), Position = UDim2.new(1, -73, 0.5, -15)}, 0.12)
  end)

  local function setPreview(c)
    if c then preview.BackgroundColor3 = c end
  end

  -- ---- POPUP ----
  local pickerGui = nil

  local function closePicker()
    if pickerGui and pickerGui.Parent then
      TweenService:Create(pickerGui.Frame, TweenInfo.new(0.2), {BackgroundTransparency = 1}):Play()
      task.delay(0.25, function()
        if pickerGui and pickerGui.Parent then pickerGui:Destroy() end
        pickerGui = nil
      end)
    end
  end

  local function applyColor(c)
    setPreview(c)
    if cfg.onColor then cfg.onColor(c) end
  end

  pickBtn.Activated:Connect(function()
    if pickerGui and pickerGui.Parent then
      closePicker()
      return
    end

    pickerGui = Instance.new("ScreenGui")
    pickerGui.Name = "AmbitiousHubColorPicker"
    pickerGui.ResetOnSpawn = false
    pickerGui.IgnoreGuiInset = true
    pickerGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pickerGui.DisplayOrder = 9999
    pickerGui.Parent = HubGui

    local backdrop = Instance.new("Frame")
    backdrop.Name = "Backdrop"
    backdrop.Size = UDim2.new(1, 0, 1, 0)
    backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    backdrop.BackgroundTransparency = 0.5
    backdrop.BorderSizePixel = 0
    backdrop.ZIndex = 1
    backdrop.Parent = pickerGui

    local pickerFrame = Instance.new("Frame")
    pickerFrame.Name = "Frame"
    pickerFrame.Size = UDim2.new(0, 320, 0, 420)
    pickerFrame.Position = UDim2.new(0.5, -160, 0.5, -210)
    pickerFrame.BackgroundColor3 = Color3.fromRGB(10, 10, 12)
    pickerFrame.BorderSizePixel = 0
    pickerFrame.ZIndex = 2
    pickerFrame.Parent = pickerGui
    corner(pickerFrame, 16)
    stroke(pickerFrame, Color3.fromRGB(90, 90, 105), 1.2, 0.3)

    local titleBar = Instance.new("Frame")
    titleBar.Name = "TitleBar"
    titleBar.Size = UDim2.new(1, 0, 0, 44)
    titleBar.BackgroundColor3 = Color3.fromRGB(14, 14, 17)
    titleBar.BackgroundTransparency = 0.1
    titleBar.BorderSizePixel = 0
    titleBar.ZIndex = 3
    titleBar.Parent = pickerFrame
    corner(titleBar, 16)

    local titleLabel = Instance.new("TextLabel")
    titleLabel.Name = "Title"
    titleLabel.Size = UDim2.new(1, -60, 1, 0)
    titleLabel.Position = UDim2.new(0, 16, 0, 0)
    titleLabel.BackgroundTransparency = 1
    titleLabel.Text = cfg.title or "COLOR"
    titleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    titleLabel.Font = Enum.Font.GothamBlack
    titleLabel.TextSize = 15
    titleLabel.TextXAlignment = Enum.TextXAlignment.Left
    titleLabel.ZIndex = 4
    titleLabel.Parent = titleBar

    local closeBtn = Instance.new("TextButton")
    closeBtn.Name = "CloseBtn"
    closeBtn.Size = UDim2.new(0, 32, 0, 32)
    closeBtn.Position = UDim2.new(1, -40, 0, 6)
    closeBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 28)
    closeBtn.BorderSizePixel = 0
    closeBtn.Text = "X"
    closeBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
    closeBtn.Font = Enum.Font.GothamBlack
    closeBtn.TextSize = 13
    closeBtn.AutoButtonColor = false
    closeBtn.ZIndex = 4
    closeBtn.Parent = titleBar
    corner(closeBtn, 8)
    stroke(closeBtn, Color3.fromRGB(90, 90, 105), 1, 0.4)
    closeBtn.MouseEnter:Connect(function()
      tween(closeBtn, {BackgroundColor3 = Color3.fromRGB(180, 50, 50)}, 0.12)
    end)
    closeBtn.MouseLeave:Connect(function()
      tween(closeBtn, {BackgroundColor3 = Color3.fromRGB(25, 25, 28)}, 0.12)
    end)
    closeBtn.Activated:Connect(closePicker)

    local currentPreview = Instance.new("Frame")
    currentPreview.Name = "CurrentPreview"
    currentPreview.Size = UDim2.new(0, 64, 0, 64)
    currentPreview.Position = UDim2.new(0.5, -32, 0, 60)
    currentPreview.BackgroundColor3 = preview.BackgroundColor3
    currentPreview.BorderSizePixel = 0
    currentPreview.ZIndex = 3
    currentPreview.Parent = pickerFrame
    Instance.new("UICorner", currentPreview).CornerRadius = UDim.new(1, 0)
    local cpStroke = Instance.new("UIStroke")
    cpStroke.Color = Color3.fromRGB(255, 255, 255)
    cpStroke.Thickness = 2
    cpStroke.Transparency = 0.2
    cpStroke.Parent = currentPreview

    local colorGrid = Instance.new("Frame")
    colorGrid.Name = "ColorGrid"
    colorGrid.Size = UDim2.new(1, -24, 0, 240)
    colorGrid.Position = UDim2.new(0, 12, 0, 140)
    colorGrid.BackgroundTransparency = 1
    colorGrid.BorderSizePixel = 0
    colorGrid.ZIndex = 3
    colorGrid.Parent = pickerFrame

    local gridLayout = Instance.new("UIGridLayout")
    gridLayout.CellSize = UDim2.new(0, 42, 0, 42)
    gridLayout.CellPadding = UDim2.new(0, 8, 0, 8)
    gridLayout.FillDirection = Enum.FillDirection.Horizontal
    gridLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
    gridLayout.SortOrder = Enum.SortOrder.LayoutOrder
    gridLayout.Parent = colorGrid

    for i, color in ipairs(_G.AmbitiousColorPresets) do
      local cBtn = Instance.new("TextButton")
      cBtn.Name = "Color_" .. i
      cBtn.Size = UDim2.new(1, 0, 1, 0)
      cBtn.BackgroundColor3 = color
      cBtn.BorderSizePixel = 0
      cBtn.Text = ""
      cBtn.AutoButtonColor = false
      cBtn.LayoutOrder = i
      cBtn.ZIndex = 4
      cBtn.Parent = colorGrid
      Instance.new("UICorner", cBtn).CornerRadius = UDim.new(0, 14)

      local cGrad = Instance.new("UIGradient")
      cGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
        ColorSequenceKeypoint.new(0.5, color),
        ColorSequenceKeypoint.new(1, color),
      })
      cGrad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.6),
        NumberSequenceKeypoint.new(0.5, 0),
        NumberSequenceKeypoint.new(1, 0),
      })
      cGrad.Rotation = 125
      cGrad.Parent = cBtn

      local cStroke = Instance.new("UIStroke")
      cStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
      cStroke.Color = Color3.fromRGB(255, 255, 255)
      cStroke.Thickness = 1.5
      cStroke.Transparency = 0.65
      cStroke.Parent = cBtn

      cBtn.MouseEnter:Connect(function()
        tween(cBtn, {Size = UDim2.new(1, 8, 1, 8), Position = UDim2.new(0, -4, 0, -4)}, 0.12)
        tween(cStroke, {Transparency = 0, Thickness = 2.6}, 0.12)
      end)
      cBtn.MouseLeave:Connect(function()
        tween(cBtn, {Size = UDim2.new(1, 0, 1, 0), Position = UDim2.new(0, 0, 0, 0)}, 0.12)
        tween(cStroke, {Transparency = 0.65, Thickness = 1.5}, 0.12)
      end)
      cBtn.Activated:Connect(function()
        applyColor(color)
        currentPreview.BackgroundColor3 = color
        closePicker()
      end)
    end

    local rgbFrame = Instance.new("Frame")
    rgbFrame.Name = "RGBFrame"
    rgbFrame.Size = UDim2.new(1, -24, 0, 36)
    rgbFrame.Position = UDim2.new(0, 12, 1, -52)
    rgbFrame.BackgroundTransparency = 1
    rgbFrame.ZIndex = 3
    rgbFrame.Parent = pickerFrame

    local rBox = Instance.new("TextBox")
    rBox.Name = "R"
    rBox.Size = UDim2.new(0, 80, 1, 0)
    rBox.Position = UDim2.new(0, 0, 0, 0)
    rBox.BackgroundColor3 = Color3.fromRGB(20, 20, 24)
    rBox.Text = tostring(math.floor(preview.BackgroundColor3.R * 255))
    rBox.TextColor3 = Color3.fromRGB(255, 100, 100)
    rBox.Font = Enum.Font.GothamBold
    rBox.TextSize = 13
    rBox.ClearTextOnFocus = false
    rBox.ZIndex = 4
    rBox.Parent = rgbFrame
    corner(rBox, 8)
    stroke(rBox, Color3.fromRGB(255, 100, 100), 1, 0.4)

    local gBox = Instance.new("TextBox")
    gBox.Name = "G"
    gBox.Size = UDim2.new(0, 80, 1, 0)
    gBox.Position = UDim2.new(0.5, -40, 0, 0)
    gBox.BackgroundColor3 = Color3.fromRGB(20, 20, 24)
    gBox.Text = tostring(math.floor(preview.BackgroundColor3.G * 255))
    gBox.TextColor3 = Color3.fromRGB(100, 255, 100)
    gBox.Font = Enum.Font.GothamBold
    gBox.TextSize = 13
    gBox.ClearTextOnFocus = false
    gBox.ZIndex = 4
    gBox.Parent = rgbFrame
    corner(gBox, 8)
    stroke(gBox, Color3.fromRGB(100, 255, 100), 1, 0.4)

    local bBox = Instance.new("TextBox")
    bBox.Name = "B"
    bBox.Size = UDim2.new(0, 80, 1, 0)
    bBox.Position = UDim2.new(1, -80, 0, 0)
    bBox.BackgroundColor3 = Color3.fromRGB(20, 20, 24)
    bBox.Text = tostring(math.floor(preview.BackgroundColor3.B * 255))
    bBox.TextColor3 = Color3.fromRGB(100, 100, 255)
    bBox.Font = Enum.Font.GothamBold
    bBox.TextSize = 13
    bBox.ClearTextOnFocus = false
    bBox.ZIndex = 4
    bBox.Parent = rgbFrame
    corner(bBox, 8)
    stroke(bBox, Color3.fromRGB(100, 100, 255), 1, 0.4)

    local function applyRGB()
      local r = math.clamp(tonumber(rBox.Text) or 0, 0, 255)
      local g = math.clamp(tonumber(gBox.Text) or 0, 0, 255)
      local b = math.clamp(tonumber(bBox.Text) or 0, 0, 255)
      local newColor = Color3.fromRGB(r, g, b)
      applyColor(newColor)
      currentPreview.BackgroundColor3 = newColor
      rBox.Text = tostring(r)
      gBox.Text = tostring(g)
      bBox.Text = tostring(b)
    end

    rBox.FocusLost:Connect(applyRGB)
    gBox.FocusLost:Connect(applyRGB)
    bBox.FocusLost:Connect(applyRGB)

    backdrop.InputBegan:Connect(function(input)
      if input.UserInputType == Enum.UserInputType.MouseButton1
         or input.UserInputType == Enum.UserInputType.Touch then
        closePicker()
      end
    end)

    pickerFrame.Size = UDim2.new(0, 0, 0, 0)
    pickerFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
    TweenService:Create(pickerFrame, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
      Size = UDim2.new(0, 320, 0, 420),
      Position = UDim2.new(0.5, -160, 0.5, -210)
    }):Play()
  end)

  return row, setPreview
end
-- <<< COLOR PICKER CONDIVISO END

section(Combat, "AUTO STEAL", 1)
autoStealSelectorRow(Combat, 2)
_ambitiousRow, setAutoStealVisual = toggleRow(Combat, "Auto Steal", autoStealEnabled, 3)
do
  _ambitiousBtn = _ambitiousRow and _ambitiousRow:FindFirstChild("ToggleButton")
  if _ambitiousBtn then
    _ambitiousBtn.Activated:Connect(function()
      autoStealEnabled = not autoStealEnabled
      if setAutoStealVisual then setAutoStealVisual(autoStealEnabled) end
      if _G.AmbitiousAutoStealSync then _G.AmbitiousAutoStealSync() end
      saveAmbitiousConfig()
    end)
  end
end

_, radiusBox = textboxRow(Combat, "Radius", tostring(autoStealRadius), 4)
autoStealRadiusBox = radiusBox
-- Corregge il valore iniziale del box in base al modo caricato dal config
if selectedStealMode == "Semi" and selectedSemiMode == "V2" then
  radiusBox.Text = tostring(_G.AmbitiousStealRadii.SemiV2Radius or 60)
elseif selectedStealMode == "Semi" then
  radiusBox.Text = tostring(_G.AmbitiousStealRadii.Semi or 60)
else
  radiusBox.Text = tostring(_G.AmbitiousStealRadii.Normal or 62)
end
radiusBox.FocusLost:Connect(function()
  local v = tonumber(radiusBox.Text)
  _G.AmbitiousStealRadii = _G.AmbitiousStealRadii or {Normal = 62, Semi = 60, SemiV2Radius = 60, SemiV2SemiRadius = 8}
  if selectedStealMode == "Semi" and selectedSemiMode == "V2" then
    -- In V2: Radius = prime range (PRIME_RANGE)
    if v and v > 0 and v <= 500 then
      _G.AmbitiousStealRadii.SemiV2Radius = v
      if _G.AmbitiousSemiV2SetRadius then _G.AmbitiousSemiV2SetRadius(v) end
    end
    radiusBox.Text = tostring(_G.AmbitiousStealRadii.SemiV2Radius or 60)
  else
    if v and v > 0 and v <= 500 then
      autoStealRadius = v
    end
    _G.AmbitiousStealRadii[selectedStealMode] = autoStealRadius
    radiusBox.Text = tostring(autoStealRadius)
    if _G.AmbitiousNormalAutoStealSetRadius then _G.AmbitiousNormalAutoStealSetRadius(_G.AmbitiousStealRadii.Normal or 62) end
    if _G.AmbitiousSemiAutoStealSetRadius then _G.AmbitiousSemiAutoStealSetRadius(_G.AmbitiousStealRadii.Semi or 60) end
  end
  if _G.AmbitiousAutoStealSync then _G.AmbitiousAutoStealSync() end
  saveAmbitiousConfig()
end)

-- ===== SEMI SUB-MODE SELECTOR (V1 / V2 / V3) — visibile solo in modalità Semi =====
;(function()
  -- Costruiamo il row slider SEMI V1 / SEMI V2 / SEMI V3 identico allo stile di autoStealSelectorRow
  local semiSubHolder = Instance.new("Frame")
  semiSubHolder.Name = "Semi Sub Mode"
  semiSubHolder.BackgroundColor3 = COLORS.row
  semiSubHolder.BackgroundTransparency = 0.28
  semiSubHolder.Size = UDim2.new(1, -4, 0, 42)
  semiSubHolder.BorderSizePixel = 0
  semiSubHolder.LayoutOrder = 2.5
  semiSubHolder.ZIndex = 4
  semiSubHolder.ClipsDescendants = true
  semiSubHolder.Visible = selectedStealMode == "Semi"
  semiSubHolder.Parent = Combat
  corner(semiSubHolder, 14)
  stroke(semiSubHolder, Color3.fromRGB(110, 110, 120), 1.4, 0.32)
  _G._AmbitiousRegAccent(semiSubHolder, nil, "soft")

  local subSlide = Instance.new("Frame")
  subSlide.Name = "SelectedSlide"
  subSlide.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
  subSlide.BackgroundTransparency = 0.1
  subSlide.Size = UDim2.new(1/3, -3, 1, -8)
  subSlide.Position = UDim2.new(0, 4, 0, 4)
  subSlide.BorderSizePixel = 0
  subSlide.ZIndex = 5
  subSlide.Parent = semiSubHolder
  corner(subSlide, 13)
  local subSlideStroke = Instance.new("UIStroke")
  subSlideStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  subSlideStroke.Color = Color3.fromRGB(200, 200, 210)
  subSlideStroke.Thickness = 1.5
  subSlideStroke.Transparency = 0.1
  subSlideStroke.Parent = subSlide
  local subSlideGradient = Instance.new("UIGradient")
  subSlideGradient.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
  })
  subSlideGradient.Transparency = NumberSequence.new({
    NumberSequenceKeypoint.new(0, 0.08),
    NumberSequenceKeypoint.new(0.5, 0.02),
    NumberSequenceKeypoint.new(1, 0.08),
  })
  subSlideGradient.Parent = subSlide
  _G._AmbitiousRegAccent(subSlide, subSlideGradient, "slide")
  subSlideGradient.Rotation = 22

  local SEMI_MODES = {"V1", "V2", "V3"}
  local semiSegW = 1 / #SEMI_MODES
  local semiTexts = {}

  for i, m in ipairs(SEMI_MODES) do
    local lbl = Instance.new("TextLabel")
    lbl.Name = m .. "Text"
    lbl.BackgroundTransparency = 1
    lbl.Text = "SEMI " .. m
    lbl.TextColor3 = COLORS.white
    lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    lbl.TextStrokeTransparency = 0.2
    lbl.TextSize = 11
    lbl.Font = Enum.Font.GothamBlack
    lbl.TextXAlignment = Enum.TextXAlignment.Center
    lbl.Size = UDim2.new(semiSegW, 0, 1, 0)
    lbl.Position = UDim2.new(semiSegW * (i - 1), 0, 0, 0)
    lbl.ZIndex = 8
    lbl.Parent = semiSubHolder
    semiTexts[i] = lbl

    local click = Instance.new("TextButton")
    click.Name = m .. "Click"
    click.BackgroundTransparency = 1
    click.Text = ""
    click.AutoButtonColor = false
    click.Size = UDim2.new(semiSegW, 0, 1, 0)
    click.Position = UDim2.new(semiSegW * (i - 1), 0, 0, 0)
    click.ZIndex = 10
    click.Parent = semiSubHolder
    local _m = m
    click.MouseButton1Click:Connect(function()
      if _G.AmbitiousSetSemiSubMode then _G.AmbitiousSetSemiSubMode(_m) end
    end)
  end

  local function semiIndexOf(mode)
    for i, m in ipairs(SEMI_MODES) do
      if m == mode then return i end
    end
    return 1
  end

  -- Durata fissa come gli altri slider dell'hub: piu' e' lontano il
  -- segmento, piu' veloce si muove la slide.
  local function applySemiSubVisual(mode)
    local idx = semiIndexOf(mode)
    tween(subSlide, {
      Position = UDim2.new(semiSegW * (idx - 1), (idx == 1) and 4 or -1, 0, 4),
      Size = UDim2.new(semiSegW, -3, 1, -8),
    }, 0.18)
    for i, lbl in ipairs(semiTexts) do
      local sel = (i == idx)
      tween(lbl, {
        TextTransparency = sel and 0 or 0.5,
        TextStrokeTransparency = sel and 0.2 or 0.38
      }, 0.14)
    end
  end

  -- V1 e V3 usano lo stesso motore, quindi condividono anche il Radius
  -- (slot "Semi"). Solo la V2 ha il suo SemiV2Radius.
  local function applySemiRadiusBox()
    if selectedSemiMode == "V2" then
      if autoStealRadiusBox then
        autoStealRadiusBox.Text = tostring((_G.AmbitiousStealRadii and _G.AmbitiousStealRadii.SemiV2Radius) or 60)
      end
    else
      autoStealRadius = (_G.AmbitiousStealRadii and _G.AmbitiousStealRadii.Semi) or 60
      if autoStealRadiusBox then
        autoStealRadiusBox.Text = tostring(autoStealRadius)
      end
    end
  end

  local function setSemiSubModeVisualOnly(mode)
    if mode ~= "V2" and mode ~= "V3" then mode = "V1" end
    selectedSemiMode = mode
    applySemiSubVisual(selectedSemiMode)
    applySemiRadiusBox()
    if _G.AmbitiousRefreshSemiStealRows then _G.AmbitiousRefreshSemiStealRows() end
  end

  local function setSemiSubMode(mode)
    setSemiSubModeVisualOnly(mode)
    task.spawn(function()
      saveAmbitiousConfig()
      if _G.AmbitiousAutoStealSync then _G.AmbitiousAutoStealSync() end
    end)
  end

  setSemiSubModeVisualOnly(selectedSemiMode)

  _G.AmbitiousSemiSubHolder = semiSubHolder
  _G.AmbitiousSetSemiSubMode = setSemiSubMode
  _G.AmbitiousSetSemiSubModeVisual = setSemiSubModeVisualOnly
end)()

-- ===== SEMI STEAL SETTINGS (visibili solo in modalità Semi) =====
;(function()
  local A = _G.AmbitiousSemiSteal

  local function getSemi(key, def)
    return A and A[key] or def
  end
  local function setSemi(key, val)
    if A then A[key] = val end
  end

  -- Delay Radius (4.1) — raggio entro cui scatta il trigger nella fase 2 (Semi V1)
  local _, delayRadBox = textboxRow(Combat, "Delay Radius", tostring(getSemi("autoGrabSetDelayRadius", 8)), 4.1)
  _G.AmbitiousDelayRadBox = delayRadBox
  delayRadBox.FocusLost:Connect(function()
    local v = tonumber(delayRadBox.Text)
    if v and v > 0 and v <= 500 then
      setSemi("autoGrabSetDelayRadius", v)
    end
    delayRadBox.Text = tostring(getSemi("autoGrabSetDelayRadius", 8))
    saveAmbitiousConfig()
  end)

  -- Stop Time (4.2) — barra si ferma qui prima di aspettare il raggio (Semi V1)
  local _, stopTimeBox = textboxRow(Combat, "Stop Time (s)", tostring(getSemi("autoGrabStopTime", 1.29)), 4.2)
  _G.AmbitiousStopTimeBox = stopTimeBox
  stopTimeBox.FocusLost:Connect(function()
    local v = tonumber(stopTimeBox.Text)
    -- Tetto a 1.29s: oltre, la barra resterebbe ferma a 100% e il trigger
    -- diventerebbe istantaneo, che non e' il comportamento voluto per la V1.
    if v and v > 0 and v <= 1.29 then
      setSemi("autoGrabStopTime", v)
    end
    stopTimeBox.Text = tostring(getSemi("autoGrabStopTime", 1.29))
    saveAmbitiousConfig()
  end)

  -- Stop Time % (4.25) — come sopra ma espresso in percentuale di riempimento
  -- della barra (Semi V3). Il motore e' lo stesso della V1: la percentuale
  -- viene convertita in secondi dentro executeSemi.
  local _, stopPctBox = textboxRow(Combat, "Stop Time (%)", tostring(getSemi("autoGrabStopPercent", 75)), 4.25)
  _G.AmbitiousStopPctBox = stopPctBox
  stopPctBox.FocusLost:Connect(function()
    local v = tonumber(stopPctBox.Text)
    if v and v > 0 and v <= 100 then
      setSemi("autoGrabStopPercent", v)
    end
    stopPctBox.Text = tostring(getSemi("autoGrabStopPercent", 75))
    saveAmbitiousConfig()
  end)

  -- Semi Radius (4.15) — steal range per Semi V2 (= STEAL_RANGE nel vecchio CONFIG)
  local semiV2RadDefault = tostring(tonumber(_G.AmbitiousStealRadii and _G.AmbitiousStealRadii.SemiV2SemiRadius) or 8)
  local _, semiV2RadBox = textboxRow(Combat, "Semi Radius", semiV2RadDefault, 4.15)
  _G.AmbitiousSemiV2RadBox = semiV2RadBox
  semiV2RadBox.FocusLost:Connect(function()
    local v = tonumber(semiV2RadBox.Text)
    if v and v > 0 and v <= 500 then
      _G.AmbitiousStealRadii = _G.AmbitiousStealRadii or {}
      _G.AmbitiousStealRadii.SemiV2SemiRadius = v
      if _G.AmbitiousSemiV2SetSemiRadius then _G.AmbitiousSemiV2SetSemiRadius(v) end
    end
    semiV2RadBox.Text = tostring((_G.AmbitiousStealRadii and _G.AmbitiousStealRadii.SemiV2SemiRadius) or 8)
    saveAmbitiousConfig()
  end)

  -- >>> RADIUS CIRCLE BEGIN
  -- Toggle "Radius Circle": disegna un cerchio viola alla base dei piedi
  -- con il raggio che conta davvero nella modalita' selezionata:
  --   Semi V1 / V3 -> Delay Radius
  --   Semi V2      -> Semi Radius
  -- Serve a capire a occhio quando si e' dentro il raggio di trigger.
  local rcPart = nil
  local rcConn = nil

  local function rcRadius()
    if selectedSemiMode == "V2" then
      return tonumber(_G.AmbitiousStealRadii and _G.AmbitiousStealRadii.SemiV2SemiRadius) or 8
    end
    return tonumber(getSemi("autoGrabSetDelayRadius", 8)) or 8
  end

  local function rcDestroy()
    if rcConn then pcall(function() rcConn:Disconnect() end); rcConn = nil end
    if rcPart then pcall(function() rcPart:Destroy() end); rcPart = nil end
  end

  -- Le versioni precedenti creavano anche un secondo disco ("...Rim")
  -- appeso alla camera. Rieseguendo lo script quello restava li' e si
  -- vedeva ancora l'anello: qui si spazza via qualunque residuo.
  local function rcClearStray()
    local cam = workspace.CurrentCamera
    if not cam then return end
    for _, o in ipairs(cam:GetChildren()) do
      if o ~= rcPart and typeof(o) == "Instance"
         and string.sub(o.Name, 1, 20) == "AmbitiousRadiusCircl" then
        pcall(function() o:Destroy() end)
      end
    end
  end

  local function rcEnsurePart()
    if rcPart and rcPart.Parent then return rcPart end
    rcClearStray()
    local p = Instance.new("Part")
    p.Name = "AmbitiousRadiusCircle"
    p.Shape = Enum.PartType.Cylinder
    p.Anchored = true
    p.CanCollide = false
    p.CanQuery = false
    p.CanTouch = false
    p.CastShadow = false
    p.Massless = true
    p.Material = Enum.Material.Neon
    p.Color = _G.AmbitiousRadiusCircleColor or Color3.fromRGB(230, 230, 230)
    p.Transparency = 0.72
    p.Size = Vector3.new(0.12, 2, 2)
    -- Parent alla camera: resta puramente locale e fuori dai query di workspace.
    p.Parent = workspace.CurrentCamera
    rcPart = p
    return p
  end

  local function rcStep()
    if not (_G.AmbitiousRadiusCircleEnabled == true) then rcDestroy() return end
    -- Solo in modalita' Semi: fuori di li' il raggio non vuol dire niente.
    if selectedStealMode ~= "Semi" then
      if rcPart then rcPart.Transparency = 1 end
      return
    end
    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp then
      if rcPart then rcPart.Transparency = 1 end
      return
    end
    local p = rcEnsurePart()
    p.Transparency = 0.72
    local d = math.clamp(rcRadius(), 0.5, 500) * 2
    p.Size = Vector3.new(0.12, d, d)

    -- Quota: dai piedi del personaggio, come in origine.
    local footY = hrp.Position.Y - (hrp.Size.Y * 0.5) - ((hum and hum.HipHeight) or 2)

    -- Atterrando il personaggio schiaccia e rimbalza di qualche centesimo:
    -- con un margine minimo dal suolo il disco ci finiva sotto per un frame
    -- e sembrava sparire. Si smorzano SOLO gli sbalzi piccoli (sotto 1.5
    -- stud, cioe' il rimbalzo); salti e dislivelli veri restano istantanei.
    local prev = _G._AmbRCLastY
    if prev and math.abs(footY - prev) < 1.5 then
      footY = prev + (footY - prev) * 0.4
    end
    _G._AmbRCLastY = footY

    -- Cylinder e' orientato lungo X: lo si ruota per appoggiarlo a terra.
    p.CFrame = CFrame.new(hrp.Position.X, footY + 0.2, hrp.Position.Z)
              * CFrame.Angles(0, 0, math.rad(90))
  end

  local function rcSetEnabled(on)
    _G.AmbitiousRadiusCircleEnabled = on and true or false
    if _G.AmbitiousRadiusCircleEnabled then
      if not rcConn then
        rcConn = RunService.RenderStepped:Connect(function()
          local ok = pcall(rcStep)
          if not ok and rcPart then rcPart.Transparency = 1 end
        end)
      end
    else
      rcDestroy()
    end
  end
  _G.AmbitiousSetRadiusCircle = rcSetEnabled

  -- Colore del cerchio: applicato subito anche se e' gia' a schermo.
  _G.AmbitiousSetRadiusCircleColor = function(c)
    if typeof(c) ~= "Color3" then return end
    _G.AmbitiousRadiusCircleColor = c
    if rcPart and rcPart.Parent then
      pcall(function() rcPart.Color = c end)
    end
  end

  -- La riga viene costruita DOPO il Synchronize After Hit (che nasce piu'
  -- in basso nel file): a parita' di LayoutOrder vince l'ordine di
  -- creazione, quindi cosi' finisce esattamente sotto di esso.
  local rcRow, rcColorRow = nil, nil
  _G._AmbitiousBuildRadiusCircleRow = function(order)
    if rcRow then return rcRow end
    local row, rcSetVisual = toggleRow(Combat, "Radius Circle", _G.AmbitiousRadiusCircleEnabled == true, order or 3)
    rcRow = row
    _G.AmbitiousRadiusCircleSetVisual = rcSetVisual
    local rcBtn = row and row:FindFirstChild("ToggleButton")
    if rcBtn then
      rcBtn.Activated:Connect(function()
        local on = not (_G.AmbitiousRadiusCircleEnabled == true)
        rcSetEnabled(on)
        if rcSetVisual then rcSetVisual(on) end
        saveAmbitiousConfig()
      end)
    end
    -- Tendina del colore, identica a quella del Tracker Color
    local colorRow, setRcPreview = _G._AmbitiousBuildColorPickerRow({
      parent    = Combat,
      anchorRow = row,
      rowName   = "Radius Circle Color",
      rowOrder  = order or 3,
      title     = "RADIUS CIRCLE COLOR",
      getColor  = function()
        return _G.AmbitiousRadiusCircleColor or Color3.fromRGB(230, 230, 230)
      end,
      onColor   = function(c)
        if _G.AmbitiousSetRadiusCircleColor then _G.AmbitiousSetRadiusCircleColor(c) end
        saveAmbitiousConfig()
      end,
    })
    rcColorRow = colorRow
    _G.AmbitiousRadiusCircleSetColorPreview = setRcPreview

    -- Allinea subito la visibilita' delle righe alla modalita' corrente
    if _G.AmbitiousRefreshSemiStealRows then _G.AmbitiousRefreshSemiStealRows() end
    return row
  end

  -- Stato iniziale dal config
  rcSetEnabled(_G.AmbitiousRadiusCircleEnabled == true)
  -- <<< RADIUS CIRCLE END

  -- Funzione per mostrare/nascondere le righe in base alla modalità
  local function refreshSemiRowsVisibility()
    local onSemi = selectedStealMode == "Semi"
    local onV2   = onSemi and selectedSemiMode == "V2"
    local onV3   = onSemi and selectedSemiMode == "V3"
    local onV1   = onSemi and not onV2 and not onV3

    -- slider V1/V2/V3
    if _G.AmbitiousSemiSubHolder then
      _G.AmbitiousSemiSubHolder.Visible = onSemi
    end

    -- Delay Radius: usato sia dalla V1 che dalla V3 (stesso motore)
    if delayRadBox and delayRadBox.Parent then delayRadBox.Parent.Visible = onV1 or onV3 end

    -- Stop Time in secondi: solo V1
    if stopTimeBox and stopTimeBox.Parent then stopTimeBox.Parent.Visible = onV1 end

    -- Stop Time in percentuale: solo V3
    if stopPctBox and stopPctBox.Parent then stopPctBox.Parent.Visible = onV3 end

    -- riga Semi V2
    if semiV2RadBox and semiV2RadBox.Parent then semiV2RadBox.Parent.Visible = onV2 end

    -- >>> RADIUS CIRCLE: le righe vivono solo in modalita' Semi <<<
    if rcRow then rcRow.Visible = onSemi end
    if rcColorRow and not onSemi then rcColorRow.Visible = false end

    -- aggiorna i valori quando si torna nei rispettivi tab
    if A then
      if onV1 then
        stopTimeBox.Text = tostring(A.autoGrabStopTime or 1.29)
      end
      if onV3 then
        stopPctBox.Text = tostring(A.autoGrabStopPercent or 75)
      end
      if onV1 or onV3 then
        delayRadBox.Text = tostring(A.autoGrabSetDelayRadius or 8)
      end
    end
    if onV2 then
      semiV2RadBox.Text = tostring((_G.AmbitiousStealRadii and _G.AmbitiousStealRadii.SemiV2SemiRadius) or 8)
    end
  end

  -- Mostra subito lo stato corretto
  refreshSemiRowsVisibility()

  -- Espone la funzione per essere chiamata dal mode switcher (Normal/Semi slider e V1/V2/V3 slider)
  _G.AmbitiousRefreshSemiStealRows = refreshSemiRowsVisibility
end)()

-- ===== SYNCHRONIZE AFTER HIT (condiviso Normal + Semi) =====
-- Ordine 3 come il toggle Auto Steal: essendo creata dopo, finisce
-- subito sotto di esso e sopra il Radius (4).
do
  local syncRow, _setSyncVisual = toggleRow(Combat, "Synchronize After Hit", _G._AmbitiousSyncAfterHit.enabled, 3)
  _G._AmbitiousSyncAfterHit.setVisual = _setSyncVisual
  local syncBtn = syncRow and syncRow:FindFirstChild("ToggleButton")
  if syncBtn then
    syncBtn.Activated:Connect(function()
      _G._AmbitiousSyncAfterHit.enabled = not _G._AmbitiousSyncAfterHit.enabled
      if _G._AmbitiousSyncAfterHit.setVisual then _G._AmbitiousSyncAfterHit.setVisual(_G._AmbitiousSyncAfterHit.enabled) end
      if _G._AmbitiousSyncAfterHit.enabled then
        _startSyncAfterHitWatcher()
      else
        _stopSyncAfterHitWatcher()
      end
      saveAmbitiousConfig()
    end)
  end
  -- applica stato iniziale al watcher (già avviato sopra, ma rifà il visual)
  if _G._AmbitiousSyncAfterHit.setVisual then _G._AmbitiousSyncAfterHit.setVisual(_G._AmbitiousSyncAfterHit.enabled) end
end

-- >>> RADIUS CIRCLE: riga subito sotto il Synchronize After Hit <<<
if _G._AmbitiousBuildRadiusCircleRow then _G._AmbitiousBuildRadiusCircleRow(3) end

-- >>> AIMBOT CHASE MODE BEGIN
-- Selettore NORMAL / BYPASS per l'inseguimento di un aimbot.
-- key = "V1" oppure "V2". Cambia solo la logica di chase.
_G._AmbitiousBuildAimbotChaseSelector = function(parent, key, titleText, order)
  local holder = Instance.new("Frame")
  holder.Name = "Aimbot Chase " .. key
  holder.BackgroundColor3 = COLORS.row
  holder.BackgroundTransparency = 0.28
  holder.Size = UDim2.new(1, -4, 0, 42)
  holder.BorderSizePixel = 0
  holder.LayoutOrder = order
  holder.ZIndex = 4
  holder.ClipsDescendants = true
  holder.Visible = (selectedAimbotMode == key)
  holder.Parent = parent
  corner(holder, 14)
  stroke(holder, Color3.fromRGB(110, 110, 120), 1.4, 0.32)
  _G._AmbitiousRegAccent(holder, nil, "soft")

  local slide = Instance.new("Frame")
  slide.Name = "SelectedSlide"
  slide.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
  slide.BackgroundTransparency = 0.1
  slide.Size = UDim2.new(0.5, -3, 1, -8)
  slide.Position = UDim2.new(0, 4, 0, 4)
  slide.BorderSizePixel = 0
  slide.ZIndex = 5
  slide.Parent = holder
  corner(slide, 13)
  local slideStroke = Instance.new("UIStroke")
  slideStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  slideStroke.Color = Color3.fromRGB(200, 200, 210)
  slideStroke.Thickness = 1.5
  slideStroke.Transparency = 0.1
  slideStroke.Parent = slide
  local slideGrad = Instance.new("UIGradient")
  slideGrad.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
  })
  slideGrad.Transparency = NumberSequence.new({
    NumberSequenceKeypoint.new(0, 0.08),
    NumberSequenceKeypoint.new(0.5, 0.02),
    NumberSequenceKeypoint.new(1, 0.08),
  })
  slideGrad.Rotation = 22
  slideGrad.Parent = slide
  _G._AmbitiousRegAccent(slide, slideGrad, "slide")

  local function mkText(txt, xScale)
    local t = Instance.new("TextLabel")
    t.BackgroundTransparency = 1
    t.Text = txt
    t.TextColor3 = COLORS.white
    t.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    t.TextStrokeTransparency = 0.2
    t.TextSize = 11
    t.Font = Enum.Font.GothamBlack
    t.TextXAlignment = Enum.TextXAlignment.Center
    t.Size = UDim2.new(0.5, 0, 1, 0)
    t.Position = UDim2.new(xScale, 0, 0, 0)
    t.ZIndex = 8
    t.Parent = holder
    return t
  end

  local function mkClick(xScale)
    local b = Instance.new("TextButton")
    b.BackgroundTransparency = 1
    b.Text = ""
    b.AutoButtonColor = false
    b.Size = UDim2.new(0.5, 0, 1, 0)
    b.Position = UDim2.new(xScale, 0, 0, 0)
    b.ZIndex = 10
    b.Parent = holder
    return b
  end

  local normalText = mkText("NORMAL", 0)
  local bypassText = mkText("BYPASS", 0.5)
  local normalClick = mkClick(0)
  local bypassClick = mkClick(0.5)

  local function applyVisual(mode)
    local isBypass = (mode == "BYPASS")
    tween(slide, {
      Position = isBypass and UDim2.new(0.5, -1, 0, 4) or UDim2.new(0, 4, 0, 4)
    }, 0.18)
    tween(normalText, {
      TextTransparency = isBypass and 0.5 or 0,
      TextStrokeTransparency = isBypass and 0.38 or 0.2
    }, 0.14)
    tween(bypassText, {
      TextTransparency = isBypass and 0 or 0.5,
      TextStrokeTransparency = isBypass and 0.2 or 0.38
    }, 0.14)
  end

  local function setMode(mode)
    if mode ~= "BYPASS" then mode = "NORMAL" end
    _G._AmbitiousAimbotChase = _G._AmbitiousAimbotChase or { V1 = "NORMAL", V2 = "NORMAL" }
    _G._AmbitiousAimbotChase[key] = mode
    applyVisual(mode)
    saveAmbitiousConfig()
  end

  normalClick.MouseButton1Click:Connect(function() setMode("NORMAL") end)
  bypassClick.MouseButton1Click:Connect(function() setMode("BYPASS") end)

  _G["_AmbitiousAimbotChaseHolder" .. key] = holder
  _G["_AmbitiousRefreshAimbotChase" .. key] = function()
    applyVisual((_G._AmbitiousAimbotChase and _G._AmbitiousAimbotChase[key]) or "NORMAL")
  end
  applyVisual((_G._AmbitiousAimbotChase and _G._AmbitiousAimbotChase[key]) or "NORMAL")
  return holder
end
-- <<< AIMBOT CHASE MODE END

