-- >>> TP BAT VERSIONS UI BEGIN
-- Riga SENZA toggle (sopra Auto Swing): solo la freccetta.
-- Aprendola compare lo slider a 5 segmenti V1 / V2 / V3 / V4 / V5.
-- V1 = logica storica. Bat Aimbot V2 e Bat Counter V2 usano SEMPRE la V1,
-- qualunque sia la versione selezionata qui.
;(function()
  _G.AmbitiousTPBatVersion = math.clamp(tonumber(_G.AmbitiousTPBatVersion) or 1, 1, 5)

  local tpvExpanded = false

  -- Etichetta STATICA: la riga resta sempre "TP Bat Versions".
  local tpvRow = baseRow(Combat, "TP Bat Versions", 10)

  -- ---- FRECCETTA (unico comando della riga) ----
  local tpvArrow = Instance.new("TextButton")
  tpvArrow.Name = "TPBatVersionsArrow"
  tpvArrow.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
  tpvArrow.BackgroundTransparency = 0.18
  tpvArrow.BorderSizePixel = 0
  tpvArrow.Size = UDim2.new(0, 28, 0, 24)
  tpvArrow.Position = UDim2.new(1, -40, 0.5, -12)
  tpvArrow.Text = "\u{25B2}"
  tpvArrow.TextColor3 = COLORS.white
  tpvArrow.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
  tpvArrow.TextStrokeTransparency = 0.3
  tpvArrow.TextSize = 15
  tpvArrow.Font = Enum.Font.GothamBold
  tpvArrow.AutoButtonColor = false
  tpvArrow.ZIndex = 8
  tpvArrow.Parent = tpvRow
  corner(tpvArrow, 7)
  stroke(tpvArrow, COLORS.strokeSoft, 1, 0.45)

  -- ---- HOLDER A TENDINA (2 + 42 + 2) ----
  local TPV_HOLDER_H = 46
  local tpvHolder = Instance.new("Frame")
  tpvHolder.Name = "TP Bat Versions Options"
  tpvHolder.BackgroundTransparency = 1
  tpvHolder.Size = UDim2.new(1, 0, 0, TPV_HOLDER_H)
  tpvHolder.BorderSizePixel = 0
  tpvHolder.LayoutOrder = 10
  tpvHolder.ZIndex = 4
  tpvHolder.ClipsDescendants = true
  tpvHolder.Visible = false
  tpvHolder.Parent = Combat

  -- ============ SLIDER V1 / V2 / V3 / V4 / V5 ============
  local TPV_LABELS = {"V1", "V2", "V3", "V4", "V5"}
  local TPV_N = #TPV_LABELS
  local tpvSegW = 1 / TPV_N

  local tpvVerHolder = Instance.new("Frame")
  tpvVerHolder.Name = "TPBatVersionSelector"
  tpvVerHolder.BackgroundColor3 = COLORS.row
  tpvVerHolder.BackgroundTransparency = 0.28
  tpvVerHolder.Size = UDim2.new(1, -4, 0, 42)
  tpvVerHolder.Position = UDim2.new(0, 2, 0, 2)
  tpvVerHolder.BorderSizePixel = 0
  tpvVerHolder.ZIndex = 4
  tpvVerHolder.ClipsDescendants = true
  tpvVerHolder.Parent = tpvHolder
  corner(tpvVerHolder, 14)
  stroke(tpvVerHolder, Color3.fromRGB(110, 110, 120), 1.4, 0.32)
  _G._AmbitiousRegAccent(tpvVerHolder, nil, "soft")

  local tpvSlide = Instance.new("Frame")
  tpvSlide.Name = "TPBatVersionSlide"
  tpvSlide.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
  tpvSlide.BackgroundTransparency = 0.1
  tpvSlide.AnchorPoint = Vector2.new(0.5, 0.5)
  tpvSlide.Size = UDim2.new(tpvSegW, -4, 1, -8)
  tpvSlide.Position = UDim2.new(tpvSegW * 0.5, 0, 0.5, 0)
  tpvSlide.BorderSizePixel = 0
  tpvSlide.ZIndex = 5
  tpvSlide.Parent = tpvVerHolder
  corner(tpvSlide, 13)
  local tpvSlideStroke = Instance.new("UIStroke")
  tpvSlideStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  tpvSlideStroke.Color = Color3.fromRGB(200, 200, 210)
  tpvSlideStroke.Thickness = 1.5
  tpvSlideStroke.Transparency = 0.1
  tpvSlideStroke.Parent = tpvSlide
  local tpvSlideGrad = Instance.new("UIGradient")
  tpvSlideGrad.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
    ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
    ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
  })
  tpvSlideGrad.Transparency = NumberSequence.new({
    NumberSequenceKeypoint.new(0, 0.08),
    NumberSequenceKeypoint.new(0.5, 0.02),
    NumberSequenceKeypoint.new(1, 0.08),
  })
  tpvSlideGrad.Rotation = 22
  tpvSlideGrad.Parent = tpvSlide
  _G._AmbitiousRegAccent(tpvSlide, tpvSlideGrad, "slide")

  local tpvLabels = {}
  for i, lblText in ipairs(TPV_LABELS) do
    local lbl = Instance.new("TextLabel")
    lbl.Name = "TPBatVersionLabel_" .. tostring(i)
    lbl.BackgroundTransparency = 1
    lbl.Text = lblText
    lbl.TextColor3 = COLORS.white
    lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    lbl.TextStrokeTransparency = 0.2
    lbl.TextSize = 11
    lbl.Font = Enum.Font.GothamBlack
    lbl.TextXAlignment = Enum.TextXAlignment.Center
    lbl.AnchorPoint = Vector2.new(0.5, 0.5)
    lbl.Size = UDim2.new(tpvSegW, 0, 1, 0)
    lbl.Position = UDim2.new(tpvSegW * (i - 0.5), 0, 0.5, 0)
    lbl.ZIndex = 8
    lbl.Parent = tpvVerHolder
    tpvLabels[i] = lbl

