    click.AutoButtonColor = false
    click.AnchorPoint = Vector2.new(0.5, 0.5)
    click.Size = UDim2.new(tpvSegW, 0, 1, 0)
    click.Position = UDim2.new(tpvSegW * (i - 0.5), 0, 0.5, 0)
    click.ZIndex = 10
    click.Parent = tpvVerHolder
    local idx = i
    click.MouseButton1Click:Connect(function()
      if _G.AmbitiousSetTPBatVersion then
        _G.AmbitiousSetTPBatVersion(idx)
      else
        _G.AmbitiousTPBatVersion = idx
        if _G._AmbitiousTPBatSetVersionVisual then _G._AmbitiousTPBatSetVersionVisual(idx) end
      end
    end)
  end

  local function setTPVersionVisual(index)
    index = math.clamp(tonumber(index) or 1, 1, TPV_N)
    _G._AmbitiousTPBatVisIndex = index
    tween(tpvSlide, {
      Position = UDim2.new(tpvSegW * (index - 0.5), 0, 0.5, 0),
      Size = UDim2.new(tpvSegW, -4, 1, -8),
    }, 0.18)
    for i, lbl in ipairs(tpvLabels) do
      local sel = (i == index)
      tween(lbl, {
        TextTransparency = sel and 0 or 0.22,
        TextStrokeTransparency = sel and 0.2 or 0.45,
      }, 0.14)
    end
  end
  _G._AmbitiousTPBatSetVersionVisual = setTPVersionVisual

  -- ---- APERTURA / CHIUSURA ----
  tpvArrow.Activated:Connect(function()
    tpvExpanded = not tpvExpanded
    _G._AmbitiousExpand(tpvHolder, tpvExpanded, TPV_HOLDER_H, tpvArrow)
  end)

  -- Init visuale
  setTPVersionVisual(_G.AmbitiousTPBatVersion or 1)
end)()
-- <<< TP BAT VERSIONS UI END

_G.AmbitiousTPBatAutoSwingRow, _G.AmbitiousTPBatAutoSwingSetVisual, _G.AmbitiousTPBatAutoSwingBtn = _G.AmbitiousActionToggleRow(Combat, "Auto Swing", tpBatAutoSwingEnabled, 11)
do
