end
_G.AmbitiousTPBatCameraLockRow, _G.AmbitiousTPBatCameraLockSetVisual, _G.AmbitiousTPBatCameraLockBtn = _G.AmbitiousActionToggleRow(Combat, "Camera Lock", _G._AmbitiousGetTPBatCameraLock and _G._AmbitiousGetTPBatCameraLock() or false, 12)
do
