  spamKnob.BorderSizePixel = 0
  spamKnob.ZIndex = 7
  spamKnob.Parent = spamTrack
  corner(spamKnob, 999)
  local spamKnobStroke = Instance.new("UIStroke")
  spamKnobStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  spamKnobStroke.Color = Color3.fromRGB(120, 120, 135)
  spamKnobStroke.Thickness = 1.4
  spamKnobStroke.Transparency = 0.15
  spamKnobStroke.Parent = spamKnob

  local spamShine = Instance.new("Frame")
  spamShine.Name = "Shine"
  spamShine.BackgroundColor3 = COLORS.white
  spamShine.BackgroundTransparency = 0.55
  spamShine.Size = UDim2.new(1, -5, 0, 5)
  spamShine.Position = UDim2.new(0, 2.5, 0, 2.5)
  spamShine.BorderSizePixel = 0
  spamShine.ZIndex = 8
  spamShine.Parent = spamKnob
