    tween(spamKnob, {Position = on and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)})
    tween(spamTrack, {
      BackgroundTransparency = on and 0 or 0.12,
      BackgroundColor3 = on and onBg or COLORS.toggleBg
    })
    tween(spamFill, {BackgroundTransparency = on and 0 or 1})
    tween(spamKnobStroke, {Color = on and onEdge or Color3.fromRGB(120, 120, 135)})
    if spamTrackStroke then
      tween(spamTrackStroke, {
        Color = on and onEdge or COLORS.strokeSoft,
        Transparency = on and 0 or 0.4,
        Thickness = 1.4
      })
