    if spamRowStroke then
      tween(spamRowStroke, {
        Color = on and onBg or COLORS.strokeSoft,
        Transparency = on and 0.08 or 0.38,
        Thickness = 1.25
      })
    end
  end
  _G._AmbitiousAntiTPBatSetSpamVisual = setSpamVisual

  spamBtn.Activated:Connect(function()
