    uakLbl.TextSize = 12
    uakLbl.Font = Enum.Font.GothamSemibold
    uakLbl.TextXAlignment = Enum.TextXAlignment.Left
    uakLbl.Position = UDim2.new(0, 12, 0, 0)
    uakLbl.Size = UDim2.new(1, -70, 1, 0)
    uakLbl.ZIndex = 5
    uakLbl.Parent = uakRow

    local uakTrack = Instance.new("Frame")
    uakTrack.Name = "Track"
    uakTrack.BackgroundColor3 = COLORS.toggleBg
    uakTrack.BackgroundTransparency = 0.12
    uakTrack.Size = UDim2.new(0, 44, 0, 22)
    uakTrack.Position = UDim2.new(1, -52, 0.5, -11)
    uakTrack.BorderSizePixel = 0
    uakTrack.ZIndex = 5
    uakTrack.Parent = uakRow
    corner(uakTrack, 11)
    local uakTrackStroke = stroke(uakTrack, COLORS.strokeSoft, 1.3, 0.4)

    local uakFill = Instance.new("Frame")
    uakFill.Name = "Fill"
    uakFill.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
    uakFill.BackgroundTransparency = (_G.AmbitiousUAKEnabled == true) and 0 or 1
    uakFill.Size = UDim2.new(1, 0, 1, 0)
    uakFill.BorderSizePixel = 0
    uakFill.ZIndex = 5
    uakFill.Parent = uakTrack
    corner(uakFill, 11)
    local uakFillGrad = Instance.new("UIGradient")
    uakFillGrad.Color = ColorSequence.new({
      ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
      ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
      ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
    })
    uakFillGrad.Rotation = 18
    uakFillGrad.Parent = uakFill

    local uakKnob = Instance.new("Frame")
    uakKnob.Name = "Knob"
    uakKnob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    uakKnob.Size = UDim2.new(0, 16, 0, 16)
    uakKnob.Position = (_G.AmbitiousUAKEnabled == true)
      and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)
    uakKnob.BorderSizePixel = 0
    uakKnob.ZIndex = 7
    uakKnob.Parent = uakTrack
    corner(uakKnob, 999)
    local uakKnobStroke = Instance.new("UIStroke")
    uakKnobStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    uakKnobStroke.Color = (_G.AmbitiousUAKEnabled == true)
      and Color3.fromRGB(200, 200, 210) or Color3.fromRGB(120, 120, 135)
    uakKnobStroke.Thickness = 1.4
    uakKnobStroke.Transparency = 0.15
    uakKnobStroke.Parent = uakKnob

    local uakShine = Instance.new("Frame")
    uakShine.BackgroundColor3 = COLORS.white
    uakShine.BackgroundTransparency = 0.55
    uakShine.Size = UDim2.new(1, -5, 0, 5)
    uakShine.Position = UDim2.new(0, 2.5, 0, 2.5)
    uakShine.BorderSizePixel = 0
    uakShine.ZIndex = 8
    uakShine.Parent = uakKnob
    corner(uakShine, 5)
    _G._AmbitiousRegAccent(uakFill, uakFillGrad, "toggle", uakTrack, uakKnob, uakRow)

    local function uakPaint(on)
      local onBg, onEdge = _G._AmbitiousToggleOnColor()
      tween(uakKnob, {Position = on and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8)})
      tween(uakTrack, {
        BackgroundTransparency = on and 0 or 0.12,
        BackgroundColor3 = on and onBg or COLORS.toggleBg
      })
      tween(uakFill, {BackgroundTransparency = on and 0 or 1})
      tween(uakKnobStroke, {Color = on and onEdge or Color3.fromRGB(120, 120, 135)})
      tween(uakTrackStroke, {
        Color = on and onEdge or COLORS.strokeSoft,
        Transparency = on and 0 or 0.4,
        Thickness = 1.4
      })
      tween(uakStroke, {
        Color = on and onBg or COLORS.strokeSoft,
        Transparency = on and 0.08 or 0.38,
        Thickness = 1.25
      })
    end
    _G.AmbitiousRefreshUAKVisual = function()
      uakPaint(_G.AmbitiousUAKEnabled == true)
    end

    local uakBtn = Instance.new("TextButton")
    uakBtn.Name = "ToggleButton"
    uakBtn.BackgroundTransparency = 1
    uakBtn.Text = ""
    uakBtn.Size = UDim2.new(1, 0, 1, 0)
    uakBtn.AutoButtonColor = false
    uakBtn.ZIndex = 9
    uakBtn.Parent = uakRow
    uakBtn.Activated:Connect(function()
      _G.AmbitiousUAKEnabled = not (_G.AmbitiousUAKEnabled == true)
      -- Spento a muro alzato: va tolto subito, se no resti chiuso dentro
      -- fino alla scadenza del timer.
      if not _G.AmbitiousUAKEnabled and _G.AmbitiousUltimateAntiKick then
        pcall(_G.AmbitiousUltimateAntiKick.clear)
      end
      uakPaint(_G.AmbitiousUAKEnabled)
      saveAmbitiousConfig()
    end)
    uakPaint(_G.AmbitiousUAKEnabled == true)

    -- ---- freccetta sulla riga Kick Warning ----
    local kwArrow = Instance.new("TextButton")
    kwArrow.Name = "KickWarningArrow"
    kwArrow.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    kwArrow.BackgroundTransparency = 0.18
    kwArrow.BorderSizePixel = 0
    kwArrow.Size = UDim2.new(0, 28, 0, 24)
    kwArrow.Position = UDim2.new(1, -90, 0.5, -12)
    kwArrow.Text = "\u{25B2}"
    kwArrow.TextColor3 = COLORS.white
    kwArrow.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    kwArrow.TextStrokeTransparency = 0.3
    kwArrow.TextSize = 15
    kwArrow.Font = Enum.Font.GothamBold
    kwArrow.AutoButtonColor = false
    kwArrow.ZIndex = 8
    kwArrow.Parent = rowKW
    corner(kwArrow, 7)
    stroke(kwArrow, COLORS.strokeSoft, 1, 0.45)

    local kwExpanded = false
    kwArrow.Activated:Connect(function()
      kwExpanded = not kwExpanded
      _G._AmbitiousExpand(kwHolder, kwExpanded, 38, kwArrow)
    end)

    local _kwBtn = rowKW and rowKW:FindFirstChild("ToggleButton")
    if _kwBtn then
      _kwBtn.Activated:Connect(function()
        _G._AmbitiousKickWarn.enabled = not _G._AmbitiousKickWarn.enabled
        if not _G._AmbitiousKickWarn.enabled then
          if _G.AmbitiousDestroyKickWarning then _G.AmbitiousDestroyKickWarning() end
        else
          local _c = LP.Character
          local _h = _c and _c:FindFirstChildOfClass("Humanoid")
          _G._AmbitiousKickWarn.wasLow = (_h ~= nil) and (_h.WalkSpeed < 25) or false
        end
        if setVisualKW then setVisualKW(_G._AmbitiousKickWarn.enabled) end
        saveAmbitiousConfig()
      end)
    end
  end

  -- High Ping Warning subito sotto il Kick Warning e la sua tendina:
  -- stesso LayoutOrder 8, creata dopo.
  do
    local rowHPW, setVisualHPW = toggleRow(Utility, "High Ping Warning", highPingWarningEnabled, 8)
    _SV.setHighPingWarningVisual = setVisualHPW
    local _hpwBtn = rowHPW and rowHPW:FindFirstChild("ToggleButton")
    if _hpwBtn then
      _hpwBtn.Activated:Connect(function()
        highPingWarningEnabled = not highPingWarningEnabled
        if not highPingWarningEnabled then
          local existingWarning = HubGui:FindFirstChild("AmbitiousHubPingWarning")
          if existingWarning then pcall(function() existingWarning:Destroy() end) end
          _G._AmbitiousHPWNextAllowed = 0
        end
        if setVisualHPW then setVisualHPW(highPingWarningEnabled) end
        saveAmbitiousConfig()
      end)
    end
  end

  -- ===== ANIMATION PACKS =====
  section(Utility, "ANIMATION PACKS", 10)
  do
    -- >>> CUSTOM ANIM PACK BEGIN
    -- Settimo segmento: CUSTOM. Su due righe perche' a un settimo di riga
    -- "CUSTOM" per intero non ci sta, e rimpicciolire il testo lo avrebbe
    -- reso diverso da tutti gli altri.
    local PACK_LABELS = {"NONE", "1", "2", "3", "4", "5", "CUS\nTOM"}
    -- <<< CUSTOM ANIM PACK END
    local NUM_PACKS = #PACK_LABELS  -- 7

    -- Holder principale (occupa tutta la riga, come stretch rez)
    local animPackHolder = Instance.new("Frame")
    animPackHolder.Name = "Animation Pack Selector"
    animPackHolder.BackgroundColor3 = COLORS.row
    animPackHolder.BackgroundTransparency = 0.28
    animPackHolder.Size = UDim2.new(1, -4, 0, 42)
    animPackHolder.BorderSizePixel = 0
    -- LayoutOrder INTERO: e' un intero nella proprieta', e un 10.5 verrebbe
    -- arrotondato con l'ordine deciso dal nome. A parita' di ordine il nome
    -- decide, e "ANIMATION PACKS" < "Animation Pack Selector" <
    -- "Custom Animation Pack": esattamente l'ordine voluto.
    animPackHolder.LayoutOrder = 10
    animPackHolder.ZIndex = 4
    animPackHolder.ClipsDescendants = true
    animPackHolder.Parent = Utility
    corner(animPackHolder, 14)
    stroke(animPackHolder, Color3.fromRGB(110, 110, 120), 1.4, 0.32)
    _G._AmbitiousRegAccent(animPackHolder, nil, "soft")

    -- Slide indicator (si muove orizzontalmente)
    local animSlide = Instance.new("Frame")
    animSlide.Name = "AnimSlide"
    animSlide.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
    animSlide.BackgroundTransparency = 0.1
    animSlide.AnchorPoint = Vector2.new(0.5, 0.5)
    animSlide.Size = UDim2.new(1/NUM_PACKS, -4, 1, -8)
    animSlide.Position = UDim2.new(0.5/NUM_PACKS, 0, 0.5, 0)
    animSlide.BorderSizePixel = 0
    animSlide.ZIndex = 5
    animSlide.Parent = animPackHolder
    corner(animSlide, 13)
    local animSlideStroke = Instance.new("UIStroke")
    animSlideStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    animSlideStroke.Color = Color3.fromRGB(200, 200, 210)
    animSlideStroke.Thickness = 1.5
    animSlideStroke.Transparency = 0.1
    animSlideStroke.Parent = animSlide
    local animSlideGrad = Instance.new("UIGradient")
    animSlideGrad.Color = ColorSequence.new({
      ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
      ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
      ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
    })
    animSlideGrad.Transparency = NumberSequence.new({
      NumberSequenceKeypoint.new(0, 0.08),
      NumberSequenceKeypoint.new(0.5, 0.02),
      NumberSequenceKeypoint.new(1, 0.08),
    })
    animSlideGrad.Parent = animSlide
    _G._AmbitiousRegAccent(animSlide, animSlideGrad, "slide")
    animSlideGrad.Rotation = 22

    -- Crea label e click per ogni bottone
    local animBtnLabels = {}
    local segW = 1 / NUM_PACKS
    for i, label in ipairs(PACK_LABELS) do
      local lbl = Instance.new("TextLabel")
      lbl.Name = "AnimPackLabel_" .. tostring(i)
      lbl.BackgroundTransparency = 1
      lbl.Text = label
      lbl.TextColor3 = COLORS.white
      lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
      lbl.TextStrokeTransparency = 0.2
      lbl.TextSize = 10
      lbl.Font = Enum.Font.GothamBlack
      lbl.TextXAlignment = Enum.TextXAlignment.Center
      lbl.TextYAlignment = Enum.TextYAlignment.Center
      lbl.LineHeight = 0.92   -- le due righe di CUS/TOM restano compatte
      -- >>> CUSTOM ANIM PACK BEGIN
      -- Ancoraggio al CENTRO. Posizionando dal bordo sinistro, la posizione
      -- del riquadro e la sua meta' larghezza vengono arrotondate a intero
      -- separatamente, e i due errori si sommano in modo diverso da un
      -- segmento all'altro: e' per questo che un numero solo (il "5")
      -- risultava spostato di un pixel. Con AnchorPoint 0.5 il centro e'
      -- l'unica cosa calcolata, quindi c'e' UN solo arrotondamento e tutti
      -- i segmenti si comportano allo stesso modo.
      -- <<< CUSTOM ANIM PACK END
      lbl.AnchorPoint = Vector2.new(0.5, 0.5)
      lbl.Size = UDim2.new(segW, 0, 1, 0)
      lbl.Position = UDim2.new(segW * (i - 0.5), 0, 0.5, 0)
      lbl.ZIndex = 8
      lbl.Parent = animPackHolder
      animBtnLabels[i] = lbl

      local clickBtn = Instance.new("TextButton")
      clickBtn.Name = "AnimPackClick_" .. tostring(i)
      clickBtn.BackgroundTransparency = 1
      clickBtn.Text = ""
      clickBtn.AutoButtonColor = false
      clickBtn.AnchorPoint = Vector2.new(0.5, 0.5)
      clickBtn.Size = UDim2.new(segW, 0, 1, 0)
      clickBtn.Position = UDim2.new(segW * (i - 0.5), 0, 0.5, 0)
      clickBtn.ZIndex = 10
      clickBtn.Parent = animPackHolder
      local idx = i
      clickBtn.MouseButton1Click:Connect(function()
        if _G.AmbitiousSetAnimPack then _G.AmbitiousSetAnimPack(idx) end
      end)
    end

    -- Funzione che aggiorna la posizione dello slide e la trasparenza dei testi
    -- con velocità proporzionale alla distanza (come stretch rez)
    local function applyAnimPackVisual(index)
      index = math.clamp(tonumber(index) or 1, 1, NUM_PACKS)
      local segW_scalar = 1 / NUM_PACKS
      -- Velocità di transizione proporzionale alla distanza
      local prevIdx = selectedAnimPackIndex or 1
      local dist = math.abs(index - prevIdx)
      local tweenTime = (dist <= 1) and 0.18 or math.clamp(0.08 * dist + 0.10, 0.18, 0.42)
      -- >>> CUSTOM ANIM PACK BEGIN
      -- Geometria SIMMETRICA. Prima la pillola era spostata di -1 px e
      -- larga -3: il suo centro cadeva 2.5 px a sinistra del centro del
      -- segmento, mentre le label sono centrate sul segmento. Da qui il
      -- testo che sembra spinto a destra dentro la pillola (e sul primo
      -- segmento, con l'offset +4, spinto a sinistra).
      -- Con +2 di posizione e -4 di larghezza il centro della pillola
      -- coincide esattamente con quello della label, per ogni indice.
      -- Stesso centro delle label: concentrici per costruzione.
      tween(animSlide, {
        Position = UDim2.new(segW_scalar * (index - 0.5), 0, 0.5, 0),
        Size = UDim2.new(segW_scalar, -4, 1, -8),
      }, tweenTime)
      -- <<< CUSTOM ANIM PACK END
      for i, lbl in ipairs(animBtnLabels) do
        local isSelected = (i == index)
        tween(lbl, {
          TextTransparency = isSelected and 0 or 0.22,
          TextStrokeTransparency = isSelected and 0.2 or 0.45,
        }, 0.14)
      end
    end

    -- Esponi il visual callback al sistema logico
    setAnimPackVisual = applyAnimPackVisual

    -- Inizializza visuale con il valore caricato dal config
    applyAnimPackVisual(selectedAnimPackIndex or 1)
  end

  -- >>> CUSTOM ANIM PACK BEGIN
  -- ===== CUSTOM ANIMATION PACK ROW + PICKER =====
  ;(function()
    local SLOTS  = _G.AmbitiousCustomAnimSlots
    local LABELS = _G.AmbitiousCustomAnimLabels

    -- ---------- LA RIGA ----------
    local capRow = baseRow(Utility, "Custom Animation Pack", 10)
    capRow.Size = UDim2.new(1, -4, 0, 42)
    -- >>> VISIBILE SOLO CON CUSTOM <<<
    -- La riga serve solo quando e' selezionato il pack CUSTOM (indice 7).
    -- Compare e scompare con la stessa animazione a tendina delle freccette.
    capRow.ClipsDescendants = true
    capRow.Visible = false

    local capHolder = Instance.new("Frame")
    capHolder.Name = "CustomAnimBtnHolder"
    capHolder.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
    capHolder.BackgroundTransparency = 0.28
    capHolder.BorderSizePixel = 0
    capHolder.Size = UDim2.new(0, 66, 0, 30)
    capHolder.Position = UDim2.new(1, -73, 0.5, -15)
    capHolder.ClipsDescendants = true
    capHolder.ZIndex = 6
    capHolder.Parent = capRow
    corner(capHolder, 15)
    stroke(capHolder, Color3.fromRGB(200, 200, 210), 1.5, 0.15)

    local capGrad = Instance.new("UIGradient")
    capGrad.Color = ColorSequence.new({
      ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
      ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
      ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
    })
    capGrad.Rotation = 18
    capGrad.Parent = capHolder
    _G._AmbitiousRegAccent(capHolder, capGrad, "pick")

    local capBtn = Instance.new("TextButton")
    capBtn.Name = "CustomAnimButton"
    capBtn.BackgroundTransparency = 1
    capBtn.Text = "PICK"
    capBtn.TextColor3 = COLORS.white
    capBtn.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    capBtn.TextStrokeTransparency = 0.3
    capBtn.TextSize = 12
    capBtn.Font = Enum.Font.GothamBlack
    capBtn.TextXAlignment = Enum.TextXAlignment.Center
    capBtn.Size = UDim2.new(1, 0, 1, 0)
    capBtn.Position = UDim2.new(0, 0, 0, 0)
    capBtn.BorderSizePixel = 0
    capBtn.ZIndex = 8
    capBtn.AutoButtonColor = false
    capBtn.Parent = capHolder
    capBtn.MouseEnter:Connect(function()
      tween(capHolder, {Size = UDim2.new(0, 72, 0, 32), Position = UDim2.new(1, -76, 0.5, -16)}, 0.12)
    end)
    capBtn.MouseLeave:Connect(function()
      tween(capHolder, {Size = UDim2.new(0, 66, 0, 30), Position = UDim2.new(1, -73, 0.5, -15)}, 0.12)
    end)

    -- Il contatore accanto al PICK e' stato tolto: quanti slot sono
    -- impostati si vede aprendo il picker, e nessun'altra riga della hub
    -- mostra un valore li'.
    local function refreshCount() end
    _G.AmbitiousCustomAnimRefreshRow = refreshCount

    -- >>> VISIBILE SOLO CON CUSTOM <<<
    -- animate = false allo start e al load config (deve solo trovarsi gia'
    -- nello stato giusto), true quando l'utente cambia pack.
    _G.AmbitiousCustomAnimSetRowVisible = function(show, animate)
      show = show and true or false
      if animate == false then
        capRow.Visible = show
        capRow.Size = UDim2.new(1, -4, 0, show and 42 or 0)
        return
      end
      if show then
        if capRow.Visible and capRow.Size.Y.Offset >= 42 then return end
        capRow.Visible = true
        capRow.Size = UDim2.new(1, -4, 0, 0)
        tween(capRow, {Size = UDim2.new(1, -4, 0, 42)}, 0.22)
      else
        if not capRow.Visible then return end
        tween(capRow, {Size = UDim2.new(1, -4, 0, 0)}, 0.18)
        task.delay(0.19, function()
          if capRow.Parent and capRow.Size.Y.Offset <= 1 then capRow.Visible = false end
        end)
      end
    end

    _G.AmbitiousCustomAnimSetRowVisible(selectedAnimPackIndex == 7, false)

    -- ---------- IL PICKER ----------
    local capGui = nil
    local cardRefs = {}
    -- Stessa guardia del Tab Position: il backdrop non assorbe il click,
    -- quindi senza questa il PICK richiuderebbe e riaprirebbe subito.
    local capJustClosedAt = 0

    -- Dissolvenza come gli altri picker, non rimpicciolimento.
    local function closeCap()
      if capGui and capGui.Parent then
        local f = capGui:FindFirstChild("Frame")
        if f then
          TweenService:Create(f, TweenInfo.new(0.2), {BackgroundTransparency = 1}):Play()
        end
        local g = capGui
        capGui = nil
        cardRefs = {}
        capJustClosedAt = tick()
        task.delay(0.25, function() pcall(function() g:Destroy() end) end)
      end
    end
    _G.AmbitiousCustomAnimClose = closeCap

    -- Aggiorna una card dopo che l'ID e' stato messo o tolto.
    local function refreshCard(slot)
      local r = cardRefs[slot]
      if not r then return end
      local id = _G.AmbitiousCustomAnimIds[slot] or ""
      if id ~= "" then
        r.mark.Text = "\u{2713}"
        r.mark.TextSize = 18
        r.mark.TextColor3 = Color3.fromRGB(120, 220, 150)
        r.sub.Text = id
        r.sub.TextSize = 9
        r.sub.TextColor3 = Color3.fromRGB(120, 220, 150)
        r.stroke.Color = Color3.fromRGB(120, 220, 150)
        r.stroke.Thickness = 1.5
        r.stroke.Transparency = 0.12
        r.clear.Visible = true
      else
        r.mark.Text = "+"
        r.mark.TextSize = 24
        r.mark.TextColor3 = Color3.fromRGB(200, 200, 215)
        r.sub.Text = "ADD"
        r.sub.TextSize = 10
        r.sub.TextColor3 = Color3.fromRGB(140, 140, 155)
        r.stroke.Color = Color3.fromRGB(50, 50, 58)
        r.stroke.Thickness = 1
        r.stroke.Transparency = 0.5
        r.clear.Visible = false
      end
      refreshCount()
    end

    -- ---------- MINI POPUP ASSET ID (stile Custom Background) ----------
    local function openAssetPopup(slot)
      if not capGui or not capGui.Parent then return end
      local pickerMain = capGui:FindFirstChild("Frame")
      if not pickerMain then return end

      local miniOverlay = Instance.new("Frame")
      miniOverlay.Name = "AddAnimMiniOverlay"
      miniOverlay.Size = UDim2.new(1, 0, 1, 0)
      miniOverlay.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
      miniOverlay.BackgroundTransparency = 0.48
      miniOverlay.BorderSizePixel = 0
      miniOverlay.ZIndex = 100
      miniOverlay.Parent = pickerMain
      local oc = Instance.new("UICorner")
      oc.CornerRadius = UDim.new(0, 16)
      oc.Parent = miniOverlay

      local outsideClose = Instance.new("TextButton")
      outsideClose.Size = UDim2.new(1, 0, 1, 0)
      outsideClose.BackgroundTransparency = 1
      outsideClose.Text = ""
      outsideClose.AutoButtonColor = false
      outsideClose.ZIndex = 100
      outsideClose.Parent = miniOverlay
      outsideClose.MouseButton1Click:Connect(function() miniOverlay:Destroy() end)

      local miniPanel = Instance.new("Frame")
      miniPanel.Name = "AddAnimPanel"
      miniPanel.AnchorPoint = Vector2.new(0.5, 0.5)
      miniPanel.Position = UDim2.new(0.5, 0, 0.5, 0)
      miniPanel.Size = UDim2.new(0, 300, 0, 158)
      miniPanel.BackgroundColor3 = Color3.fromRGB(6, 6, 9)
      miniPanel.BorderSizePixel = 0
      miniPanel.ZIndex = 101
      miniPanel.ClipsDescendants = true
      miniPanel.Parent = miniOverlay
      corner(miniPanel, 16)
      stroke(miniPanel, COLORS.stroke, 1.1, 0.3)

      local mHeader = Instance.new("Frame")
      mHeader.Size = UDim2.new(1, 0, 0, 42)
      mHeader.BackgroundColor3 = Color3.fromRGB(10, 10, 14)
      mHeader.BackgroundTransparency = 0.1
      mHeader.BorderSizePixel = 0
      mHeader.ZIndex = 102
      mHeader.Parent = miniPanel
      corner(mHeader, 16)

      local mTitle = Instance.new("TextLabel")
      mTitle.Size = UDim2.new(1, -52, 1, 0)
      mTitle.Position = UDim2.new(0, 14, 0, 0)
      mTitle.BackgroundTransparency = 1
      mTitle.Text = "ASSET ID  \u{2014}  " .. (LABELS[slot] or slot)
      mTitle.TextColor3 = COLORS.white
      mTitle.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
      mTitle.TextStrokeTransparency = 0.3
      mTitle.Font = Enum.Font.GothamBlack
      mTitle.TextSize = 13
      mTitle.TextXAlignment = Enum.TextXAlignment.Left
      mTitle.ZIndex = 103
      mTitle.Parent = mHeader

      local mCloseBtn = Instance.new("TextButton")
      mCloseBtn.Size = UDim2.new(0, 28, 0, 28)
      mCloseBtn.Position = UDim2.new(1, -36, 0.5, -14)
      mCloseBtn.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
      mCloseBtn.BackgroundTransparency = 0.28
      mCloseBtn.BorderSizePixel = 0
      mCloseBtn.Text = "-"
      mCloseBtn.TextColor3 = COLORS.white
      mCloseBtn.TextSize = 18
      mCloseBtn.Font = Enum.Font.GothamSemibold
      mCloseBtn.AutoButtonColor = false
      mCloseBtn.ZIndex = 104
      mCloseBtn.Parent = mHeader
      corner(mCloseBtn, 8)
      stroke(mCloseBtn, COLORS.stroke, 1, 0.35)
      mCloseBtn.MouseButton1Click:Connect(function() miniOverlay:Destroy() end)

      local mDivider = Instance.new("Frame")
      mDivider.Size = UDim2.new(1, -28, 0, 1)
      mDivider.Position = UDim2.new(0, 14, 0, 42)
      mDivider.BackgroundColor3 = Color3.fromRGB(70, 70, 82)
      mDivider.BackgroundTransparency = 0.45
      mDivider.BorderSizePixel = 0
      mDivider.ZIndex = 102
      mDivider.Parent = miniPanel

      local mBoxHolder = Instance.new("Frame")
      mBoxHolder.Size = UDim2.new(1, -24, 0, 36)
      mBoxHolder.Position = UDim2.new(0, 12, 0, 52)
      mBoxHolder.BackgroundColor3 = COLORS.row2
      mBoxHolder.BackgroundTransparency = 0.1
      mBoxHolder.BorderSizePixel = 0
      mBoxHolder.ZIndex = 102
      mBoxHolder.Parent = miniPanel
      corner(mBoxHolder, 9)
      stroke(mBoxHolder, COLORS.strokeSoft, 1, 0.38)

      local mBox = Instance.new("TextBox")
      mBox.Name = "AssetInput"
      mBox.Size = UDim2.new(1, -16, 1, 0)
      mBox.Position = UDim2.new(0, 8, 0, 0)
      mBox.BackgroundTransparency = 1
      mBox.BorderSizePixel = 0
      mBox.PlaceholderText = "Insert The Asset ID"
      mBox.PlaceholderColor3 = Color3.fromRGB(80, 80, 92)
      mBox.Text = _G.AmbitiousCustomAnimIds[slot] or ""
      mBox.TextColor3 = COLORS.white
      mBox.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
      mBox.TextStrokeTransparency = 0.4
      mBox.Font = Enum.Font.GothamSemibold
      mBox.TextSize = 12
      mBox.ClearTextOnFocus = false
      mBox.ZIndex = 103
      mBox.Parent = mBoxHolder

      local mErr = Instance.new("TextLabel")
      mErr.Size = UDim2.new(1, -24, 0, 14)
      mErr.Position = UDim2.new(0, 12, 0, 94)
      mErr.BackgroundTransparency = 1
      mErr.Text = ""
      mErr.TextColor3 = Color3.fromRGB(255, 75, 75)
      mErr.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
      mErr.TextStrokeTransparency = 0.4
      mErr.Font = Enum.Font.GothamSemibold
      mErr.TextSize = 10
      mErr.TextXAlignment = Enum.TextXAlignment.Left
      mErr.ZIndex = 102
      mErr.Parent = miniPanel

      local mConfirmHolder = Instance.new("Frame")
      mConfirmHolder.Size = UDim2.new(1, -24, 0, 32)
      mConfirmHolder.Position = UDim2.new(0, 12, 0, 114)
      mConfirmHolder.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
      mConfirmHolder.BackgroundTransparency = 0.28
      mConfirmHolder.BorderSizePixel = 0
      mConfirmHolder.ZIndex = 102
      mConfirmHolder.Parent = miniPanel
      corner(mConfirmHolder, 9)
      stroke(mConfirmHolder, Color3.fromRGB(235, 235, 245), 1, 0.28)

      local mConfirm = Instance.new("TextButton")
      mConfirm.Size = UDim2.new(1, 0, 1, 0)
      mConfirm.BackgroundTransparency = 1
      mConfirm.BorderSizePixel = 0
      mConfirm.Text = "CONFIRM"
      mConfirm.TextColor3 = COLORS.white
      mConfirm.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
      mConfirm.TextStrokeTransparency = 0.22
      mConfirm.Font = Enum.Font.GothamBlack
      mConfirm.TextSize = 11
      mConfirm.AutoButtonColor = false
      mConfirm.ZIndex = 103
      mConfirm.Parent = mConfirmHolder
      mConfirm.MouseEnter:Connect(function()
        TweenService:Create(mConfirmHolder, TweenInfo.new(0.12), {BackgroundTransparency = 0.1}):Play()
      end)
      mConfirm.MouseLeave:Connect(function()
        TweenService:Create(mConfirmHolder, TweenInfo.new(0.12), {BackgroundTransparency = 0.28}):Play()
      end)

      local isChecking = false
      local function tryConfirm()
        if isChecking then return end
        local raw = mBox.Text:match("^%s*(.-)%s*$")
        if raw == "" then mErr.Text = "Invalid Asset Please Try Again" return end
        local assetId = raw:match("^(%d+)$") or raw:match("rbxassetid://(%d+)$")
        if not assetId then mErr.Text = "Invalid Asset Please Try Again" return end

        isChecking = true
        mErr.Text = ""
        mConfirm.Text = "CHECKING..."
        TweenService:Create(mConfirmHolder, TweenInfo.new(0.12), {BackgroundTransparency = 0.55}):Play()

        task.spawn(function()
          -- Validazione come Uranium: si scarica l'asset e si cerca dentro
          -- una Animation. Un ID che carica ma non contiene animazioni non
          -- va accettato, altrimenti il pack parte e non si muove niente.
          local url = "rbxassetid://" .. assetId
          local valid = false
          pcall(function()
            local objs = game:GetObjects(url)
            if objs then
              for _, obj in pairs(objs) do
                if obj:IsA("Animation") then valid = true return end
                local deep = obj:FindFirstChildWhichIsA("Animation", true)
                if deep then valid = true return end
              end
            end
          end)
          -- Ripiego: alcuni asset non tornano oggetti ma esistono davvero.
          if not valid then
            local tempImg = Instance.new("ImageLabel")
            tempImg.Image = url
            tempImg.Parent = miniOverlay
            local timeout = tick() + 4
            repeat task.wait(0.05) until tempImg.IsLoaded or tick() > timeout
            valid = tempImg.IsLoaded
            tempImg:Destroy()
          end

          if not miniOverlay or not miniOverlay.Parent then return end
          if valid then
            _G.AmbitiousCustomAnimIds[slot] = assetId
            refreshCard(slot)
            saveAmbitiousConfig()
            if _G.AmbitiousReloadCustomAnimPack then
              pcall(_G.AmbitiousReloadCustomAnimPack)
            end
            miniOverlay:Destroy()
          else
            isChecking = false
            mErr.Text = "Invalid Asset Please Try Again"
            mConfirm.Text = "CONFIRM"
            TweenService:Create(mConfirmHolder, TweenInfo.new(0.12), {BackgroundTransparency = 0.28}):Play()
          end
        end)
      end

      mConfirm.MouseButton1Click:Connect(tryConfirm)
      mBox.FocusLost:Connect(function(enter) if enter then tryConfirm() end end)
      task.delay(0.05, function() if mBox and mBox.Parent then mBox:CaptureFocus() end end)
    end

    -- ---------- APERTURA DEL PICKER ----------
    capBtn.Activated:Connect(function()
      if capGui and capGui.Parent then closeCap() return end
      if tick() - capJustClosedAt < 0.25 then return end

      capGui = Instance.new("ScreenGui")
      capGui.Name = "AmbitiousHubCustomAnimPicker"
      capGui.ResetOnSpawn = false
      capGui.IgnoreGuiInset = true
      capGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
      capGui.DisplayOrder = 9999
      capGui.Parent = HubGui

      local backdrop = Instance.new("Frame")
      backdrop.Name = "Backdrop"
      backdrop.Size = UDim2.new(1, 0, 1, 0)
      backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
      backdrop.BackgroundTransparency = 0.5
      backdrop.BorderSizePixel = 0
      backdrop.ZIndex = 1
      backdrop.Parent = capGui
      backdrop.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
          or input.UserInputType == Enum.UserInputType.Touch then closeCap() end
      end)

      local frame = Instance.new("Frame")
      frame.Name = "Frame"
      frame.BackgroundColor3 = Color3.fromRGB(8, 8, 10)
      frame.BorderSizePixel = 0
      frame.ZIndex = 2
      frame.Parent = capGui
      corner(frame, 16)
      stroke(frame, Color3.fromRGB(90, 90, 105), 1.2, 0.3)

      local titleBar = Instance.new("Frame")
      titleBar.Size = UDim2.new(1, 0, 0, 48)
      titleBar.BackgroundColor3 = Color3.fromRGB(12, 12, 15)
      titleBar.BackgroundTransparency = 0.15
      titleBar.BorderSizePixel = 0
      titleBar.ZIndex = 3
      titleBar.Parent = frame
      corner(titleBar, 16)

      local title = Instance.new("TextLabel")
      title.BackgroundTransparency = 1
      title.Text = "CUSTOM ANIMATION PACK"
      title.TextColor3 = Color3.fromRGB(255, 255, 255)
      title.Font = Enum.Font.GothamBlack
      title.TextSize = 16
      title.TextXAlignment = Enum.TextXAlignment.Left
      title.Size = UDim2.new(1, -60, 1, 0)
      title.Position = UDim2.new(0, 18, 0, 0)
      title.ZIndex = 4
      title.Parent = titleBar

      -- Chiusura del popup GRANDE: X, come tutti gli altri picker della hub
      -- (Custom Background, Sky Theme, Music Player). Il "-" resta solo sul
      -- mini popup dell'Asset ID, dove la Custom Background usa quello.
      local closeBtn = Instance.new("TextButton")
      closeBtn.Name = "CloseBtn"
      closeBtn.Size = UDim2.new(0, 36, 0, 36)
      closeBtn.Position = UDim2.new(1, -44, 0, 6)
      closeBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 28)
      closeBtn.BackgroundTransparency = 0.1
      closeBtn.BorderSizePixel = 0
      closeBtn.Text = "X"
      closeBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
      closeBtn.Font = Enum.Font.GothamBlack
      closeBtn.TextSize = 14
      closeBtn.AutoButtonColor = false
      closeBtn.ZIndex = 4
      closeBtn.Parent = titleBar
      corner(closeBtn, 10)
      stroke(closeBtn, Color3.fromRGB(90, 90, 105), 1, 0.4)
      closeBtn.MouseEnter:Connect(function()
        TweenService:Create(closeBtn, TweenInfo.new(0.12), {BackgroundColor3 = Color3.fromRGB(180, 50, 50)}):Play()
      end)
      closeBtn.MouseLeave:Connect(function()
        TweenService:Create(closeBtn, TweenInfo.new(0.12), {BackgroundColor3 = Color3.fromRGB(25, 25, 28)}):Play()
      end)
      closeBtn.Activated:Connect(closeCap)

      -- Contenuto dentro una ScrollingFrame, esattamente come il Background
      -- Changer: e' quella a dare a tutti i picker della hub lo stesso
      -- comportamento in apertura, perche' ritaglia da sola e il contenuto
      -- resta contenuto mentre il riquadro cresce.
      local scrollFrame = Instance.new("ScrollingFrame")
      scrollFrame.Name = "Scroll"
      scrollFrame.Size = UDim2.new(1, -16, 1, -64)
      scrollFrame.Position = UDim2.new(0, 8, 0, 56)
      scrollFrame.BackgroundTransparency = 1
      scrollFrame.BorderSizePixel = 0
      scrollFrame.ScrollBarThickness = 4
      scrollFrame.ScrollBarImageColor3 = Color3.fromRGB(80, 80, 90)
      scrollFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
      scrollFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
      scrollFrame.ZIndex = 3
      scrollFrame.Parent = frame

      local grid = Instance.new("UIGridLayout")
      grid.CellSize = UDim2.new(0, 165, 0, 76)
      grid.CellPadding = UDim2.new(0, 8, 0, 8)
      grid.FillDirection = Enum.FillDirection.Horizontal
      grid.HorizontalAlignment = Enum.HorizontalAlignment.Center
      grid.SortOrder = Enum.SortOrder.LayoutOrder
      grid.Parent = scrollFrame

      local gridPad = Instance.new("UIPadding", scrollFrame)
      gridPad.PaddingLeft = UDim.new(0, 8)
      gridPad.PaddingTop = UDim.new(0, 8)
      gridPad.PaddingRight = UDim.new(0, 8)
      gridPad.PaddingBottom = UDim.new(0, 8)

      cardRefs = {}
      for i, slot in ipairs(SLOTS) do
        local card = Instance.new("TextButton")
        card.Name = slot
        card.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
        card.BorderSizePixel = 0
        card.Text = ""
        card.AutoButtonColor = false
        card.LayoutOrder = i
        card.ZIndex = 3
        card.Parent = scrollFrame
        corner(card, 12)
        local cs = stroke(card, Color3.fromRGB(50, 50, 58), 1, 0.5)

        local nameLbl = Instance.new("TextLabel")
        nameLbl.BackgroundTransparency = 1
        nameLbl.Text = LABELS[slot] or slot
        nameLbl.TextColor3 = COLORS.white
        nameLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        nameLbl.TextStrokeTransparency = 0.3
        nameLbl.Font = Enum.Font.GothamBlack
        nameLbl.TextSize = 11
        nameLbl.TextXAlignment = Enum.TextXAlignment.Left
        nameLbl.Size = UDim2.new(1, -20, 0, 16)
        nameLbl.Position = UDim2.new(0, 12, 0, 8)
        nameLbl.ZIndex = 5
        nameLbl.Parent = card

        local mark = Instance.new("TextLabel")
        mark.BackgroundTransparency = 1
        mark.Font = Enum.Font.GothamBlack
        mark.TextXAlignment = Enum.TextXAlignment.Center
        mark.Size = UDim2.new(0, 30, 0, 30)
        mark.Position = UDim2.new(0, 10, 0, 30)
        mark.ZIndex = 5
        mark.Parent = card

        local sub = Instance.new("TextLabel")
        sub.BackgroundTransparency = 1
        sub.Font = Enum.Font.GothamSemibold
        sub.TextXAlignment = Enum.TextXAlignment.Left
        sub.TextTruncate = Enum.TextTruncate.AtEnd
        sub.Size = UDim2.new(1, -78, 0, 30)
        sub.Position = UDim2.new(0, 42, 0, 30)
        sub.ZIndex = 5
        sub.Parent = card

        -- X identica a quella delle miniature Custom Background: una "X"
        -- maiuscola normale, non il simbolo Unicode. GothamBlack non ha il
        -- glifo U+2715 e Roblox al suo posto disegna il rettangolo del
        -- carattere mancante.
        local clear = Instance.new("TextButton")
        clear.Name = "Clear"
        clear.Size = UDim2.new(0, 22, 0, 22)
        clear.Position = UDim2.new(1, -26, 0, 5)
        clear.BackgroundTransparency = 1
        clear.BorderSizePixel = 0
        clear.Text = "X"
        clear.TextColor3 = Color3.fromRGB(255, 55, 55)
        clear.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        clear.TextStrokeTransparency = 0
        clear.Font = Enum.Font.GothamBlack
        clear.TextSize = 14
        clear.AutoButtonColor = false
        clear.Visible = false
        clear.ZIndex = 9
        clear.Parent = card
        clear.MouseEnter:Connect(function()
          TweenService:Create(clear, TweenInfo.new(0.1), {TextColor3 = Color3.fromRGB(255, 110, 110)}):Play()
        end)
        clear.MouseLeave:Connect(function()
          TweenService:Create(clear, TweenInfo.new(0.1), {TextColor3 = Color3.fromRGB(255, 55, 55)}):Play()
        end)
        clear.MouseButton1Click:Connect(function()
          _G.AmbitiousCustomAnimIds[slot] = ""
          refreshCard(slot)
          saveAmbitiousConfig()
          if _G.AmbitiousReloadCustomAnimPack then
            pcall(_G.AmbitiousReloadCustomAnimPack)
          end
        end)

        card.MouseEnter:Connect(function()
          tween(card, {BackgroundColor3 = Color3.fromRGB(22, 22, 28)}, 0.12)
        end)
        card.MouseLeave:Connect(function()
          tween(card, {BackgroundColor3 = Color3.fromRGB(14, 14, 18)}, 0.12)
        end)
        card.Activated:Connect(function() openAssetPopup(slot) end)

        cardRefs[slot] = {mark = mark, sub = sub, stroke = cs, clear = clear}
        refreshCard(slot)
      end

      frame.Size = UDim2.new(0, 0, 0, 0)
      frame.Position = UDim2.new(0.5, 0, 0.5, 0)
      TweenService:Create(frame, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Size = UDim2.new(0, 380, 0, 336),
        Position = UDim2.new(0.5, -190, 0.5, -168)
      }):Play()
    end)
  end)()
  -- <<< CUSTOM ANIM PACK END

  -- ===== AVATAR (HEADLESS, KORBLOX) =====
  section(Utility, "AVATAR", 11)

  -- ===== AVATAR CHANGER =====
  do
    -- ---- Stato persistente ----
    _G._AmbitiousAvatarChanger = {
      Hair     = { enabled=false, savedId=nil, savedName="" },
      Hats     = { enabled=false, savedId=nil, savedName="" },
      Face     = { enabled=false, savedId=nil, savedName="" },
      Neck     = { enabled=false, savedId=nil, savedName="" },
      Shoulder = { enabled=false, savedId=nil, savedName="" },
      Front    = { enabled=false, savedId=nil, savedName="" },
      Back     = { enabled=false, savedId=nil, savedName="" },
      Waist    = { enabled=false, savedId=nil, savedName="" },
      Shirts   = { enabled=false, savedId=nil, savedName="" },
      Pants    = { enabled=false, savedId=nil, savedName="" },
      ["T-Shirts"] = { enabled=false, savedId=nil, savedName="" },
      Jackets  = { enabled=false, savedId=nil, savedName="" },
      Sweaters = { enabled=false, savedId=nil, savedName="" },
      Bottoms  = { enabled=false, savedId=nil, savedName="" },
    }
    -- Applica i dati caricati dal config se presenti
    if type(_G._AmbitiousAvatarChangerPending) == "table" then
      for k,v in pairs(_G._AmbitiousAvatarChangerPending) do
        if _G._AmbitiousAvatarChanger[k] then
          _G._AmbitiousAvatarChanger[k].enabled   = v.enabled == true
          _G._AmbitiousAvatarChanger[k].savedId   = tonumber(v.savedId)
          _G._AmbitiousAvatarChanger[k].savedName = tostring(v.savedName or "")
        end
      end
      _G._AmbitiousAvatarChangerPending = nil
    end

    local AC_CATEGORIES = {
      { Name="Hair",     AssetTypes={Enum.AvatarAssetType.HairAccessory} },
      { Name="Hats",     AssetTypes={Enum.AvatarAssetType.Hat} },
      { Name="Face",     AssetTypes={Enum.AvatarAssetType.FaceAccessory} },
      { Name="Neck",     AssetTypes={Enum.AvatarAssetType.NeckAccessory} },
      { Name="Shoulder", AssetTypes={Enum.AvatarAssetType.ShoulderAccessory} },
      { Name="Front",    AssetTypes={Enum.AvatarAssetType.FrontAccessory} },
      { Name="Back",     AssetTypes={Enum.AvatarAssetType.BackAccessory} },
      { Name="Waist",    AssetTypes={Enum.AvatarAssetType.WaistAccessory} },
      { Name="Shirts",   AssetTypes={Enum.AvatarAssetType.Shirt} },
      { Name="Pants",    AssetTypes={Enum.AvatarAssetType.Pants} },
      { Name="T-Shirts", AssetTypes={Enum.AvatarAssetType.TShirt} },
      { Name="Jackets",  AssetTypes={Enum.AvatarAssetType.JacketAccessory} },
      { Name="Sweaters", AssetTypes={Enum.AvatarAssetType.SweaterAccessory} },
      { Name="Bottoms",  AssetTypes={Enum.AvatarAssetType.ShortsAccessory} },
    }

    -- ---- Equip ----
    -- Generazione: cresce ad ogni respawn. Serve ad abortire gli equip
    -- rimasti in sospeso su un character ormai vecchio.
    local _acGen = 0
    -- Cache dei template scaricati: il watcher puo' riapplicare un item
    -- molte volte, senza cache ogni volta sarebbe una richiesta di rete.
    local _acAssetCache = {}

    -- Usa l'helper condiviso definito in cima allo script
    local _acWaitCharReady = _G._AmbitiousWaitCharReady

    -- Ritorna true solo se l'item e' stato davvero applicato.
    local function _acEquipItem(itemId, itemType, itemName, gen)
      if not itemId then return false end
      if gen == nil then gen = _acGen end
      local ok, applied = pcall(function()
        local objects
        local cached = _acAssetCache[itemId]
        if cached then
          objects = { cached:Clone() }
        else
          objects = game:GetObjects("rbxassetid://"..tostring(itemId))
          if objects and objects[1] then
            _acAssetCache[itemId] = objects[1]:Clone()
          end
        end
        -- GetObjects fa una richiesta di rete: nel frattempo il character
        -- puo' essere cambiato, quindi si rilegge adesso e non prima.
        if gen ~= _acGen then return false end
        local character = LP.Character
        if not character or not character.Parent then return false end
        if not _acWaitCharReady(character, 5) then return false end
        if gen ~= _acGen then return false end
        if not objects or #objects==0 then return false end
          local item = objects[1]
          if item:IsA("Folder") or item:IsA("Model") then
            local core = item:FindFirstChildOfClass("Accessory")
              or item:FindFirstChildOfClass("Shirt")
              or item:FindFirstChildOfClass("Pants")
              or item:FindFirstChildOfClass("ShirtGraphic")
            if core then item=core end
          end
          if item:IsA("Shirt") then
            for _,c in pairs(character:GetChildren()) do if c:IsA("Shirt") then c:Destroy() end end
            item.Name="ACShirt"; item.Parent=character; return true
          elseif item:IsA("Pants") then
            for _,c in pairs(character:GetChildren()) do if c:IsA("Pants") then c:Destroy() end end
            item.Name="ACPants"; item.Parent=character; return true
          elseif item:IsA("ShirtGraphic") then
            for _,c in pairs(character:GetChildren()) do if c:IsA("ShirtGraphic") then c:Destroy() end end
            item.Name="ACTShirt"; item.Parent=character; return true
          end
          if item:IsA("Accessory") then
            local handle=item:FindFirstChild("Handle")
            if handle then
              if itemType==Enum.AvatarAssetType.HairAccessory then
                for _,c in pairs(character:GetChildren()) do
                  if c:IsA("Accessory") and (c.Name:lower():find("hair") or (c:FindFirstChild("Handle") and c.Handle:FindFirstChild("HairAttachment"))) then c:Destroy() end
                end
              else
                for _,c in pairs(character:GetChildren()) do
                  if c:IsA("Accessory") and (c.Name==itemName or c.Name=="AC"..itemName) then c:Destroy() end
                end
              end
              local attachment=handle:FindFirstChildOfClass("Attachment")
              local targetPart=character:FindFirstChild("Head")
              local targetAttachment=nil
              if attachment then
                for _,bodyPart in pairs(character:GetChildren()) do
                  if bodyPart:IsA("BasePart") then
                    targetAttachment=bodyPart:FindFirstChild(attachment.Name)
                    if targetAttachment then targetPart=bodyPart; break end
                  end
                end
              end
              -- Senza un punto di aggancio valido il weld esplode: meglio
              -- fallire pulito e lasciare che il retry ci riprovi.
              if not targetPart then
                targetPart = character:FindFirstChild("HumanoidRootPart")
              end
              if not targetPart then return false end
              item.Name="AC"..itemName; item.Parent=character
              handle.CFrame=targetPart.CFrame
              for _,j in pairs(handle:GetChildren()) do
                if j:IsA("Weld") or j:IsA("ManualWeld") or j:IsA("WeldConstraint") then j:Destroy() end
              end
              local w=Instance.new("Weld")
              w.Name="ACManualWeld"; w.Part0=handle; w.Part1=targetPart
              if attachment and targetAttachment then w.C0=attachment.CFrame; w.C1=targetAttachment.CFrame
              else w.C0=CFrame.new(0,0.5,0) end
              w.Parent=handle
              return true
            end
          end
          return false
      end)
      return ok and applied == true
    end

    -- ---- Rimuovi item dal character ----
    local function _acRemoveItem(itemType, itemName)
      local character = LP.Character
      if not character then return end
      pcall(function()
        if itemType == Enum.AvatarAssetType.Shirt then
          for _,c in pairs(character:GetChildren()) do
            if c:IsA("Shirt") and (c.Name=="ACShirt" or c.Name==itemName) then c:Destroy() end
          end
        elseif itemType == Enum.AvatarAssetType.Pants then
          for _,c in pairs(character:GetChildren()) do
            if c:IsA("Pants") and (c.Name=="ACPants" or c.Name==itemName) then c:Destroy() end
          end
        elseif itemType == Enum.AvatarAssetType.TShirt then
          for _,c in pairs(character:GetChildren()) do
            if c:IsA("ShirtGraphic") and (c.Name=="ACTShirt" or c.Name==itemName) then c:Destroy() end
          end
        else
          -- Accessory: rimuovi per nome salvato
          for _,c in pairs(character:GetChildren()) do
            if c:IsA("Accessory") and (c.Name=="AC"..itemName or c.Name==itemName) then c:Destroy() end
          end
        end
      end)
    end

    -- ---- Save/Load separato ----
    local function _acSaveConfig()
      pcall(saveAmbitiousConfig)
    end

    -- (load avviene in loadAmbitiousConfig, già eseguita prima di questo blocco)

    -- Applica tutti gli item con toggle ON
    local function _acApplyAll(gen)
      if gen == nil then gen = _acGen end
      -- Si aspetta che il character sia completo PRIMA di iniziare:
      -- l'attesa a tempo fisso era la causa degli item saltati al reset.
      local character = LP.Character
      if not character then return end
      if not _acWaitCharReady(character, 10) then return end
      if gen ~= _acGen then return end

      for _,cat in ipairs(AC_CATEGORIES) do
        if gen ~= _acGen then return end   -- respawn nel frattempo: si abortisce
        local entry=_G._AmbitiousAvatarChanger[cat.Name]
        if entry and entry.enabled and entry.savedId then
          -- Fino a 3 tentativi: se l'asset tarda o il weld non trova
          -- l'attachment, si riprova invece di perdere l'item.
          for attempt = 1, 3 do
            if gen ~= _acGen then return end
            if _acEquipItem(entry.savedId, cat.AssetTypes[1], entry.savedName, gen) then
              break
            end
            task.wait(0.25 * attempt)
          end
          task.wait(0.05)
        end
      end
    end

    -- Applica subito al personaggio esistente se c'e' un char e toggle ON
    task.spawn(function()
      if not LP.Character then return end
      _acApplyAll(_acGen)
    end)

    -- Applica al respawn
    LP.CharacterAdded:Connect(function()
      _acGen = _acGen + 1          -- invalida gli equip del character precedente
      local gen = _acGen
      task.spawn(function()
        _acApplyAll(gen)
      end)
    end)

    -- ------------------------------------------------------------
    -- WATCHER RE-EQUIP
    -- Gli item dell'Avatar Changer sono locali: quando un altro giocatore
    -- ti colpisce (o il gioco risincronizza il character) il server li
    -- cancella e restavi senza capelli. Qui vengono rimessi subito,
    -- sia per evento (ChildRemoved / HealthChanged) sia con un poll di
    -- sicurezza ogni secondo.
    -- ------------------------------------------------------------
    ;(function()
      local lastTry   = {}
      local fails     = {}
      local charConns = {}
      local pendingCheck = false

      -- Gli eventi (HealthChanged soprattutto) possono arrivare a raffica:
      -- qui vengono compattati in un solo controllo.
      local runCheck
      local function requestCheck(delaySec)
        if pendingCheck then return end
        pendingCheck = true
        task.delay(delaySec or 0.1, function()
          pendingCheck = false
          pcall(runCheck)
        end)
      end

      local function expectedFor(cat, entry)
        local at = cat.AssetTypes[1]
        if at == Enum.AvatarAssetType.Shirt then
          return "ACShirt", "Shirt"
        elseif at == Enum.AvatarAssetType.Pants then
          return "ACPants", "Pants"
        elseif at == Enum.AvatarAssetType.TShirt then
          return "ACTShirt", "ShirtGraphic"
        end
        return "AC"..tostring(entry.savedName or ""), "Accessory"
      end

      local function isPresent(character, cat, entry)
        local nm, cls = expectedFor(cat, entry)
        for _, c in ipairs(character:GetChildren()) do
          if c:IsA(cls) and (c.Name == nm or c.Name == entry.savedName) then
            return true
          end
        end
        return false
      end

      function runCheck()
        local character = LP.Character
        if not character or not character.Parent then return end
        local hum = character:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health <= 0 then return end
        local now = tick()
        for _, cat in ipairs(AC_CATEGORIES) do
          local entry = _G._AmbitiousAvatarChanger[cat.Name]
          if entry and entry.enabled and entry.savedId then
            if isPresent(character, cat, entry) then
              fails[cat.Name] = nil
            else
              -- Backoff: se un asset non si applica (id rotto, attachment
              -- assente) non si riprova all'infinito ogni 0.6s.
              local n = fails[cat.Name] or 0
              local wait = math.min(0.6 * (2 ^ math.min(n, 5)), 20)
              if (now - (lastTry[cat.Name] or 0)) > wait then
                lastTry[cat.Name] = now
                local gen = _acGen
                local _cn = cat.Name
                local _id, _at, _nm = entry.savedId, cat.AssetTypes[1], entry.savedName
                task.spawn(function()
                  if gen ~= _acGen then return end
                  if _acEquipItem(_id, _at, _nm, gen) then
                    fails[_cn] = nil
                  else
                    fails[_cn] = (fails[_cn] or 0) + 1
                  end
                end)
              end
            end
          end
        end
      end
      _G._AmbitiousAvatarChangerRecheck = function() fails = {}; pcall(runCheck) end

      local function hookCharacter(character)
        for _, c in ipairs(charConns) do pcall(function() c:Disconnect() end) end
        charConns = {}
        if not character then return end
        table.insert(charConns, character.ChildRemoved:Connect(function(child)
          if child:IsA("Accessory") or child:IsA("Shirt")
          or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            requestCheck(0.05)
          end
        end))
        local hum = character:FindFirstChildOfClass("Humanoid")
        if hum then
          -- Il caso segnalato: colpito da un altro player -> accessori persi
          table.insert(charConns, hum.HealthChanged:Connect(function()
            requestCheck(0.15)
          end))
        end
      end

      hookCharacter(LP.Character)
      LP.CharacterAdded:Connect(function(c)
        task.delay(0.6, function() hookCharacter(c) end)
      end)

      task.spawn(function()
        while true do
          task.wait(1)
          pcall(runCheck)
        end
      end)
    end)()

    -- ---- Visual callbacks sub-toggle ----
    local _acSubSetVisuals = {}

    -- ---- Unico popup condiviso ----
    local _acPickerGui = nil
    -- Categoria del popup attualmente aperto: serve per il toggle sul riclick
    local _acPickerCat = nil
    -- Il backdrop e' un Frame e non assorbe il click, quindi cliccando un PICK
    -- mentre il popup e' aperto arrivano DUE eventi in quest'ordine:
    --   1) backdrop.InputBegan -> chiude il popup
    --   2) pickBtn.Activated   -> lo trovava gia' chiuso e lo riapriva
    -- Ricordiamo cosa e' stato appena chiuso per ignorare il secondo evento.
    local _acPickerJustClosedCat = nil
    local _acPickerJustClosedAt = 0

    local function _acClosePicker()
      if _acPickerGui and _acPickerGui.Parent then
        _acPickerGui:Destroy()
        _acPickerJustClosedCat = _acPickerCat
        _acPickerJustClosedAt = tick()
      end
      _acPickerGui = nil
      _acPickerCat = nil
    end

    local function _acOpenPicker(catName, assetTypes)
      -- Riclick sullo stesso PICK: chiude, come fanno gli altri picker.
      -- Click su un PICK diverso: passa a quella categoria.
      if _acPickerGui and _acPickerGui.Parent and _acPickerCat == catName then
        _acClosePicker()
        return
      end
      -- Il backdrop ha appena chiuso questo stesso popup: non riaprirlo.
      if _acPickerJustClosedCat == catName and (tick() - _acPickerJustClosedAt) < 0.25 then
        _acPickerJustClosedCat = nil
        return
      end
      _acClosePicker()
      _acPickerJustClosedCat = nil
      _acPickerCat = catName

      _acPickerGui=Instance.new("ScreenGui")
      _acPickerGui.Name="AmbitiousHubAVChanger"
      _acPickerGui.ResetOnSpawn=false
      _acPickerGui.IgnoreGuiInset=true
      _acPickerGui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
      _acPickerGui.DisplayOrder=9998
      _acPickerGui.Parent=HubGui

      -- Frame (non TextButton) come tutti gli altri picker: un TextButton
      -- catturerebbe l'input e i bottoni sotto smetterebbero di ricevere
      -- MouseLeave, restando bloccati nello stato hover.
      local backdrop=Instance.new("Frame")
      backdrop.Name="Backdrop"
      backdrop.Size=UDim2.new(1,0,1,0)
      backdrop.BackgroundColor3=Color3.fromRGB(0,0,0)
      backdrop.BackgroundTransparency=0.45
      backdrop.BorderSizePixel=0
      backdrop.ZIndex=1
      backdrop.Parent=_acPickerGui

      local pickerFrame=Instance.new("Frame")
      pickerFrame.Name="Frame"
      pickerFrame.Size=UDim2.new(0,370,0,510)
      pickerFrame.Position=UDim2.new(0.5,-185,0.5,-255)
      pickerFrame.BackgroundColor3=Color3.fromRGB(8,8,10)
      pickerFrame.BorderSizePixel=0
      pickerFrame.ZIndex=2
      pickerFrame.Parent=_acPickerGui
      corner(pickerFrame,16)
      stroke(pickerFrame,Color3.fromRGB(90,90,105),1.2,0.3)

      -- Title bar
      local titleBar=Instance.new("Frame")
      titleBar.Size=UDim2.new(1,0,0,48)
      titleBar.BackgroundColor3=Color3.fromRGB(12,12,15)
      titleBar.BackgroundTransparency=0.15
      titleBar.BorderSizePixel=0
      titleBar.ZIndex=3
      titleBar.Parent=pickerFrame
      corner(titleBar,16)

      local titleLabel=Instance.new("TextLabel")
      titleLabel.Size=UDim2.new(1,-60,1,0)
      titleLabel.Position=UDim2.new(0,18,0,0)
      titleLabel.BackgroundTransparency=1
      titleLabel.Text=catName.." Changer"
      titleLabel.TextColor3=Color3.fromRGB(255,255,255)
      titleLabel.Font=Enum.Font.GothamBlack
      titleLabel.TextSize=15
      titleLabel.TextXAlignment=Enum.TextXAlignment.Left
      titleLabel.ZIndex=4
      titleLabel.Parent=titleBar

      local closeBtn=Instance.new("TextButton")
      closeBtn.Size=UDim2.new(0,36,0,36)
      closeBtn.Position=UDim2.new(1,-44,0,6)
      closeBtn.BackgroundColor3=Color3.fromRGB(25,25,28)
      closeBtn.BackgroundTransparency=0.1
      closeBtn.BorderSizePixel=0
      closeBtn.Text="X"
      closeBtn.TextColor3=Color3.fromRGB(255,255,255)
      closeBtn.Font=Enum.Font.GothamBlack
      closeBtn.TextSize=14
      closeBtn.AutoButtonColor=false
      closeBtn.ZIndex=4
      closeBtn.Parent=titleBar
      corner(closeBtn,10)
      stroke(closeBtn,Color3.fromRGB(90,90,105),1,0.4)
      closeBtn.MouseEnter:Connect(function() tween(closeBtn,{BackgroundColor3=Color3.fromRGB(180,50,50)},0.12) end)
      closeBtn.MouseLeave:Connect(function() tween(closeBtn,{BackgroundColor3=Color3.fromRGB(25,25,28)},0.12) end)
      closeBtn.Activated:Connect(_acClosePicker)

      -- Search bar
      local searchBar=Instance.new("TextBox")
      searchBar.Size=UDim2.new(1,-24,0,30)
      searchBar.Position=UDim2.new(0,12,0,55)
      searchBar.BackgroundColor3=Color3.fromRGB(18,18,22)
      searchBar.BackgroundTransparency=0.1
      searchBar.BorderSizePixel=0
      searchBar.PlaceholderText="Search..."
      searchBar.PlaceholderColor3=Color3.fromRGB(110,110,120)
      searchBar.Text=""
      searchBar.TextColor3=Color3.fromRGB(245,245,255)
      searchBar.Font=Enum.Font.GothamSemibold
      searchBar.TextSize=12
      searchBar.ClearTextOnFocus=false
      searchBar.ZIndex=4
      searchBar.Parent=pickerFrame
      corner(searchBar,8)
      stroke(searchBar,Color3.fromRGB(70,70,85),1,0.4)

      -- Status label
      local statusLabel=Instance.new("TextLabel")
      statusLabel.Size=UDim2.new(1,-24,0,22)
      statusLabel.Position=UDim2.new(0,12,0,92)
      statusLabel.BackgroundTransparency=1
      statusLabel.Text="Loading..."
      statusLabel.TextColor3=Color3.fromRGB(150,150,160)
      statusLabel.Font=Enum.Font.GothamSemibold
      statusLabel.TextSize=11
      statusLabel.ZIndex=4
      statusLabel.Parent=pickerFrame

      -- Scroll con thumbnails a griglia
      local scrollFrame=Instance.new("ScrollingFrame")
      scrollFrame.Size=UDim2.new(1,-12,1,-100)
      scrollFrame.Position=UDim2.new(0,6,0,96)
      scrollFrame.BackgroundTransparency=1
      scrollFrame.BorderSizePixel=0
      scrollFrame.ScrollBarThickness=4
      scrollFrame.ScrollBarImageColor3=Color3.fromRGB(80,80,90)
      scrollFrame.CanvasSize=UDim2.new(0,0,0,0)
      scrollFrame.AutomaticCanvasSize=Enum.AutomaticSize.Y
      scrollFrame.ZIndex=3
      scrollFrame.Parent=pickerFrame

      local gridLayout=Instance.new("UIGridLayout")
      gridLayout.CellSize=UDim2.new(0,100,0,120)
      gridLayout.CellPadding=UDim2.new(0,8,0,8)
      gridLayout.FillDirection=Enum.FillDirection.Horizontal
      gridLayout.HorizontalAlignment=Enum.HorizontalAlignment.Center
      gridLayout.SortOrder=Enum.SortOrder.LayoutOrder
      gridLayout.Parent=scrollFrame

      local gridPad=Instance.new("UIPadding")
      gridPad.PaddingTop=UDim.new(0,8)
      gridPad.PaddingBottom=UDim.new(0,8)
      gridPad.PaddingLeft=UDim.new(0,6)
      gridPad.PaddingRight=UDim.new(0,6)
      gridPad.Parent=scrollFrame

      local itemOrder=0
      local currentCatalogPage=nil
      local loadingMore=false

      local function makeItemCard(item)
        itemOrder=itemOrder+1
        local card=Instance.new("TextButton")
        card.Name="AC_Item_"..tostring(item.Id)
        card.BackgroundColor3=Color3.fromRGB(16,16,20)
        card.BackgroundTransparency=0.05
        card.BorderSizePixel=0
        card.Text=""
        card.AutoButtonColor=false
        card.LayoutOrder=itemOrder
        card.ZIndex=4
        card.Parent=scrollFrame
        corner(card,10)
        local cardStroke=Instance.new("UIStroke")
        cardStroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
        cardStroke.Color=Color3.fromRGB(50,50,62)
        cardStroke.Thickness=1
        cardStroke.Transparency=0.5
        cardStroke.Parent=card

        -- Thumbnail immagine
        local thumb=Instance.new("ImageLabel")
        thumb.Size=UDim2.new(1,-8,0,72)
        thumb.Position=UDim2.new(0,4,0,4)
        thumb.BackgroundColor3=Color3.fromRGB(22,22,28)
        thumb.BorderSizePixel=0
        thumb.ZIndex=5
        thumb.Image="rbxthumb://type=Asset&id="..tostring(item.Id).."&w=150&h=150"
        thumb.ScaleType=Enum.ScaleType.Fit
        thumb.Parent=card
        corner(thumb,7)

        -- Nome item (sotto thumbnail, troncato)
        local nameLabel=Instance.new("TextLabel")
        nameLabel.Size=UDim2.new(1,-6,0,30)
        nameLabel.Position=UDim2.new(0,3,0,78)
        nameLabel.BackgroundTransparency=1
        nameLabel.Text=item.Name or "?"
        nameLabel.TextColor3=Color3.fromRGB(225,225,235)
        nameLabel.Font=Enum.Font.GothamSemibold
        nameLabel.TextSize=9
        nameLabel.TextWrapped=true
        nameLabel.TextXAlignment=Enum.TextXAlignment.Center
        nameLabel.TextYAlignment=Enum.TextYAlignment.Top
        nameLabel.ZIndex=5
        nameLabel.Parent=card

        card.MouseEnter:Connect(function()
          tween(card,{BackgroundColor3=Color3.fromRGB(30,30,38)},0.1)
          tween(cardStroke,{Color=Color3.fromRGB(200,200,210),Transparency=0.15},0.1)
        end)
        card.MouseLeave:Connect(function()
          -- ripristina colore normale (verde=selezionato gia' equipaggiato)
          local entry=_G._AmbitiousAvatarChanger[catName]
          local isSaved = entry and entry.savedId == item.Id
          tween(card,{BackgroundColor3=isSaved and Color3.fromRGB(20,36,20) or Color3.fromRGB(16,16,20)},0.1)
          tween(cardStroke,{Color=isSaved and Color3.fromRGB(120,220,120) or Color3.fromRGB(50,50,62),Transparency=isSaved and 0.15 or 0.5},0.1)
        end)

        -- Evidenzia se gia' salvato
        local entry=_G._AmbitiousAvatarChanger[catName]
        if entry and entry.savedId == item.Id then
          card.BackgroundColor3=Color3.fromRGB(20,36,20)
          cardStroke.Color=Color3.fromRGB(120,220,120)
          cardStroke.Transparency=0.15
        end

        card.Activated:Connect(function()
          local ent=_G._AmbitiousAvatarChanger[catName]
          if not ent then return end
          -- Se toggle ON e c'era un vecchio item, rimuovilo prima
          if ent.enabled and ent.savedId and ent.savedName ~= "" then
            _acRemoveItem(assetTypes[1], ent.savedName)
          end
          ent.savedId=item.Id
          ent.savedName=item.Name or ""
          if ent.enabled then
            local _id, _at, _nm = item.Id, assetTypes[1], item.Name or ""
            task.spawn(function() _acEquipItem(_id,_at,_nm) end)
          end
          _acSaveConfig()
          -- Aggiorna highlight su tutte le card
          for _,ch in ipairs(scrollFrame:GetChildren()) do
            if ch:IsA("TextButton") then
              local st2=ch:FindFirstChildOfClass("UIStroke")
              local isThis=(ch.Name=="AC_Item_"..tostring(item.Id))
              tween(ch,{BackgroundColor3=isThis and Color3.fromRGB(20,36,20) or Color3.fromRGB(16,16,20)},0.14)
              if st2 then tween(st2,{Color=isThis and Color3.fromRGB(120,220,120) or Color3.fromRGB(50,50,62),Transparency=isThis and 0.15 or 0.5},0.14) end
            end
          end
        end)
      end

      local function loadItems(keyword)
        for _,c in ipairs(scrollFrame:GetChildren()) do if c:IsA("TextButton") then c:Destroy() end end
        itemOrder=0
        currentCatalogPage=nil
        loadingMore=false
        statusLabel.Text="Loading..."
        statusLabel.Visible=true
        task.spawn(function()
          local ok,pages2=pcall(function()
            local params=CatalogSearchParams.new()
            params.AssetTypes=assetTypes
            if keyword and keyword~="" then params.SearchKeyword=keyword end
            return game:GetService("AvatarEditorService"):SearchCatalog(params)
          end)
          if not ok or not pages2 then statusLabel.Text="Error loading."; return end
          currentCatalogPage=pages2
          local firstPage=pages2:GetCurrentPage()
          statusLabel.Visible=#firstPage==0
          statusLabel.Text=#firstPage==0 and "No results." or ""
          for _,item in ipairs(firstPage) do makeItemCard(item) end
        end)
      end

      scrollFrame:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
        if loadingMore or not currentCatalogPage then return end
        local posY=scrollFrame.CanvasPosition.Y
        local canvasH=scrollFrame.CanvasSize.Y.Offset
        local viewH=scrollFrame.AbsoluteSize.Y
        if canvasH>0 and posY+viewH>=canvasH-100 and not currentCatalogPage.IsFinished then
          loadingMore=true
          task.spawn(function()
            local ok2=pcall(function() currentCatalogPage:AdvanceToNextPageAsync() end)
            if ok2 then
              for _,item in ipairs(currentCatalogPage:GetCurrentPage()) do makeItemCard(item) end
            end
            loadingMore=false
          end)
        end
      end)

      local searchDebounce=nil
      searchBar:GetPropertyChangedSignal("Text"):Connect(function()
        if searchDebounce then task.cancel(searchDebounce) end
        searchDebounce=task.delay(0.5,function() loadItems(searchBar.Text) end)
      end)

      backdrop.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
          _acClosePicker()
        end
      end)

      pickerFrame.Size=UDim2.new(0,0,0,0)
      pickerFrame.Position=UDim2.new(0.5,0,0.5,0)
      TweenService:Create(pickerFrame,TweenInfo.new(0.3,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{
        Size=UDim2.new(0,370,0,510),
        Position=UDim2.new(0.5,-185,0.5,-255)
      }):Play()

      loadItems("")
    end

    -- ---- Riga principale "Avatar Changer" con freccia stile Infinite Jump ----
    local acMainRow=baseRow(Utility,"Avatar Changer",11.5)
    acMainRow.LayoutOrder=11.5

    local acArrowBtn=Instance.new("TextButton")
    acArrowBtn.Name="AvatarChangerArrow"
    acArrowBtn.BackgroundColor3=Color3.fromRGB(8,8,12)
    acArrowBtn.BackgroundTransparency=0.18
    acArrowBtn.BorderSizePixel=0
    acArrowBtn.Size=UDim2.new(0,28,0,24)
    acArrowBtn.Position=UDim2.new(1,-38,0.5,-12)
    acArrowBtn.Text="▲"
    acArrowBtn.TextColor3=COLORS.white
    acArrowBtn.TextStrokeColor3=Color3.fromRGB(0,0,0)
    acArrowBtn.TextStrokeTransparency=0.3
    acArrowBtn.TextSize=15
    acArrowBtn.Font=Enum.Font.GothamBold
    acArrowBtn.AutoButtonColor=false
    acArrowBtn.ZIndex=8
    acArrowBtn.Parent=acMainRow
    corner(acArrowBtn,7)
    stroke(acArrowBtn,COLORS.strokeSoft,1,0.45)

    -- ---- SubHolder (auto-size, lista) ----
    local acSubHolder=Instance.new("Frame")
    acSubHolder.Name="AvatarChangerSubHolder"
    acSubHolder.BackgroundTransparency=1
    acSubHolder.BorderSizePixel=0
    acSubHolder.Size=UDim2.new(1,-4,0,0)
    acSubHolder.LayoutOrder=11.6
    acSubHolder.ZIndex=4
    acSubHolder.Visible=false
    acSubHolder.AutomaticSize=Enum.AutomaticSize.Y
    acSubHolder.Parent=Utility

    local acSubLayout=Instance.new("UIListLayout")
    acSubLayout.Padding=UDim.new(0,5)
    acSubLayout.SortOrder=Enum.SortOrder.LayoutOrder
    acSubLayout.HorizontalAlignment=Enum.HorizontalAlignment.Center
    acSubLayout.Parent=acSubHolder

    -- 2px sopra/sotto: gli UIStroke delle righe sono disegnati FUORI dai bounds,
    -- quindi senza questo margine il clipping della tendina taglia il bordo
    -- superiore della prima riga e quello inferiore dell'ultima.
    local acSubPad=Instance.new("UIPadding")
    acSubPad.PaddingTop=UDim.new(0,2)
    acSubPad.PaddingBottom=UDim.new(0,2)
    acSubPad.Parent=acSubHolder

    -- ---- 14 sub-righe ----
    for i,cat in ipairs(AC_CATEGORIES) do
      local catName=cat.Name
      local catAssetTypes=cat.AssetTypes
      local entry=_G._AmbitiousAvatarChanger[catName]

      -- Usa baseRow identico a toggleRow, poi aggiungi manualmente toggle+PICK
      local subRow=Instance.new("Frame")
      subRow.Name="AC_Sub_"..catName
      subRow.BackgroundColor3=COLORS.row
      subRow.BackgroundTransparency=0.3
      subRow.Size=UDim2.new(1,-8,0,34)
      subRow.BorderSizePixel=0
      subRow.LayoutOrder=i
      subRow.ZIndex=4
      subRow.Parent=acSubHolder
      corner(subRow,9)
      local subRowStroke=stroke(subRow,COLORS.strokeSoft,1.15,0.38)
      subRow.MouseEnter:Connect(function() tween(subRow,{BackgroundTransparency=0.22}) end)
      subRow.MouseLeave:Connect(function() tween(subRow,{BackgroundTransparency=0.3}) end)

      -- Label
      local subLabel=Instance.new("TextLabel")
      subLabel.BackgroundTransparency=1
      subLabel.Text=catName
      subLabel.TextColor3=Color3.fromRGB(245,245,255)
      subLabel.TextStrokeColor3=Color3.fromRGB(0,0,0)
      subLabel.TextStrokeTransparency=0.25
      subLabel.TextSize=12
      subLabel.Font=Enum.Font.GothamSemibold
      subLabel.TextXAlignment=Enum.TextXAlignment.Left
      subLabel.Position=UDim2.new(0,12,0,0)
      subLabel.Size=UDim2.new(1,-132,1,0)
      subLabel.ZIndex=5
      subLabel.Parent=subRow

      -- Toggle track (identico a toggleRow)
      local track=Instance.new("Frame")
      track.Name="Track"
      track.BackgroundColor3=COLORS.toggleBg
      track.BackgroundTransparency=0.12
      track.Size=UDim2.new(0,44,0,22)
      track.Position=UDim2.new(1,-52,0.5,-11)
      track.BorderSizePixel=0
      track.ZIndex=5
      track.Parent=subRow
      corner(track,11)
      local trackStroke=stroke(track,COLORS.strokeSoft,1.3,0.4)

      local fill=Instance.new("Frame")
      fill.Name="Fill"
      fill.BackgroundColor3=Color3.fromRGB(140, 140, 150)
      fill.BackgroundTransparency=entry.enabled and 0 or 1
      fill.Size=UDim2.new(1,0,1,0)
      fill.BorderSizePixel=0
      fill.ZIndex=5
      fill.Parent=track
      corner(fill,11)
      local acFillGrad=Instance.new("UIGradient")
      acFillGrad.Color=ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
      })
      acFillGrad.Rotation=18
      acFillGrad.Parent=fill

      local knob=Instance.new("Frame")
      knob.Name="Knob"
      knob.BackgroundColor3=Color3.fromRGB(255,255,255)
      knob.Size=UDim2.new(0,16,0,16)
      knob.Position=entry.enabled and UDim2.new(1,-19,0.5,-8) or UDim2.new(0,3,0.5,-8)
      knob.BorderSizePixel=0
      knob.ZIndex=7
      knob.Parent=track
      corner(knob,999)
      local knobStroke=Instance.new("UIStroke")
      knobStroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
      knobStroke.Color=entry.enabled and Color3.fromRGB(200, 200, 210) or Color3.fromRGB(120, 120, 135)
      knobStroke.Thickness=1.4
      knobStroke.Transparency=0.15
      knobStroke.Parent=knob

      local shine=Instance.new("Frame")
      shine.BackgroundColor3=COLORS.white
      shine.BackgroundTransparency=0.55
      shine.Size=UDim2.new(1,-5,0,5)
      shine.Position=UDim2.new(0,2.5,0,2.5)
      shine.BorderSizePixel=0
      shine.ZIndex=8
      shine.Parent=knob
      corner(shine,5)
      _G._AmbitiousRegAccent(fill, acFillGrad, "toggle", track, knob, subRow)

      -- setVisual identico a toggleRow
      local function subSetVisual(on)
        tween(knob,{Position=on and UDim2.new(1,-19,0.5,-8) or UDim2.new(0,3,0.5,-8)})
        local _onBg, _onEdge = _G._AmbitiousToggleOnColor()
        tween(track,{
          BackgroundTransparency=on and 0 or 0.12,
          BackgroundColor3=on and _onBg or COLORS.toggleBg
        })
        tween(fill,{BackgroundTransparency=on and 0 or 1})
        tween(knobStroke,{
          Color=on and _onEdge or Color3.fromRGB(120, 120, 135)
        })
        tween(trackStroke,{
          Color=on and _onEdge or COLORS.strokeSoft,
          Transparency=on and 0 or 0.4,
          Thickness=1.4
        })
        tween(subRowStroke,{
          Color=on and _onBg or COLORS.strokeSoft,
          Transparency=on and 0.08 or 0.38,
          Thickness=1.25
        })
      end
      _acSubSetVisuals[catName]=subSetVisual
      subSetVisual(entry.enabled)

      -- ToggleButton invisibile sopra la track (esattamente come toggleRow)
      local toggleBtn=Instance.new("TextButton")
      toggleBtn.Name="ToggleButton"
      toggleBtn.BackgroundTransparency=1
      toggleBtn.Text=""
      toggleBtn.Size=UDim2.new(1,0,1,0)
      toggleBtn.Position=UDim2.new(0,0,0,0)
      toggleBtn.AutoButtonColor=false
      toggleBtn.ZIndex=7
      toggleBtn.Parent=subRow

      do
        local _cn=catName
        local _cat=catAssetTypes
        toggleBtn.Activated:Connect(function()
          local ent=_G._AmbitiousAvatarChanger[_cn]
          if not ent then return end
          ent.enabled=not ent.enabled
          subSetVisual(ent.enabled)
          if ent.enabled and ent.savedId then
            local _id, _at, _nm = ent.savedId, _cat[1], ent.savedName
            task.spawn(function() _acEquipItem(_id,_at,_nm) end)
          else
            -- Toggle OFF: rimuovi item dal personaggio
            if ent.savedId then
              _acRemoveItem(_cat[1],ent.savedName)
            end
          end
          _acSaveConfig()
        end)
      end

      -- PICK button stile Tracker Color (holder scuro + testo bianco)
      local pickHolder=Instance.new("Frame")
      pickHolder.Name="PickHolder"
      pickHolder.BackgroundColor3=Color3.fromRGB(140, 140, 150)
      pickHolder.BackgroundTransparency=0.28
      pickHolder.BorderSizePixel=0
      pickHolder.Size=UDim2.new(0,48,0,26)
      pickHolder.Position=UDim2.new(1,-118,0.5,-13)
      pickHolder.ClipsDescendants=true
      pickHolder.ZIndex=8
      pickHolder.Parent=subRow
      corner(pickHolder,13)
      stroke(pickHolder,Color3.fromRGB(200, 200, 210),1.5,0.15)

      local pickGradAc = Instance.new("UIGradient")
      pickGradAc.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
      })
      pickGradAc.Rotation = 18
      pickGradAc.Parent = pickHolder
      _G._AmbitiousRegAccent(pickHolder, pickGradAc, "pick")

      local pickBtn=Instance.new("TextButton")
      pickBtn.Name="PickBtn"
      pickBtn.BackgroundTransparency=1
      pickBtn.Text="PICK"
      pickBtn.TextColor3=COLORS.white
      pickBtn.TextStrokeColor3=Color3.fromRGB(0,0,0)
      pickBtn.TextStrokeTransparency=0.3
      pickBtn.TextSize=11
      pickBtn.Font=Enum.Font.GothamBlack
      pickBtn.TextXAlignment=Enum.TextXAlignment.Center
      pickBtn.Size=UDim2.new(1,0,1,0)
      pickBtn.Position=UDim2.new(0,0,0,0)
      pickBtn.BorderSizePixel=0
      pickBtn.ZIndex=9
      pickBtn.AutoButtonColor=false
      pickBtn.Parent=pickHolder

      pickBtn.MouseEnter:Connect(function()
        tween(pickHolder, {Size = UDim2.new(0, 54, 0, 28), Position = UDim2.new(1, -121, 0.5, -14)}, 0.12)
      end)
      pickBtn.MouseLeave:Connect(function()
        tween(pickHolder, {Size = UDim2.new(0, 48, 0, 26), Position = UDim2.new(1, -118, 0.5, -13)}, 0.12)
      end)

      do
        local _cn2=catName
        local _cat2=catAssetTypes
        pickBtn.Activated:Connect(function()
          _acOpenPicker(_cn2,_cat2)
        end)
      end
    end

    -- ---- Toggle espansione freccia ----
    local acExpanded=false
    local function acSetExpanded(on)
      acExpanded=on
      -- Animazione a tendina + freccia che ruota, come Infinite Jump / Anti Ragdoll.
      -- Usa la variante Auto perche' il sub holder ha AutomaticSize.Y (14 sub-righe).
      _G._AmbitiousExpandAuto(acSubHolder, on, acSubLayout, acArrowBtn)
      _G._AmbitiousClampCanvas(Utility)
    end
    acArrowBtn.Activated:Connect(function() acSetExpanded(not acExpanded) end)

    -- ---- Hook Reset All Settings ----
    _G._AmbitiousAvatarChangerReset=function()
      for _,cat in ipairs(AC_CATEGORIES) do
        local entry=_G._AmbitiousAvatarChanger[cat.Name]
        if entry then
          -- Rimuovi subito dal personaggio se era attivo
          if entry.enabled and entry.savedId then
            _acRemoveItem(cat.AssetTypes[1], entry.savedName)
          end
          entry.enabled=false; entry.savedId=nil; entry.savedName=""
          if _acSubSetVisuals[cat.Name] then _acSubSetVisuals[cat.Name](false) end
        end
      end
      _acSaveConfig()
    end
  end -- fine Avatar Changer

  do
    local rowH, setVisualH = toggleRow(Utility, "Enable Headless", headlessEnabled, 12)
    _SV.setHeadlessVisual = setVisualH
    local _headlessBtn = rowH and rowH:FindFirstChild("ToggleButton")
    if _headlessBtn then
      _headlessBtn.Activated:Connect(function()
        if headlessEnabled then disableHeadless() else enableHeadless() end
        if setVisualH then setVisualH(headlessEnabled) end
        saveAmbitiousConfig()
      end)
    end
  end
  do
    local rowK, setVisualK = toggleRow(Utility, "Enable Korblox", korbloxEnabled, 12)
    _SV.setKorbloxVisual = setVisualK
    local _korbloxBtn = rowK and rowK:FindFirstChild("ToggleButton")
    if _korbloxBtn then
      _korbloxBtn.Activated:Connect(function()
        if korbloxEnabled then disableKorblox() else enableKorblox() end
        if setVisualK then setVisualK(korbloxEnabled) end
        saveAmbitiousConfig()
      end)
    end
  end

  -- ===== TOOLS (RAINBOW, TRANSPARENT, CUSTOM) =====
  section(Utility, "TOOLS", 12)

  -- >>> CUSTOM TOOLS + SELETTORE SKIN BEGIN
  -- Riga sopra Rainbow Tools, con freccetta stile Infinite Jump. Aprendola
  -- compare "Custom Tools Selector" col bottone PICK, che apre il popup di
  -- scelta skin: due sezioni (Bat / Medusa) con slide fluida e anteprime 3D
  -- dell'oggetto che ruota.
  do
    local rowCT, setVisualCT = toggleRow(Utility, "Custom Tools", _G.AmbitiousCustomToolsEnabled == true, 12)
    _SV.setCustomToolsVisual = setVisualCT
    local btn = rowCT and rowCT:FindFirstChild("ToggleButton")
    if btn then
      btn.Activated:Connect(function()
        local on = not (_G.AmbitiousCustomToolsEnabled == true)
        if _G.AmbitiousCustomTools then _G.AmbitiousCustomTools.setEnabled(on) end
        if setVisualCT then setVisualCT(on) end
        saveAmbitiousConfig()
      end)
    end

    -- ---------- riga a tendina col PICK ----------
    local ctSelRow = baseRow(Utility, "Custom Tools Selector", 12)
    ctSelRow.Size = UDim2.new(1, -4, 0, 42)
    ctSelRow.ClipsDescendants = true
    ctSelRow.Visible = false

    do
      local ctExpanded = false
      local ctArrow = Instance.new("TextButton")
      ctArrow.Name = "CustomToolsArrow"
      ctArrow.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
      ctArrow.BackgroundTransparency = 0.18
      ctArrow.BorderSizePixel = 0
      ctArrow.Size = UDim2.new(0, 28, 0, 24)
      ctArrow.Position = UDim2.new(1, -90, 0.5, -12)
      ctArrow.Text = "\u{25B2}"
      ctArrow.TextColor3 = COLORS.white
      ctArrow.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
      ctArrow.TextStrokeTransparency = 0.3
      ctArrow.TextSize = 15
      ctArrow.Font = Enum.Font.GothamBold
      ctArrow.AutoButtonColor = false
      ctArrow.ZIndex = 8
      ctArrow.Parent = rowCT
      corner(ctArrow, 7)
      stroke(ctArrow, COLORS.strokeSoft, 1, 0.45)
      ctArrow.Activated:Connect(function()
        ctExpanded = not ctExpanded
        _G._AmbitiousExpand(ctSelRow, ctExpanded, 42, ctArrow)
      end)
    end

    local ctBtnHolder = Instance.new("Frame")
    ctBtnHolder.Name = "CustomToolsPickHolder"
    ctBtnHolder.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
    ctBtnHolder.BackgroundTransparency = 0.28
    ctBtnHolder.BorderSizePixel = 0
    ctBtnHolder.Size = UDim2.new(0, 66, 0, 30)
    ctBtnHolder.Position = UDim2.new(1, -73, 0.5, -15)
    ctBtnHolder.ClipsDescendants = true
    ctBtnHolder.ZIndex = 9
    ctBtnHolder.Parent = ctSelRow
    corner(ctBtnHolder, 15)
    stroke(ctBtnHolder, Color3.fromRGB(200, 200, 210), 1.5, 0.15)

    local ctGrad = Instance.new("UIGradient")
    ctGrad.Color = ColorSequence.new({
      ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
      ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
      ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
    })
    ctGrad.Rotation = 18
    ctGrad.Parent = ctBtnHolder
    _G._AmbitiousRegAccent(ctBtnHolder, ctGrad, "pick")

    local ctPickBtn = Instance.new("TextButton")
    ctPickBtn.Name = "CustomToolsPick"
    ctPickBtn.BackgroundTransparency = 1
    ctPickBtn.Text = "PICK"
    ctPickBtn.TextColor3 = COLORS.white
    ctPickBtn.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    ctPickBtn.TextStrokeTransparency = 0.3
    ctPickBtn.TextSize = 12
    ctPickBtn.Font = Enum.Font.GothamBlack
    ctPickBtn.Size = UDim2.new(1, 0, 1, 0)
    ctPickBtn.BorderSizePixel = 0
    ctPickBtn.ZIndex = 10
    ctPickBtn.AutoButtonColor = false
    ctPickBtn.Parent = ctBtnHolder

    ctPickBtn.MouseEnter:Connect(function()
      tween(ctBtnHolder, {Size = UDim2.new(0, 72, 0, 32), Position = UDim2.new(1, -76, 0.5, -16)}, 0.12)
    end)
    ctPickBtn.MouseLeave:Connect(function()
      tween(ctBtnHolder, {Size = UDim2.new(0, 66, 0, 30), Position = UDim2.new(1, -73, 0.5, -15)}, 0.12)
    end)

    -- ================== POPUP SCELTA SKIN ==================
    loadstring(game:HttpGet("https://pastebin.com/raw/2H5JyQKE"))()
    local ctGui = nil

    local function closeCTPicker()
      if ctGui and ctGui.Parent then
        local fr = ctGui:FindFirstChild("Frame")
        if fr then TweenService:Create(fr, TweenInfo.new(0.2), {BackgroundTransparency = 1}):Play() end
        task.delay(0.25, function()
          if ctGui and ctGui.Parent then ctGui:Destroy() end
          ctGui = nil
        end)
      end
    end

    ctPickBtn.Activated:Connect(function()
      if ctGui and ctGui.Parent then closeCTPicker() return end

      ctGui = Instance.new("ScreenGui")
      ctGui.Name = "AmbitiousCustomToolsPicker"
      ctGui.ResetOnSpawn = false
      ctGui.IgnoreGuiInset = true
      ctGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
      ctGui.DisplayOrder = 9999
      ctGui.Parent = HubGui

      local backdrop = Instance.new("Frame")
      backdrop.Name = "Backdrop"
      backdrop.Size = UDim2.new(1, 0, 1, 0)
      backdrop.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
      backdrop.BackgroundTransparency = 0.5
      backdrop.BorderSizePixel = 0
      backdrop.ZIndex = 1
      backdrop.Parent = ctGui

      local frame = Instance.new("Frame")
      frame.Name = "Frame"
      frame.Size = UDim2.new(0, 420, 0, 470)
      frame.Position = UDim2.new(0.5, -210, 0.5, -235)
      frame.BackgroundColor3 = Color3.fromRGB(10, 10, 12)
      frame.BorderSizePixel = 0
      frame.ZIndex = 2
      frame.Parent = ctGui
      corner(frame, 16)
      stroke(frame, Color3.fromRGB(90, 90, 105), 1.2, 0.3)

      local titleBar = Instance.new("Frame")
      titleBar.Size = UDim2.new(1, 0, 0, 44)
      titleBar.BackgroundColor3 = Color3.fromRGB(14, 14, 17)
      titleBar.BackgroundTransparency = 0.1
      titleBar.BorderSizePixel = 0
      titleBar.ZIndex = 3
      titleBar.Parent = frame
      corner(titleBar, 16)

      local titleLabel = Instance.new("TextLabel")
      titleLabel.Size = UDim2.new(1, -60, 1, 0)
      titleLabel.Position = UDim2.new(0, 16, 0, 0)
      titleLabel.BackgroundTransparency = 1
      titleLabel.Text = "CUSTOM TOOLS SELECTOR"
      titleLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
      titleLabel.Font = Enum.Font.GothamBlack
      titleLabel.TextSize = 15
      titleLabel.TextXAlignment = Enum.TextXAlignment.Left
      titleLabel.ZIndex = 4
      titleLabel.Parent = titleBar

      local closeBtn = Instance.new("TextButton")
      closeBtn.Size = UDim2.new(0, 32, 0, 32)
      closeBtn.Position = UDim2.new(1, -40, 0, 6)
      closeBtn.BackgroundColor3 = Color3.fromRGB(25, 25, 28)
      closeBtn.BorderSizePixel = 0
      closeBtn.Text = "X"
      closeBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
      closeBtn.Font = Enum.Font.GothamBlack
      closeBtn.TextSize = 13
      closeBtn.AutoButtonColor = false
      closeBtn.ZIndex = 4
      closeBtn.Parent = titleBar
      corner(closeBtn, 8)
      stroke(closeBtn, Color3.fromRGB(90, 90, 105), 1, 0.4)
      closeBtn.MouseEnter:Connect(function()
        tween(closeBtn, {BackgroundColor3 = Color3.fromRGB(180, 50, 50)}, 0.12)
      end)
      closeBtn.MouseLeave:Connect(function()
        tween(closeBtn, {BackgroundColor3 = Color3.fromRGB(25, 25, 28)}, 0.12)
      end)
      closeBtn.Activated:Connect(closeCTPicker)

      -- ---------- due sezioni: Bat | Medusa ----------
      -- Selettore sezioni: barra piena, niente cornice e niente riquadro
      -- interno. La meta' attiva viene riempita del tutto dal gradiente,
      -- bordo a bordo, cosi' non somiglia agli slider del pannello.
      local tabsHolder = Instance.new("Frame")
      tabsHolder.Name = "Sections"
      tabsHolder.BackgroundColor3 = Color3.fromRGB(18, 18, 23)
      tabsHolder.BackgroundTransparency = 0.25
      tabsHolder.Size = UDim2.new(1, -24, 0, 38)
      tabsHolder.Position = UDim2.new(0, 12, 0, 58)
      tabsHolder.BorderSizePixel = 0
      tabsHolder.ZIndex = 3
      tabsHolder.ClipsDescendants = true
      tabsHolder.Parent = frame
      corner(tabsHolder, 10)

      -- Colore fuori dalla palette della hub: la meta' attiva e' chiara con
      -- testo scuro, cosi' il selettore si distingue e non sembra l'ennesimo
      -- slider viola.
      local slide = Instance.new("Frame")
      slide.Name = "Slide"
      slide.BackgroundColor3 = Color3.fromRGB(236, 238, 245)
      slide.BackgroundTransparency = 0
      slide.AnchorPoint = Vector2.new(0.5, 0.5)
      slide.Size = UDim2.new(0.5, 0, 1, 0)   -- riempie l'intera meta'
      slide.Position = UDim2.new(0.25, 0, 0.5, 0)
      slide.BorderSizePixel = 0
      slide.ZIndex = 4
      slide.Parent = tabsHolder
      corner(slide, 10)
      local slideGrad = Instance.new("UIGradient")
      slideGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(206, 210, 224)),
      })
      slideGrad.Rotation = 90
      slideGrad.Parent = slide

      local CATS = { {key = "Bat", text = "BAT"}, {key = "Medusa", text = "MEDUSA"} }
      local catLabels = {}
      for i, c in ipairs(CATS) do
        local lbl = Instance.new("TextLabel")
        lbl.BackgroundTransparency = 1
        lbl.Text = c.text
        lbl.TextColor3 = COLORS.white
        lbl.TextStrokeTransparency = 1
        lbl.TextSize = 12
        lbl.Font = Enum.Font.GothamBlack
        lbl.AnchorPoint = Vector2.new(0.5, 0.5)
        lbl.Size = UDim2.new(0.5, 0, 1, 0)
        lbl.Position = UDim2.new(0.25 + 0.5 * (i - 1), 0, 0.5, 0)
        lbl.ZIndex = 6
        lbl.Parent = tabsHolder
        catLabels[i] = lbl
      end

      -- ---------- area anteprime ----------
      local page = Instance.new("Frame")
      page.Name = "Page"
      page.BackgroundTransparency = 1
      page.Size = UDim2.new(1, -24, 1, -118)
      page.Position = UDim2.new(0, 12, 0, 106)
      page.ClipsDescendants = true
      page.ZIndex = 3
      page.Parent = frame

      local cards = {}      -- [i] = {card, cat, key}
      local spinConn = nil

      local function buildCard(def, key, idx)
        local card = Instance.new("Frame")
        card.Name = "Skin_" .. key
        card.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
        card.BackgroundTransparency = 0.15
        card.Size = UDim2.new(0, 148, 0, 172)
        card.BorderSizePixel = 0
        card.ZIndex = 4
        card.Visible = false
        card.Parent = page
        corner(card, 14)
        local cStroke = stroke(card, COLORS.strokeSoft, 1.3, 0.5)

        -- Anteprima 3D: ViewportFrame con la mesh vera che ruota
        local vp = Instance.new("ViewportFrame")
        vp.Name = "Preview"
        vp.BackgroundColor3 = Color3.fromRGB(8, 8, 11)
        vp.BackgroundTransparency = 0.25
        vp.Size = UDim2.new(1, -16, 0, 116)
        vp.Position = UDim2.new(0, 8, 0, 8)
        vp.BorderSizePixel = 0
        vp.ZIndex = 5
        vp.Ambient = Color3.fromRGB(190, 190, 200)
        vp.LightColor = Color3.fromRGB(255, 255, 255)
        vp.LightDirection = Vector3.new(-0.4, -1, -0.6)
        vp.Parent = card
        corner(vp, 12)

        local part = Instance.new("Part")
        part.Name = "Preview"
        part.Anchored = true
        part.CanCollide = false
        part.Size = Vector3.new(1, 1, 1)
        part.CFrame = CFrame.new(0, 0, 0)
        part.Parent = vp

        local mesh = Instance.new("SpecialMesh")
        mesh.MeshType = Enum.MeshType.FileMesh
        mesh.MeshId = def.mesh
        mesh.TextureId = def.tex
        mesh.Scale = def.scale
        mesh.Parent = part

        local cam = Instance.new("Camera")
        cam.FieldOfView = 45
        cam.Parent = vp
        vp.CurrentCamera = cam

        local nameLbl = Instance.new("TextLabel")
        nameLbl.BackgroundTransparency = 1
        nameLbl.Text = def.label
        nameLbl.TextColor3 = COLORS.white
        nameLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        nameLbl.TextStrokeTransparency = 0.35
        nameLbl.TextSize = 12
        nameLbl.Font = Enum.Font.GothamBlack
        nameLbl.TextWrapped = true
        nameLbl.Size = UDim2.new(1, -12, 0, 36)
        nameLbl.Position = UDim2.new(0, 6, 0, 130)
        nameLbl.ZIndex = 6
        nameLbl.Parent = card

        local click = Instance.new("TextButton")
        click.BackgroundTransparency = 1
        click.Text = ""
        click.AutoButtonColor = false
        click.Size = UDim2.new(1, 0, 1, 0)
        click.ZIndex = 8
        click.Parent = card

        local entry = { card = card, cat = def.cat, key = key,
                        part = part, stroke = cStroke, idx = idx,
                        vp = vp, cam = cam, def = def }

        -- Distanza fissa per skin, com'era prima: def.view.
        local dist = def.view or 4
        cam.CFrame = CFrame.new(Vector3.new(0, dist * 0.35, dist), Vector3.new(0, 0, 0))


        local function refreshSel()
          local sel = (_G.AmbitiousCustomToolSkins[def.cat] == key)
          tween(cStroke, {
            -- lo stesso bianco del resto della GUI, non il viola
            Color = sel and COLORS.white or COLORS.strokeSoft,
            Transparency = sel and 0 or 0.5,
            Thickness = sel and 2.2 or 1.3,
          }, 0.14)
          tween(card, {BackgroundTransparency = sel and 0 or 0.15}, 0.14)
        end
        entry.refresh = refreshSel

        -- Hover: la card cresce di 4px in TUTTE le direzioni, cioe' 2 per
        -- lato, spostando anche la posizione di -2/-2. Prima cresceva solo
        -- verso destra e verso il basso, e di 6px: si vedeva lo scarto.
        click.MouseEnter:Connect(function()
          local w = entry.baseW or card.Size.X.Offset
          local x = entry.baseX or card.Position.X.Offset
          tween(card, {
            Size = UDim2.new(0, w + 4, 0, 176),
            Position = UDim2.new(0, x - 2, 0, 8),
          }, 0.12)
        end)
        click.MouseLeave:Connect(function()
          local w = entry.baseW or card.Size.X.Offset
          local x = entry.baseX or card.Position.X.Offset
          tween(card, {
            Size = UDim2.new(0, w, 0, 172),
            Position = UDim2.new(0, x, 0, 10),
          }, 0.12)
        end)
        click.MouseButton1Click:Connect(function()
          if _G.AmbitiousSetCustomToolSkin then
            _G.AmbitiousSetCustomToolSkin(def.cat, key)
          end
          for _, e in ipairs(cards) do e.refresh() end
        end)

        refreshSel()
        return entry
      end

      for key, def in pairs(_G.AmbitiousCustomToolAssets or {}) do
        cards[#cards + 1] = buildCard(def, key, #cards + 1)
      end

      -- Rotazione continua delle anteprime
      spinConn = RunService.RenderStepped:Connect(function(dt)
        for _, e in ipairs(cards) do
          if e.card.Visible and e.part.Parent then
            e.part.CFrame = e.part.CFrame * CFrame.Angles(0, dt * 1.2, 0)
          end
        end
      end)
      ctGui.AncestryChanged:Connect(function(_, parent)
        if not parent and spinConn then
          pcall(function() spinConn:Disconnect() end)
          spinConn = nil
        end
      end)

      -- ---------- cambio sezione con scorrimento ----------
      local current = "Bat"

      -- La larghezza si prende dalla misura NOTA del popup, non da
      -- AbsoluteSize: quando il layout gira il riquadro sta ancora crescendo
      -- dall'animazione di apertura e AbsoluteSize e' praticamente zero.
      -- Era per quello che le card finivano incollate a sinistra col bordo
      -- tagliato e lo spazio a destra vuoto.
      local PAGE_W = 420 - 24
      local GAP = 14
      -- Margine interno. Lo UIStroke e' disegnato FUORI dal bordo della card
      -- e la pagina ha ClipsDescendants: se le card arrivavano a filo, la
      -- cornice della prima e dell'ultima veniva tagliata. In piu' l'hover
      -- allarga la card di 6px, che devono avere dove andare.
      local INSET = 9
      -- Le card si dividono tutta la larghezza disponibile: con due riempiono
      -- la riga, con una sola occupa tutto. Quando aggiungeremo altre skin
      -- basta cambiare questa formula (o passare a una griglia su piu' righe).
      local function layoutCat(cat, fromRight, animate)
        local list = {}
        for _, e in ipairs(cards) do
          if e.cat == cat then list[#list + 1] = e end
        end
        local n = #list
        if n == 0 then return list end
        local cardW = math.floor((PAGE_W - INSET * 2 - GAP * (n - 1)) / n)
        for i, e in ipairs(list) do
          local targetX = INSET + (i - 1) * (cardW + GAP)
          e.card.Size = UDim2.new(0, cardW, 0, 172)
          e.baseW = cardW
          e.baseX = targetX
          e.card.Visible = true
          if animate then
            e.card.Position = UDim2.new(0, targetX + (fromRight and 300 or -300), 0, 10)
            tween(e.card, {Position = UDim2.new(0, targetX, 0, 10)}, 0.24)
          else
            e.card.Position = UDim2.new(0, targetX, 0, 10)
          end
        end
        return list
      end

      local switchToken = 0
      local function setCat(cat, animate)
        if cat == current and animate then return end
        local goingRight = (cat == "Medusa")
        switchToken = switchToken + 1
        local myToken = switchToken

        local outList = {}
        for _, e in ipairs(cards) do
          if e.cat ~= cat and e.card.Visible then outList[#outList + 1] = e end
        end

        current = cat

        if animate then
          -- Le card che escono vengono nascoste NON appena sono fuori dal
          -- riquadro, non a fine animazione: prima restavano visibili per
          -- tutta la durata dello scorrimento e si vedeva la Katana ferma
          -- mentre gia' entrava la sezione Medusa.
          for _, e in ipairs(outList) do
            local x = e.card.Position.X.Offset
            tween(e.card, {Position = UDim2.new(0, x + (goingRight and -300 or 300), 0, 10)}, 0.18)
          end
          task.delay(0.14, function()
            if myToken ~= switchToken then return end
            for _, e in ipairs(outList) do
              if e.card.Parent then e.card.Visible = false end
            end
          end)
        else
          for _, e in ipairs(outList) do e.card.Visible = false end
        end

        layoutCat(cat, goingRight, animate)
        -- slide + etichette
        local idx = (cat == "Bat") and 1 or 2
        tween(slide, {Position = UDim2.new(0.25 + 0.5 * (idx - 1), 0, 0.5, 0)}, 0.2)
        for i, lbl in ipairs(catLabels) do
          -- sulla meta' chiara il testo va scuro, sull'altra resta chiaro
          tween(lbl, {
            TextColor3 = (i == idx) and Color3.fromRGB(22, 22, 28) or Color3.fromRGB(225, 225, 235),
            TextTransparency = (i == idx) and 0 or 0.35,
          }, 0.16)
        end
      end

      for i, c in ipairs(CATS) do
        local clickTab = Instance.new("TextButton")
        clickTab.BackgroundTransparency = 1
        clickTab.Text = ""
        clickTab.AutoButtonColor = false
        clickTab.AnchorPoint = Vector2.new(0.5, 0.5)
        clickTab.Size = UDim2.new(0.5, 0, 1, 0)
        clickTab.Position = UDim2.new(0.25 + 0.5 * (i - 1), 0, 0.5, 0)
        clickTab.ZIndex = 8
        clickTab.Parent = tabsHolder
        local key = c.key
        clickTab.MouseButton1Click:Connect(function() setCat(key, true) end)
      end

      backdrop.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
           or input.UserInputType == Enum.UserInputType.Touch then
          closeCTPicker()
        end
      end)

      -- stato iniziale, senza animazione
      task.defer(function()
        for _, e in ipairs(cards) do e.card.Visible = false end
        setCat("Bat", false)
      end)

      frame.Size = UDim2.new(0, 0, 0, 0)
      frame.Position = UDim2.new(0.5, 0, 0.5, 0)
      TweenService:Create(frame, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Size = UDim2.new(0, 420, 0, 470),
        Position = UDim2.new(0.5, -210, 0.5, -235)
      }):Play()
    end)
  end
  -- <<< CUSTOM TOOLS + SELETTORE SKIN END

  do
    local rowRT, setVisualRT = toggleRow(Utility, "Rainbow Tools", _G.AmbitiousRainbowToolsEnabled == true, 12)
    _SV.setRainbowToolsVisual = setVisualRT
    local btn = rowRT and rowRT:FindFirstChild("ToggleButton")
    if btn then
      btn.Activated:Connect(function()
        local on = not (_G.AmbitiousRainbowToolsEnabled == true)
        if _G.AmbitiousRainbowTools then _G.AmbitiousRainbowTools.setEnabled(on) end
        if setVisualRT then setVisualRT(on) end
        saveAmbitiousConfig()
      end)
    end
  end

  do
    local rowTT, setVisualTT = toggleRow(Utility, "Transparent Tools", _G.AmbitiousTransparentToolsEnabled == true, 12)
    _SV.setTransparentToolsVisual = setVisualTT
    local btn = rowTT and rowTT:FindFirstChild("ToggleButton")
    if btn then
      btn.Activated:Connect(function()
        local on = not (_G.AmbitiousTransparentToolsEnabled == true)
        if _G.AmbitiousTransparentTools then _G.AmbitiousTransparentTools.setEnabled(on) end
        if setVisualTT then setVisualTT(on) end
        saveAmbitiousConfig()
      end)
    end
  end

  do
    local rowCS, setVisualCS = toggleRow(Utility, "Custom Sounds", _G.AmbitiousCustomSoundsEnabled == true, 12)
    _SV.setCustomSoundsVisual = setVisualCS
    local btn = rowCS and rowCS:FindFirstChild("ToggleButton")
    if btn then
      btn.Activated:Connect(function()
        local on = not (_G.AmbitiousCustomSoundsEnabled == true)
        if _G.AmbitiousCustomSounds then _G.AmbitiousCustomSounds.setEnabled(on) end
        if setVisualCS then setVisualCS(on) end
        saveAmbitiousConfig()
      end)
    end
  end

-- ===== CAMERA (STRETCH REZ, FOV, FOV VALUE, NO CAM COLLISION) =====
section(Utility, "CAMERA", 13)

-- >>> STRETCH REZ: toggle + tendina BEGIN
-- Il toggle decide se lo stretch e' attivo: spento significa X1, acceso
-- applica il valore scelto nella tendina. La freccetta (stile Infinite Jump)
-- apre lo slider con SOLO i tre valori veri: X1.5, X2, X3 — X1 non e' piu'
-- un'opzione della lista, e' semplicemente "toggle spento".
do
    local STRETCH_PICKS = { {idx = 2, name = "X1.5"}, {idx = 3, name = "X2"}, {idx = 4, name = "X3"} }
    local SEG_N = #STRETCH_PICKS

    -- Valore scelto quando il toggle e' acceso (indice dentro stretchPresetOrder)
    _G.AmbitiousStretchPick = _G.AmbitiousStretchPick
        or ((stretchCurrentIndex and stretchCurrentIndex > 1) and stretchCurrentIndex or 2)

    local row, setStretchVisual = toggleRow(Utility, "Stretch Rez", stretchEnabled == true, 14)

    -- ---------- tendina con i tre valori ----------
    local segHolder = Instance.new("Frame")
    segHolder.Name = "Stretch Rez Options"
    segHolder.BackgroundColor3 = COLORS.row
    segHolder.BackgroundTransparency = 0.28
    segHolder.Size = UDim2.new(1, -4, 0, 42)
    segHolder.BorderSizePixel = 0
    segHolder.LayoutOrder = 14
    segHolder.ZIndex = 4
    segHolder.ClipsDescendants = true
    segHolder.Visible = false
    segHolder.Parent = Utility
    corner(segHolder, 14)
    stroke(segHolder, Color3.fromRGB(110, 110, 120), 1.4, 0.32)
    _G._AmbitiousRegAccent(segHolder, nil, "soft")

    local segSlide = Instance.new("Frame")
    segSlide.Name = "SelectedSlide"
    segSlide.BackgroundColor3 = Color3.fromRGB(140, 140, 150)
    segSlide.BackgroundTransparency = 0.1
    segSlide.AnchorPoint = Vector2.new(0.5, 0.5)
    segSlide.Size = UDim2.new(1 / SEG_N, -4, 1, -8)
    segSlide.Position = UDim2.new(0.5 / SEG_N, 0, 0.5, 0)
    segSlide.BorderSizePixel = 0
    segSlide.ZIndex = 5
    segSlide.Parent = segHolder
    corner(segSlide, 13)
    local segSlideStroke = Instance.new("UIStroke")
    segSlideStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    segSlideStroke.Color = Color3.fromRGB(200, 200, 210)
    segSlideStroke.Thickness = 1.5
    segSlideStroke.Transparency = 0.1
    segSlideStroke.Parent = segSlide
    local segSlideGrad = Instance.new("UIGradient")
    segSlideGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(210, 210, 218)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(140, 140, 150)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(40, 40, 48)),
    })
    segSlideGrad.Rotation = 22
    segSlideGrad.Parent = segSlide
    _G._AmbitiousRegAccent(segSlide, segSlideGrad, "slide")

    local segLabels = {}
    local segW = 1 / SEG_N
    for i, p in ipairs(STRETCH_PICKS) do
        local lbl = Instance.new("TextLabel")
        lbl.BackgroundTransparency = 1
        lbl.Text = p.name
        lbl.TextColor3 = COLORS.white
        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        lbl.TextStrokeTransparency = 0.2
        lbl.TextSize = 11
        lbl.Font = Enum.Font.GothamBlack
        lbl.AnchorPoint = Vector2.new(0.5, 0.5)
        lbl.Size = UDim2.new(segW, 0, 1, 0)
        lbl.Position = UDim2.new(segW * (i - 0.5), 0, 0.5, 0)
        lbl.ZIndex = 8
        lbl.Parent = segHolder
        segLabels[i] = lbl

        local clk = Instance.new("TextButton")
        clk.BackgroundTransparency = 1
        clk.Text = ""
        clk.AutoButtonColor = false
        clk.AnchorPoint = Vector2.new(0.5, 0.5)
        clk.Size = UDim2.new(segW, 0, 1, 0)
        clk.Position = UDim2.new(segW * (i - 0.5), 0, 0.5, 0)
        clk.ZIndex = 10
        clk.Parent = segHolder
        local picked = p.idx
        clk.MouseButton1Click:Connect(function()
            _G.AmbitiousStretchPick = picked
            -- Se il toggle e' acceso il nuovo valore parte subito;
            -- se e' spento resta memorizzato per la prossima accensione.
            if stretchEnabled then applyStretchPreset(picked) end
            if _G.AmbitiousRefreshStretchSelector then _G.AmbitiousRefreshStretchSelector() end
            saveAmbitiousConfig()
        end)
    end

    local function refreshStretchSelector()
        -- Quale segmento evidenziare: quello scelto, non stretchCurrentIndex,
        -- che a toggle spento vale 1 e non corrisponde a nessun segmento.
        local pick = _G.AmbitiousStretchPick or 2
        local segIdx = 1
        for i, p in ipairs(STRETCH_PICKS) do
            if p.idx == pick then segIdx = i break end
        end
        tween(segSlide, {
            Position = UDim2.new(segW * (segIdx - 0.5), 0, 0.5, 0),
            Size = UDim2.new(segW, -4, 1, -8),
        }, 0.18)
        for i, lbl in ipairs(segLabels) do
            tween(lbl, {
                TextTransparency = (i == segIdx) and 0 or 0.45,
                TextStrokeTransparency = (i == segIdx) and 0.2 or 0.45,
            }, 0.14)
        end
        if setStretchVisual then pcall(setStretchVisual, stretchEnabled == true) end
    end
    _G.AmbitiousRefreshStretchSelector = refreshStretchSelector

    local sBtn = row and row:FindFirstChild("ToggleButton")
    if sBtn then
        sBtn.Activated:Connect(function()
            if stretchEnabled then
                applyStretchPreset(1)                       -- spento = X1
            else
                applyStretchPreset(_G.AmbitiousStretchPick or 2)
            end
            refreshStretchSelector()
            saveAmbitiousConfig()
        end)
    end

    local sArrow = Instance.new("TextButton")
    sArrow.Name = "StretchRezArrow"
    sArrow.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    sArrow.BackgroundTransparency = 0.18
    sArrow.BorderSizePixel = 0
    sArrow.Size = UDim2.new(0, 28, 0, 24)
    sArrow.Position = UDim2.new(1, -90, 0.5, -12)
    sArrow.Text = "\u{25B2}"
    sArrow.TextColor3 = COLORS.white
    sArrow.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    sArrow.TextStrokeTransparency = 0.3
    sArrow.TextSize = 15
    sArrow.Font = Enum.Font.GothamBold
    sArrow.AutoButtonColor = false
    sArrow.ZIndex = 8
    sArrow.Parent = row
    corner(sArrow, 7)
    stroke(sArrow, COLORS.strokeSoft, 1, 0.45)

    local sExpanded = false
    sArrow.Activated:Connect(function()
        sExpanded = not sExpanded
        _G._AmbitiousExpand(segHolder, sExpanded, 42, sArrow)
    end)

    refreshStretchSelector()
end
-- <<< STRETCH REZ: toggle + tendina END

-- ===== MOTION BLUR =====
do
    local function _startMotionBlur()
        if _motionBlurConn then pcall(function() _motionBlurConn:Disconnect() end); _motionBlurConn = nil end
        -- Crea o recupera il BlurEffect in Lighting
        if not _motionBlurEffect or not _motionBlurEffect.Parent then
            _motionBlurEffect = Lighting:FindFirstChildOfClass("BlurEffect")
            if not _motionBlurEffect then
                _motionBlurEffect = Instance.new("BlurEffect")
                _motionBlurEffect.Name = "AmbitiousMotionBlur"
            end
        end
        _motionBlurEffect.Size = 0
        _motionBlurEffect.Enabled = true
        _motionBlurEffect.Parent = Lighting
        local camera = Workspace.CurrentCamera
        local lastCFrame = camera.CFrame
        _motionBlurCurrentValue = 0
        _motionBlurConn = RunService.RenderStepped:Connect(function(deltaTime)
            if not motionBlurEnabled then
                if _motionBlurConn then pcall(function() _motionBlurConn:Disconnect() end); _motionBlurConn = nil end
                if _motionBlurEffect and _motionBlurEffect.Parent then
                    _motionBlurEffect.Size = 0
                    _motionBlurEffect.Enabled = false
                end
                return
            end
            local cam = Workspace.CurrentCamera
            if not cam then return end
            local currentCF = cam.CFrame
            local dot = currentCF.LookVector:Dot(lastCFrame.LookVector)
            local angleRad = math.acos(math.clamp(dot, -1, 1))
            local angleDeg = math.deg(angleRad)
            local speed = angleDeg * 20
            local targetBlur = math.min(speed, 7)
            _motionBlurCurrentValue = _motionBlurCurrentValue + (targetBlur - _motionBlurCurrentValue) * math.min(1, deltaTime * 10)
            if _motionBlurEffect and _motionBlurEffect.Parent then
                _motionBlurEffect.Size = _motionBlurCurrentValue
            end
            lastCFrame = currentCF
        end)
    end

    local function _stopMotionBlur()
        if _motionBlurConn then pcall(function() _motionBlurConn:Disconnect() end); _motionBlurConn = nil end
        if _motionBlurEffect and _motionBlurEffect.Parent then
            _motionBlurEffect.Size = 0
            _motionBlurEffect.Enabled = false
        end
        _motionBlurCurrentValue = 0
    end

    local row, setVisual = toggleRow(Utility, "Motion Blur", motionBlurEnabled, 15)
    _SV.setMotionBlurVisual = setVisual
    local _mblurBtn = row and row:FindFirstChild("ToggleButton")
    if _mblurBtn then
        _mblurBtn.Activated:Connect(function()
            motionBlurEnabled = not motionBlurEnabled
            if motionBlurEnabled then
                _startMotionBlur()
            else
                _stopMotionBlur()
            end
            if setVisual then setVisual(motionBlurEnabled) end
            saveAmbitiousConfig()
        end)
    end

    -- Ripristina lo stato al load
    if motionBlurEnabled then
        _startMotionBlur()
    end
end

-- ORDINE CAMERA: Stretch Rez (14) -> FOV (14) -> Motion Blur (15) -> No Cam Collision (16)
