    fovLabel.TextSize = 11
    fovLabel.Font = Enum.Font.GothamSemibold
    fovLabel.TextXAlignment = Enum.TextXAlignment.Left
    fovLabel.Size = UDim2.new(0.55, 0, 1, 0)
    fovLabel.Position = UDim2.new(0, 12, 0, 0)
    fovLabel.ZIndex = 8
