    -- Bridge per Reset All Settings / load config
    _G.AmbitiousFovValueBox = fovBox
    _G.AmbitiousRefreshFovValueBox = function()
        pcall(function() fovBox.Text = tostring(fovValue) end)
    end

    fovBox.FocusLost:Connect(function()
