          TweenService:Create(removeBtn, TweenInfo.new(0.1), {TextColor3 = Color3.fromRGB(255, 55, 55)}):Play()
        end)

        local capturedId = assetId
        removeBtn.MouseButton1Click:Connect(function()
          for j, v in ipairs(customBgIds) do
            if v == capturedId then table.remove(customBgIds, j) break end
          end
          if customBgSelected == capturedId then
            customBgSelected = nil
            applyBackground(1)
          end
          saveAmbitiousConfig()
          if customBgPickerGui and customBgPickerGui.Parent then
            local sf2 = customBgPickerGui:FindFirstChild("Frame") and customBgPickerGui.Frame:FindFirstChild("Scroll")
            if sf2 then rebuildCustomThumbs(sf2) end
          end
        end)

        -- Click per applicare (non copre area X)
