        thumbClick.Name = "Click"
        thumbClick.Size = UDim2.new(1, -26, 1, 0)
        thumbClick.BackgroundTransparency = 1
        thumbClick.Text = ""
        thumbClick.AutoButtonColor = false
        thumbClick.ZIndex = 6
        thumbClick.MouseEnter:Connect(function()
