        end)
        thumbClick.MouseLeave:Connect(function()
          TweenService:Create(thumbHolder, TweenInfo.new(0.12), {BackgroundColor3 = Color3.fromRGB(12, 12, 16)}):Play()
        end)
        thumbClick.MouseButton1Click:Connect(function()
          applyCustomBackground(capturedId)
          if customBgPickerGui and customBgPickerGui.Parent then
            local sf3 = customBgPickerGui:FindFirstChild("Frame") and customBgPickerGui.Frame:FindFirstChild("Scroll")
            if sf3 then
              for _, ch in ipairs(sf3:GetChildren()) do
                if ch.Name:sub(1,12) == "CustomThumb_" then
                  local img2 = ch:FindFirstChildOfClass("ImageLabel")
                  local cid = img2 and img2.Image:match("rbxassetid://(.+)")
                  local st2 = ch:FindFirstChildOfClass("UIStroke")
                  if st2 then
                    local sel2 = cid == capturedId
                    st2.Color = sel2 and Color3.fromRGB(255,255,255) or Color3.fromRGB(50,50,58)
                    st2.Thickness = sel2 and 1.8 or 1
                    st2.Transparency = sel2 and 0.05 or 0.5
                  end
                end
              end
            end
          end
        end)
        table.insert(_customThumbButtons, {holder = thumbHolder, id = assetId})
      end

      -- Pulsante Add SEMPRE IN FONDO (LayoutOrder = n+1), scorre con i thumbnail
