      fpClose.BackgroundTransparency = 0.1
      fpClose.BorderSizePixel = 0
      fpClose.Text = "X"
      fpClose.TextColor3 = Color3.fromRGB(255, 255, 255)
      fpClose.Font = Enum.Font.GothamBlack
      fpClose.TextSize = 14
      fpClose.AutoButtonColor = false
      fpClose.ZIndex = 4
      fpClose.Parent = fpBar
      corner(fpClose, 10)
      stroke(fpClose, Color3.fromRGB(90, 90, 105), 1, 0.4)

      fpClose.MouseEnter:Connect(function()
        tween(fpClose, {BackgroundColor3 = Color3.fromRGB(180, 50, 50)}, 0.12)
      end)
      fpClose.MouseLeave:Connect(function()
        tween(fpClose, {BackgroundColor3 = Color3.fromRGB(25, 25, 28)}, 0.12)
      end)
      fpClose.Activated:Connect(closeFontPicker)

      local fpScroll = Instance.new("ScrollingFrame")
      fpScroll.Name = "Scroll"
      fpScroll.Size = UDim2.new(1, -16, 1, -64)
      fpScroll.Position = UDim2.new(0, 8, 0, 56)
      fpScroll.BackgroundTransparency = 1
      fpScroll.BorderSizePixel = 0
      fpScroll.ScrollBarThickness = 4
      fpScroll.ScrollBarImageColor3 = Color3.fromRGB(80, 80, 90)
      fpScroll.ZIndex = 3
      fpScroll.Parent = fpFrame

      -- RIUSO DELLE CARD (niente UIGridLayout)
      -- I font sono centinaia: creare una card per ognuno vuol dire
      -- migliaia di istanze in un colpo solo, ed e' quello lo scatto
      -- all'apertura. Qui le card create sono solo quelle che entrano
      -- nello schermo piu' una riga di margine: scorrendo non se ne
      -- creano altre, si riscrive il contenuto di quelle che ci sono.
      -- La griglia viene calcolata a mano perche' un UIGridLayout
      -- pretenderebbe che tutte le celle esistessero davvero: le misure
      -- pero' sono identiche a quelle dello Sky Picker (108 + 10 di gap).
      local FP_COLS, FP_CELL, FP_GAP = 3, 108, 10
      local FP_STEP = FP_CELL + FP_GAP
      local fpList = _G.AmbitiousFonts.list()
      local fpRows = math.ceil(#fpList / FP_COLS)
      -- L'altezza del canvas e' quella che avrebbero TUTTE le righe: la
      -- barra di scorrimento resta giusta anche se le card non esistono.
      fpScroll.CanvasSize = UDim2.new(0, 0, 0, 16 + fpRows * FP_STEP)

      local fpPool = {}

      local function fpEntryOf(card)
        local idx = card:GetAttribute("FontIdx")
        return idx and fpList[idx] or nil
      end

      local function fpPaint()
        for _, c in ipairs(fpPool) do
          local e = fpEntryOf(c)
          local sel = (e ~= nil and _G.AmbitiousFontChoice == e.key)
          local st = c:FindFirstChildOfClass("UIStroke")
          if st then
            tween(st, {
              Color = sel and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(50, 50, 58),
              Transparency = sel and 0 or 0.55,
              Thickness = sel and 2.4 or 1.2,
            }, 0.12)
          end
        end
      end

      local function fpBind(card, idx)
        local e = fpList[idx]
        if not e then
          card:SetAttribute("FontIdx", nil)
          card.Visible = false
          return
        end
        local row = math.floor((idx - 1) / FP_COLS)
        local col = (idx - 1) % FP_COLS
        card.Position = UDim2.new(0, 10 + col * FP_STEP, 0, 8 + row * FP_STEP)
        card:SetAttribute("FontIdx", idx)
        local prv = card:FindFirstChild("Preview")
        if prv then
          if e.font then prv.FontFace = e.font else prv.Font = Enum.Font.GothamBlack end
        end
        local nl = card:FindFirstChild("FontName")
        if nl then nl.Text = e.label end
        card.Visible = true
      end

      -- Quante card servono davvero: le righe visibili piu' due di
      -- margine, cosi' scorrendo non si vede mai un buco.
      for j = 1, (math.ceil(456 / FP_STEP) + 2) * FP_COLS do
        local card = Instance.new("TextButton")
        card.Name = "FontCard_" .. tostring(j)
        card.Size = UDim2.new(0, FP_CELL, 0, FP_CELL)
        card.BackgroundColor3 = Color3.fromRGB(14, 14, 18)
        card.BackgroundTransparency = 0
        card.BorderSizePixel = 0
        card.Text = ""
        card.AutoButtonColor = false
        card.Visible = false
        card.ZIndex = 4
        card.ClipsDescendants = true
        card.Parent = fpScroll
        corner(card, 18)

        local cardStroke = Instance.new("UIStroke")
        cardStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        cardStroke.Color = Color3.fromRGB(50, 50, 58)
        cardStroke.Thickness = 1.2
        cardStroke.Transparency = 0.55
        cardStroke.Parent = card

        -- ANTEPRIMA. L'attributo la mette fuori dalla portata del motore
        -- dei font: senza, il font appena scelto verrebbe applicato anche
        -- a lei — sta dentro la hub come tutto il resto — e i campioni
        -- diventerebbero tutti uguali.
        local prv = Instance.new("TextLabel")
        prv.Name = "Preview"
        prv.BackgroundTransparency = 1
        prv.Size = UDim2.new(1, -10, 0, 58)
        prv.Position = UDim2.new(0, 5, 0, 8)
        prv.Text = "Aa"
        prv.TextColor3 = Color3.fromRGB(255, 255, 255)
        prv.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        prv.TextStrokeTransparency = 0.4
        prv.TextSize = 34
        prv.Font = Enum.Font.GothamBlack
        prv.ZIndex = 5
        prv.Parent = card
        prv:SetAttribute("AmbFontLock", true)

        local nameLbl = Instance.new("TextLabel")
        nameLbl.Name = "FontName"
        nameLbl.Size = UDim2.new(1, -8, 0, 32)
        nameLbl.Position = UDim2.new(0, 4, 1, -36)
        nameLbl.BackgroundTransparency = 1
        nameLbl.Text = ""
        nameLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        nameLbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        nameLbl.TextStrokeTransparency = 0.4
        nameLbl.Font = Enum.Font.GothamBlack
        nameLbl.TextSize = 9
        nameLbl.TextWrapped = true
        nameLbl.ZIndex = 6
        nameLbl.Parent = card
        nameLbl:SetAttribute("AmbFontLock", true)

        card.MouseEnter:Connect(function()
          tween(cardStroke, {Transparency = 0, Thickness = 2.4}, 0.12)
          tween(prv, {TextSize = 40}, 0.12)
        end)
        card.MouseLeave:Connect(function()
          local e = fpEntryOf(card)
          local sel = (e ~= nil and _G.AmbitiousFontChoice == e.key)
          tween(cardStroke, {
            Transparency = sel and 0 or 0.55,
            Thickness = sel and 2.4 or 1.2,
          }, 0.12)
          tween(prv, {TextSize = 34}, 0.12)
        end)

        card.Activated:Connect(function()
          local e = fpEntryOf(card)
          if not e then return end
          _G.AmbitiousFonts.set(e.key)
          fpPaint()
        end)

        fpPool[#fpPool + 1] = card
      end

      -- Si ridisegna solo quando cambia la prima riga visibile: durante
      -- uno scorrimento fluido la maggior parte dei frame non fa nulla.
      local fpFirstRow = -1
      local function fpRender()
        local first = math.max(0, math.floor((fpScroll.CanvasPosition.Y - 8) / FP_STEP) - 1)
        if first == fpFirstRow then return end
        fpFirstRow = first
        for j, card in ipairs(fpPool) do
          fpBind(card, first * FP_COLS + j)
        end
        fpPaint()
      end
      fpScroll:GetPropertyChangedSignal("CanvasPosition"):Connect(fpRender)
      fpRender()

      fpBack.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
          closeFontPicker()
        end
      end)

      fpFrame.Size = UDim2.new(0, 0, 0, 0)
      fpFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
      TweenService:Create(fpFrame, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Size = UDim2.new(0, 380, 0, 520),
        Position = UDim2.new(0.5, -190, 0.5, -260)
      }):Play()
    end)
  end)()
  -- ===== FINE CUSTOM FONTS ROW =====

  -- ===== TITLE STYLE ROW =====
  -- >>> TITLE STYLE BEGIN
  -- Stessa impaginazione della riga GUI Scale: etichetta a sinistra, le due
  -- frecce ai lati e in mezzo il riquadro del valore. Qui pero' il valore
  -- non e' un numero ma l'anteprima vera del logo, cosi' si vede cosa si
  -- sta scegliendo senza doverlo applicare.
  -- Stesso LayoutOrder della Tab Position e creata subito dopo: a parita'
  -- di LayoutOrder il UIListLayout rispetta l'ordine di inserimento, quindi
  -- finisce esattamente sotto.
  ;(function()
    local N = #_G.AmbitiousTitleStyles

    -- Riga alta come tutte le altre: il logo sta in mezzo alle due frecce,
    -- senza riquadro attorno.
    local tsRow = baseRow(Settings, "Title Style", 3)
    tsRow.Size = UDim2.new(1, -4, 0, 42)
    local tsLabel = tsRow:FindFirstChild("Label")
    if tsLabel then tsLabel.Size = UDim2.new(1, -162, 1, 0) end

    local tsPrev = Instance.new("TextButton")
    tsPrev.Name = "TitleStylePrev"
    tsPrev.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    tsPrev.BackgroundTransparency = 0.1
    tsPrev.BorderSizePixel = 0
    tsPrev.Text = "\u{25C0}"
    tsPrev.TextColor3 = Color3.fromRGB(245, 245, 255)
    tsPrev.TextSize = 12
    tsPrev.Font = Enum.Font.GothamBlack
    tsPrev.AutoButtonColor = false
    -- Bottoncini quadrati come quelli dello stepper: alti quanto il
    -- riquadro sembravano enormi, l'anteprima e' quella che deve risaltare.
    tsPrev.Size = UDim2.new(0, 24, 0, 24)
    tsPrev.Position = UDim2.new(1, -146, 0.5, -12)
    tsPrev.ZIndex = 6
    tsPrev.Parent = tsRow
    corner(tsPrev, 7)
    stroke(tsPrev, COLORS.strokeSoft, 1, 0.5)

    -- Niente contenitore: il logo sta direttamente in mezzo alle due
    -- frecce. Il Frame resta solo come area di ritaglio per lo zoom
    -- (ClipsDescendants), ma e' trasparente e senza bordo, e occupa TUTTO
    -- lo spazio tra i due bottoni invece dei 130px fissi di prima: cosi'
    -- non avanza spazio vuoto ai lati e il logo viene piu' grande.
    local tsBox = Instance.new("Frame")
    tsBox.Name = "TitleStylePreview"
    tsBox.BackgroundTransparency = 1
    tsBox.BorderSizePixel = 0
    tsBox.Size = UDim2.new(0, 82, 0, 36)
    tsBox.Position = UDim2.new(1, -118, 0.5, -18)
    tsBox.ClipsDescendants = true
    tsBox.ZIndex = 6
    tsBox.Parent = tsRow

    local tsImg = Instance.new("ImageLabel")
    tsImg.Name = "Img"
    tsImg.BackgroundTransparency = 1
    tsImg.AnchorPoint = Vector2.new(0.5, 0.5)
    tsImg.Position = UDim2.new(0.5, 0, 0.5, 0)
    tsImg.Size = UDim2.new(1, 0, 1, 0)
    tsImg.ScaleType = Enum.ScaleType.Fit
    tsImg.ZIndex = 7
    tsImg.Parent = tsBox

    local tsNext = Instance.new("TextButton")
    tsNext.Name = "TitleStyleNext"
    tsNext.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    tsNext.BackgroundTransparency = 0.1
    tsNext.BorderSizePixel = 0
    tsNext.Text = "\u{25B6}"
    tsNext.TextColor3 = Color3.fromRGB(245, 245, 255)
    tsNext.TextSize = 12
    tsNext.Font = Enum.Font.GothamBlack
    tsNext.AutoButtonColor = false
    tsNext.Size = UDim2.new(0, 24, 0, 24)
    tsNext.Position = UDim2.new(1, -36, 0.5, -12)
    tsNext.ZIndex = 6
    tsNext.Parent = tsRow
    corner(tsNext, 7)
    stroke(tsNext, COLORS.strokeSoft, 1, 0.5)

    local function refreshTitleStyleSelector()
      local idx = math.clamp(math.floor(tonumber(_G.AmbitiousTitleStyle) or 1), 1, N)
      local st = _G.AmbitiousTitleStyles[idx]
      if st then
        tsImg.Image = st.image
        local k = tonumber(st.prev) or 1
        tsImg.Size = UDim2.new(k, 0, k, 0)
      end
    end
    _G.AmbitiousRefreshTitleStyleSelector = refreshTitleStyleSelector

    -- Le frecce girano in tondo: dall'ultimo si torna al primo.
    local function step(d)
      local idx = math.clamp(math.floor(tonumber(_G.AmbitiousTitleStyle) or 1), 1, N)
      idx = ((idx - 1 + d) % N) + 1
      if _G.AmbitiousApplyTitleStyle then _G.AmbitiousApplyTitleStyle(idx) end
      refreshTitleStyleSelector()
      saveAmbitiousConfig()
    end

    tsPrev.MouseButton1Click:Connect(function() step(-1) end)
    tsNext.MouseButton1Click:Connect(function() step(1) end)

    refreshTitleStyleSelector()
  end)()
  -- <<< TITLE STYLE END
  -- ===== FINE TITLE STYLE ROW =====


  function stepperRow(parent, labelText, defaultValue, order, callback, minValue, maxValue)
    local row = Instance.new("Frame")
    row.Name = labelText
    row.BackgroundColor3 = COLORS.row
    row.BackgroundTransparency = 0.22
    row.Size = UDim2.new(1, -4, 0, 42)
    row.BorderSizePixel = 0
    row.LayoutOrder = order
    row.ZIndex = 4
    row.Parent = parent
    corner(row, 10)
    stroke(row, COLORS.strokeSoft, 1.15, 0.32)

    local label = Instance.new("TextLabel")
    label.Name = "Label"
    label.BackgroundTransparency = 1
    label.Text = labelText
    label.TextColor3 = Color3.fromRGB(245, 245, 255)
    label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    label.TextStrokeTransparency = 0.25
    label.TextSize = 11
    label.Font = Enum.Font.GothamMedium
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Position = UDim2.new(0, 12, 0, 0)
    label.Size = UDim2.new(1, -155, 1, 0)
    label.ZIndex = 5
    label.Parent = row

    local value = defaultValue
    local minus = Instance.new("TextButton")
    minus.Name = "Minus"
    minus.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    minus.BackgroundTransparency = 0.1
    minus.BorderSizePixel = 0
    minus.Text = "-"
    minus.TextColor3 = Color3.fromRGB(245, 245, 255)
    minus.TextSize = 14
    minus.Font = Enum.Font.GothamBlack
    minus.AutoButtonColor = false
    minus.Size = UDim2.new(0, 28, 0, 26)
    minus.Position = UDim2.new(1, -118, 0.5, -13)
    minus.ZIndex = 6
    minus.Parent = row
    corner(minus, 7)
    stroke(minus, COLORS.strokeSoft, 1, 0.5)

    local valueBox = Instance.new("TextLabel")
    valueBox.Name = "Value"
    valueBox.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    valueBox.BackgroundTransparency = 0.05
    valueBox.BorderSizePixel = 0
    valueBox.Text = string.format("%.2f", value)
    valueBox.TextColor3 = Color3.fromRGB(245, 245, 255)
    valueBox.TextSize = 13
    valueBox.Font = Enum.Font.GothamBlack
    valueBox.TextXAlignment = Enum.TextXAlignment.Center
    valueBox.Size = UDim2.new(0, 48, 0, 26)
    valueBox.Position = UDim2.new(1, -84, 0.5, -13)
    valueBox.ZIndex = 6
    valueBox.Parent = row
    corner(valueBox, 7)
    stroke(valueBox, COLORS.strokeSoft, 1, 0.5)

    local plus = Instance.new("TextButton")
    plus.Name = "Plus"
    plus.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    plus.BackgroundTransparency = 0.1
    plus.BorderSizePixel = 0
    plus.Text = "+"
    plus.TextColor3 = Color3.fromRGB(245, 245, 255)
    plus.TextSize = 14
    plus.Font = Enum.Font.GothamBlack
    plus.AutoButtonColor = false
    plus.Size = UDim2.new(0, 28, 0, 26)
    plus.Position = UDim2.new(1, -30, 0.5, -13)
    plus.ZIndex = 6
    plus.Parent = row
    corner(plus, 7)
    stroke(plus, COLORS.strokeSoft, 1, 0.5)

    local function setValue(nextValue)
      value = math.clamp(math.floor((nextValue * 100) + 0.5) / 100, minValue or 0.50, maxValue or 1.50)
      valueBox.Text = string.format("%.2f", value)
      if callback then callback(value) end
    end

    minus.MouseButton1Click:Connect(function()
      setValue(value - 0.05)
    end)
    plus.MouseButton1Click:Connect(function()
      setValue(value + 0.05)
    end)
    return row
  end

  stepperRow(Settings, "GUI Scale", ambitiousGuiScaleValue, 4, function(v)
