    ColorSequenceKeypoint.new(1.00, Color3.fromRGB(50, 50, 60)),
})

-- Funzione per ruotare le tonalità (hue) di un colore
local function shiftHue(color, offset)
    local r, g, b = color.R, color.G, color.B
    local max = math.max(r, g, b)
    local min = math.min(r, g, b)
    local h, s, v
    v = max
    local d = max - min
    s = (max == 0) and 0 or d / max
    if max == min then
        h = 0
    else
        if max == r then
            h = (g - b) / d + (g < b and 6 or 0)
        elseif max == g then
            h = (b - r) / d + 2
        else
            h = (r - g) / d + 4
        end
        h = h / 6
    end
    h = (h + offset) % 1
    local function hueToRgb(p, q, t)
        if t < 0 then t = t + 1 end
        if t > 1 then t = t - 1 end
        if t < 1/6 then return p + (q - p) * 6 * t end
        if t < 1/2 then return q end
        if t < 2/3 then return p + (q - p) * (2/3 - t) * 6 end
        return p
    end
    if s == 0 then
        return Color3.fromRGB(v, v, v)
    end
    local q = v * (1 - s * (1 - (h * 6 % 1)))
    local p = v * (1 - s)
    local tr = v
    local tg = v
    local tb = v
    if h < 1/6 then
        tr = v
        tg = v * (1 - s * (1 - (h * 6)))
        tb = v * (1 - s)
    elseif h < 1/3 then
        tr = v * (1 - s * (h * 6 - 1))
        tg = v
        tb = v * (1 - s)
    elseif h < 1/2 then
        tr = v * (1 - s)
        tg = v
        tb = v * (1 - s * (1 - (h * 6 - 2)))
    elseif h < 2/3 then
        tr = v * (1 - s)
        tg = v * (1 - s * (h * 6 - 3))
        tb = v
    elseif h < 5/6 then
        tr = v * (1 - s * (1 - (h * 6 - 4)))
        tg = v * (1 - s)
        tb = v
    else
        tr = v
        tg = v * (1 - s)
        tb = v * (1 - s * (h * 6 - 5))
    end
    return Color3.new(tr, tg, tb)
end

-- Animazione: cambia i colori lentamente
task.spawn(function()
    local hueOffset = 0
    local speed = 0.002  -- velocità lenta per effetto morbido
    while skipBtn and skipBtn.Parent do
        hueOffset = (hueOffset + speed) % 1
        
        -- Colori base (galattici) con tonalità spostata
        local c1 = shiftHue(Color3.fromRGB(200, 200, 210), hueOffset)
        local c2 = shiftHue(Color3.fromRGB(120, 120, 130), hueOffset)
        local c3 = shiftHue(Color3.fromRGB(50, 50, 60), hueOffset)
        
        grad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0.00, c1),
            ColorSequenceKeypoint.new(0.50, c2),
            ColorSequenceKeypoint.new(1.00, c3),
        })
        
        task.wait(0.05)
    end
end)

